/// <reference path="angular.js" />
$.mobile.ajaxEnabled = false;
$.mobile.linkBindingEnabled = false;
$.mobile.hashListeningEnabled = false;
$.mobile.pushStateEnabled = false;
//$.mobile.changePage.defaults.changeHash = false;
var app;
(function () {
    app = angular.module("app", ['lazy-scroll', 'ui.router', 'ngCookies',
        'pascalprecht.translate', 'angular-loading-bar', 'angular-growl', 'ui.bootstrap', 'dialogs',
        'itg-control', 'ngMessages',
        'ui.select', 'gridster', 'nvd3', 'as.sortable',
        'CRUDServices', 'mainFactory', 'ChartFactory', 'DashboardServices',
        'ui.tree', 'multiselect-searchtree', 'tree-folder-view',
        'ui.mention', 'easypiechart', 'ngFabForm',
        'ng-gritter', 'chosen.angular', 'ngSanitize',
        'mgo-angular-wizard', 'textAngular', 'ngMap',
        'angularFileUpload', 'ngTagsInput', 'ngWYSIWYG', 'jqgridFactory', 'ngAvatar'
    ]);
    //Ngôn ngữ
    //cập nhật phiên bản mới: cho phép load từng phần thay vì load toàn bộ
    app.config(['$translateProvider', '$translatePartialLoaderProvider',
        function ($translateProvider, $translatePartialLoaderProvider) {
            $translatePartialLoaderProvider.addPart('system');
            //$translateProvider.preferredLanguage(localStorage.language);
            $translateProvider.useLoader('$translatePartialLoader', {
                urlTemplate: '/ConfigAPI/api/Translate/TranslationsConfigAPI/GetLanguage?lang={lang}&form={part}',
            });
            $translateProvider.useSanitizeValueStrategy('sanitizeParameters');

        }]);
    //popup thong bao khi luu, sua, xoa thanh cong
    app.config(['growlProvider', function (growlProvider) {
        growlProvider.globalDisableCountDown(true);
        growlProvider.globalPosition('top-center');
        growlProvider.globalTimeToLive(5500);
    }]);
    app.config(['$provide', function ($provide) {
        $provide.decorator('$state', ['$q', '$delegate', '$window', '$http', '$location', 'growl',
            function ($q, $delegate, $window, $http, $location, growl) {
                var extended = {
                    //chuyển hướng cửa sổ giao diện đối với báo cáo dạng bảng kê (mở chi tiết phiếu)
                    openDetail: function (paramsData, overide_yn) {
                        growl.destroy();
                        //có bật nhiều cửa sổ lên cùng lúc hay không
                        var type = overide_yn ? '' : 'popup';

                        var arrayMenu = JSON.parse(localStorage.getItem('user_role'));
                        var stateName = '';

                        //điều hướng đến phiếu khi xem chi tiết bc
                        switch (paramsData['ma_ct']) {
                            case "PNE": {
                                paramsData['ma_ct'] = 'PXE';
                                paramsData['stt_rec'] = paramsData['stt_rec'].replace('PNE', 'PXE');
                                break;
                            }
                            case "PNF": {
                                //nếu _ma_ct0 <> '' => phiếu xuất kiêm nhập
                                if (JSON.toString(paramsData['stt_rec_dc']) != "") {
                                    if (paramsData['stt_rec'].substring(0, 17) == paramsData['stt_rec_dc'].substring(0, 17)) {
                                        paramsData['ma_ct'] = 'PXB';
                                        paramsData['stt_rec'] = paramsData['stt_rec'].replace('PNF', 'PXB');
                                    }
                                }
                                break;
                            }
                            default: break;
                        }

                        //dựa vào mã chứng từ để lấy state tiếp theo
                        var arrTemp = JSON.GetItemsInArray('state', paramsData['ma_ct'], arrayMenu);
                        if (arrTemp == "" || arrTemp == undefined) {
                            console.warn('Chưa khai báo cột ma_ct trong gridconfig');
                            return false;
                        }
                        if (arrTemp.length > 0) {
                            var resNext = JSON.GetItemsInArray('menuid', arrTemp[0].menuid0, arrayMenu);
                            stateName = resNext[0]['state'];
                        }

                        var toState = JSON.GetItemsInArray('state', stateName, arrayMenu);

                        if (toState.length > 0) {
                            var hostURL = $location.$$absUrl;
                            var hostURLTemp = hostURL.split('#');
                            var linkURL = hostURLTemp[0] + '#' + toState[0].url;
                            var arr_role = JSON.parse(localStorage["role_detail"]);
                            arr_role = arr_role == undefined ? [] : arr_role;
                            localStorage.removeItem('ct');
                            if (!toState[0].menu_yn) {
                                var parentState = JSON.GetItemsInArray('menuid0', toState[0].menuid, arrayMenu);
                                var roleState = JSON.GetItemsInArray('state', parentState[0].state, arr_role);
                                if (parentState.length > 0 && roleState.length == 0) {
                                    getRoleUser(parentState[0].state).then(function (resVal) {
                                        arr_role.push(resVal);
                                        var ct = {
                                            ct: paramsData,
                                            add_yn: false,
                                            ma_ct: paramsData.ma_ct,
                                            from: "report",
                                            role: resVal,
                                            hide_menu_yn: true,
                                            search: {}
                                        }
                                        localStorage.setItem('ct', JSON.stringify(ct));
                                        localStorage.setItem("role_detail", JSON.stringify(arr_role));
                                        PopupWindow(linkURL, '', $window, 1366, 600, ct);
                                    })
                                } else {
                                    var ct = {
                                        ct: paramsData,
                                        add_yn: false,
                                        ma_ct: paramsData.ma_ct,
                                        from: "report",
                                        role: roleState[0],
                                        hide_menu_yn: true,
                                        search: {}
                                    }
                                    localStorage.setItem('ct', JSON.stringify(ct));
                                    localStorage.setItem("role_detail", JSON.stringify(arr_role));
                                    PopupWindow(linkURL, type, $window, 1366, 600, ct);
                                }
                            }
                            else {
                                if (parentState.length > 0) {
                                    linkURL = hostURLTemp[0] + '#' + parentState[0].url;
                                }
                                var roleState = JSON.GetItemsInArray('state', toState[0].state, arr_role);
                                if (parentState.length > 0 && roleState.length == 0) {
                                    getRoleUser(parentState[0].state).then(function (resVal) {
                                        var arr_role = JSON.parse(localStorage["role_detail"]);
                                        arr_role.push(resVal);
                                        var ct = {
                                            ct: paramsData,
                                            add_yn: false,
                                            ma_ct: paramsData.ma_ct,
                                            from: "report",
                                            role: resVal,
                                            hide_menu_yn: true,
                                            search: {}
                                        }
                                        localStorage.setItem('ct', JSON.stringify(ct));
                                        localStorage.setItem("role_detail", JSON.stringify(arr_role));
                                        PopupWindow(linkURL, type, $window, 1366, 600, ct);
                                    })
                                } else {
                                    var ct = {
                                        ct: paramsData,
                                        add_yn: false,
                                        ma_ct: paramsData.ma_ct,
                                        from: "report",
                                        role: roleState[0],
                                        hide_menu_yn: true,
                                        search: {}
                                    }
                                    localStorage.setItem('ct', JSON.stringify(ct));
                                    localStorage.setItem("role_detail", JSON.stringify(arr_role));

                                    PopupWindow(linkURL, type, $window, 1366, 600, ct);
                                }
                            }
                        } else {
                            growl.info('ERROR_NOT_EXISTS_DB');
                        }
                        function getRoleUser(name) {
                            var defer = $q.defer();
                            var arr_role = JSON.parse(localStorage["role_detail"]);
                            arr_role = arr_role == undefined ? [] : arr_role;
                            var index = JSON.CheckExistInArray('state', name, arr_role);
                            if (index >= 0) {
                                //nếu là is_admin hoặc super admin thì set các quyền mặc định
                                if (localStorage.is_admin == "1" || localStorage.is_super == "1") {
                                    var default_role = {
                                        r_access: true,
                                        r_add: true,
                                        r_approve: true,
                                        r_delete: true,
                                        r_edit: true,
                                        r_export: true,
                                        r_import: true,
                                        r_modify_all: true,
                                        r_print: true,
                                        r_view_all: true
                                    }
                                    arr_role[index] = Object.assign(arr_role[index], default_role);
                                }
                                defer.resolve(arr_role[index]);
                                return defer.promise;
                            }
                            else {
                                return $http({
                                    method: 'GET', url: '/ExtenAPI/api/LVRBaseExtention/ReportBaseExtentionAPI/GetRoleDetail/',
                                    params: { state: name },
                                    headers: {
                                        'Token': localStorage.token,
                                        'state': name,
                                        'user_name': localStorage.user_name,
                                        'user_id': localStorage.user_id,
                                        'lang': localStorage.language,
                                        'ma_dvcs': '',
                                        'user_id0': localStorage.user_id,
                                        'project_id': '',
                                        'list_id_data': '',
                                        'module': localStorage.module
                                    }
                                }).then(function (datares) {
                                    defer.resolve(datares.data.Result);
                                    return defer.promise;
                                });
                            };
                        }
                    },
                    openDetailOverview: function (paramsData, toState) {
                        delete paramsData.parent;
                        delete paramsData.children;
                        var data = {
                            ct: paramsData,
                            add_yn: false,
                            ma_ct: '', //paramsData.ma_ct,
                            from: "report",
                            role: {}, // roleState[0],
                            hide_menu_yn: true,
                            search: {}
                        }
                        var hostURL = $location.$$absUrl;
                        var hostURLTemp = hostURL.split('#');
                        var arrayMenu = JSON.parse(localStorage.getItem('user_role'));
                        var itemState = JSON.GetItemsInArray('state', toState, arrayMenu);
                        var arr_role = JSON.parse(localStorage["role_detail"]);
                        arr_role = arr_role == undefined ? [] : arr_role;
                        var linkURL = hostURLTemp[0] + '#' + itemState[0].url;
                        localStorage.setItem('ct', JSON.stringify(data));
                        localStorage.setItem("role_detail", JSON.stringify(arr_role));
                        PopupWindow(linkURL, 'popup', $window, 1366, 600, data);
                    }
                };
                function PopupWindow(url, title, window, w, h, paramsct) {
                    //Top của window popup sẽ bằng chiều cao màn hình - đi chiều cao của window popup chia cho 2, cộng vị trí trên cùng của hàn hình
                    var y = window.screen.height / 2 - (h / 2) + window.screenY;
                    //Left của window popup sẽ bằng chiều rộng màn hình - đi chiều rộng của window popup chia cho 2, cộng vị trí trên cùng của hàn hình
                    var x = window.screen.width / 2 - (w / 2) + window.screenX;

                    var popupWin = window.open(url, title,
                        "toolbar=no, location=no, directories=no, status=no, menubar=no,scrollbars=no, resizable=no, copyhistory=no, width=" + w + ", height=" + h + ", top=" + y + ", left=" + x + "");
                    popupWin.moveTo(x, y);
                    popupWin.focus();
                    popupWin.sessionStorage["paramsct"] = JSON.stringify(paramsct);
                }

                angular.extend($delegate, extended);
                return $delegate;
            }]);
    }]);
    ////config default for chosen directive
    app.config(['chosenProvider', function (chosenProvider) {
        //song ngữ cấu hình trong bảng sys_languages (form: system)
        chosenProvider.setOption({
            no_results_text: 'no_results_text',
            placeholder_text_multiple: 'placeholder_text_multiple',
            placeholder_text: 'placeholder_text',
            allow_single_deselect: true //hiển thị dấu (X) để xóa giá trị được chọn
        });
    }]);

    //kiểm soát việc đang có api request
    app.factory('httpInterceptor', ['$q', '$rootScope', function ($q, $rootScope) {
        var loadingCount = 0;
        return {
            request: function (config) {
                if (++loadingCount === 1) {
                    $rootScope.$broadcast('loading:progress');
                    if (config.method.includes('GET') && config.url.includes('/api/')) {
                        localStorage['api_progress'] = config.url;
                    }
                }
                return config || $q.when(config);
            },
            response: function (response) {
                if (--loadingCount === 0) {
                    $rootScope.$broadcast('loading:finish');
                    localStorage['api_progress'] = '';
                }
                return response || $q.when(response);
            },
            responseError: function (response) {
                if (--loadingCount === 0) {
                    $rootScope.$broadcast('loading:finish');
                    localStorage['api_progress'] = 'ERROR';
                }
                return $q.reject(response);
            }
        };
    }
    ]).config(['$httpProvider', function ($httpProvider) {
        $httpProvider.interceptors.push('httpInterceptor');
    }]);
    //Điều hướng
    app.config(['$qProvider', function ($qProvider) {
        $qProvider.errorOnUnhandledRejections(false);
    }]);
    //Gán Module truy cập
    app.constant('Module', 'ERP');

    //tạo $stateProvider tự động, cấu hình trong bảng: web_syscommand, command_bshub
    app.provider('runtimeStates', ['$stateProvider', function runtimeStates($stateProvider) {
        this.$get = ['$q', '$timeout', '$state', '$http', function ($q, $timeout, $state, $http) {
            return {
                //tạo state tự động
                /*Obejct = {
                   name: '',
                   state: '',
                   templateUrl: '',
                   url: '',
                   ...
                  } */
                //tạo state từ một object
                //addState: function (object, state) {
                //    $stateProvider.state(object, state);
                //},
                //tạo state từ một danh sách phân quyền
                addListState: function (array_state) {
                    var _this = this;
                    //tạo biến lưu trữ để truyền dữ liệu giữa các $state
                    for (var i = 0; i < array_state.length; i++) {
                        array_state[i].params = { params: '' };   //khởi tạo gán mặc định
                        $stateProvider.state(array_state[i], array_state[i].state);
                    }

                    /////////////////
                    if (localStorage.newState != '' && localStorage.newState != undefined && localStorage.newState != 'undefined') {
                        $state.go(localStorage.newState, {});
                        localStorage.newState = undefined;
                    } else {
                        localStorage.newState = undefined;
                        var x = localStorage.stateLast == '' ? null : JSON.parse(localStorage.stateLast);
                        if (x === null) {
                            if (localStorage.token === null) {
                                window.location.href = "/Account/Login";
                            }
                            else {
                                var role_access = JSON.parse(localStorage.user_role);
                                var check_item = localStorage.user_role.indexOf('"state":"OverviewDisplay"') !== -1;
                                //nếu  đc phân quyền Oveview, thì chuyển page về overview
                                if (check_item) {
                                    $state.go("OverviewDisplay");
                                }
                                else if (role_access.length > 0) {
                                    if (localStorage.user_role.indexOf("SYS_a0_00") != -1)
                                        $state.go("Dashboards");
                                    else {
                                        var toState = {};
                                        //lấy menu là lá đầu tiên trên cây phân quyền
                                        for (var i = 0; i < role_access.length; i++) {
                                            if (role_access[i].menuid !== '' && role_access[i].isleaf) {
                                                toState = role_access[i];
                                                break;
                                            }
                                        }
                                        if (toState.state) {
                                            //từ menu đầu tiên lấy đc dựa vào session
                                            //nếu chưa lưu biến gì thì kiểm tra và điều hướng cho phù hợp
                                            if (!sessionStorage.getItem('paramsLast')) {
                                                for (var i = 0; i < role_access.length; i++) {
                                                    if (role_access[i].menuid0 == toState.menuid && role_access[i].url != "#") {
                                                        $state.go(role_access[i].state);
                                                        break;
                                                    }
                                                }
                                            } else {
                                                $state.go(toState.state);
                                            }
                                        }
                                        else growl.error("validate_notvalid");
                                    }
                                }
                            }
                        }
                        else {
                            var cookie = x;// JSON.parse(x);
                            //kiểm tra nếu laststate không có trong danh sách menu 
                            //đc phân quyền của user đang login
                            var check_exists = localStorage.user_role.indexOf('"state":"' + cookie.name + '"') !== -1;
                            var current_url = document.URL.split('#')[1];
                            //cùng user_name trước đó thì mới hỏi xác nhận
                            if (cookie.user_name === localStorage.user_name &&
                                cookie.token === localStorage.token &&
                                cookie.state != "OverviewDisplay" && check_exists) {
                                //kiểm tra trường hợp người dùng đang mở nhiều tab, mỗi tab lại đang focus vào view khác nhau
                                if (current_url == cookie.url) {
                                    //$state.go(cookie.state);
                                }
                                else {
                                    var role_access = JSON.parse(localStorage.user_role);
                                    var exist = JSON.CheckExistInArray('url', current_url, role_access);
                                    if (exist >= 0) {
                                        var this_state = role_access[exist];
                                        $state.go(this_state.state);
                                    }
                                }
                            }
                            else {
                                //trường hợp mặc định,
                                var role_access = JSON.parse(localStorage.user_role);
                                var check_exits = localStorage.user_role.indexOf('"state":"OverviewDisplay"') !== -1;
                                if (check_exits) {
                                    $state.go("OverviewDisplay");
                                }
                                else
                                    if (role_access.length > 0) {
                                        var toState = role_access[0].state;
                                        for (var i = 0; i < role_access.length; i++) {
                                            if (role_access[i].menuid !== '' && role_access[i].isleaf) {
                                                toState = role_access[i];
                                                break;
                                            }
                                        }
                                        $state.go(toState.state);
                                    }
                            }
                        }
                    }
                },

                //đọc cookies từ store
                readCookie: function (name) {
                    var nameEQ = name + "=";
                    var ca = document.cookie.split(';');
                    for (var i = 0; i < ca.length; i++) {
                        var c = ca[i];
                        while (c.charAt(0) == ' ') c = c.substring(1, c.length);
                        if (c.indexOf(nameEQ) == 0) return c.substring(nameEQ.length, c.length);
                    }
                    return null;
                },
                //tạo phần tử cuối cùng lưu vào cookies
                createCookie: function (name, value, days) {
                    var expires = "";
                    if (days) {
                        var date = new Date();
                        date.setTime(date.getTime() + (days * 24 * 60 * 60 * 1000));
                        expires = "; expires=" + date.toUTCString();
                    }
                    document.cookie = name + "=" + value + expires + "; path=/";
                },
                //xóa cookies trong store
                eraseCookie: function (name) {
                    this.createCookie(name, "", -1);
                }
            }
        }];
    }]);
    //cấu hình điều hướng
    app.config(['$stateProvider', '$locationProvider', '$urlRouterProvider', '$qProvider',
        '$compileProvider', '$httpProvider', 'cfpLoadingBarProvider',
        function ($stateProvider, $locationProvider, $urlRouterProvider, $qProvider,
            $compileProvider, $httpProvider, cfpLoadingBarProvider) {
            $compileProvider.debugInfoEnabled(true);
            cfpLoadingBarProvider.includeSpinner = true;
            $compileProvider.aHrefSanitizationWhitelist(/^\s*(https?|ftp|mailto|tel|sms|file|skype|callto):/);
            $httpProvider.interceptors.push('sessionInjector');
            $locationProvider.hashPrefix('');

            //$urlRouterProvider.otherwise("AccountSetting");
            //$urlRouterProvider.otherwise(function ($injector) {
            //    var $state = $injector.get('$state');
            //    //$state.go('Error404Page');
            //});
            $stateProvider
            .state("stateLogin", {
                url: "/Login",
                templateUrl: "/Account/Login"
            })
            ///////////////////////////////////
            //.state("DuyetNotify", {
            //    url: "/DSDuyetNotify",
            //    templateUrl: "/SYSTEM/Notification/DuyetNotify",
            //    params: {
            //        params: ''
            //    },
            //    titlestate: "Danh sách duyệt"
            //})
        }]);
    app.run(['$rootScope', '$state', '$stateParams', function ($rootScope, $state, $stateParams) {
        $rootScope.$state = $state;
        $rootScope.$stateParams = $stateParams;
        $rootScope.$on("$stateChangeSuccess", function (event, currentRoute, previousRoute) {

        });
        $rootScope.$on('$stateChangeStart', function (event, toState, toParams, fromState, fromParams) {
            // do something
        })
    }]);

    app.run(['$rootScope', '$location', function ($rootScope, $location) {
        $rootScope.$on('$locationChangeStart', function (event) {
            if (window.event && window.event.type === "popstate") {
                window.document.title = "Can't back previous";
                event.preventDefault();
            }
        });
    }]);
})();;
