//tạo dấu * màu đỏ bên cạnh các trường bắt buộc nhập
//Using with hmtl: <important/>
app.directive("important", function () {
    return {
        template: '<span style="color:red;">&nbsp;*</span>'
    };
});

///lazy-scroll
app.directive("loadMoreData", [function () {
    return {
        scope: {
            lazyload: "&"
        },
        restrict: 'ACE',
        link: function ($scope, element, attrs, ctrl) {
            var raw = element[0];
            element.scroll(function () {
                if (raw.scrollTop + raw.offsetHeight >= raw.scrollHeight) {
                    //$scope.$apply("loadMoreData()");
                    $scope.$apply($scope.lazyload);
                }
            });
        }
    };

}]);

//validate giá trị nhỏ nhất
app.directive('ngMin', function () {
    return {
        restrict: 'A',
        require: 'ngModel',
        link: function (scope, elem, attr, ctrl) {
            scope.$watch(attr.ngMin, function () {
                ctrl.$setViewValue(ctrl.$viewValue);
            });
            var minValidator = function (value) {
                var min = scope.$eval(attr.ngMin) || 0;
                if (value < min) {
                    ctrl.$setValidity('minValue', false);
                    return undefined;
                } else {
                    ctrl.$setValidity('minValue', true);
                    return value;
                }
            };

            ctrl.$parsers.push(minValidator);
            ctrl.$formatters.push(minValidator);
        }
    };
});

//validate giá trị lớn nhất
app.directive('ngMax', function () {
    return {
        restrict: 'A',
        require: 'ngModel',
        link: function (scope, elem, attr, ctrl) {
            scope.$watch(attr.ngMax, function () {
                ctrl.$setViewValue(ctrl.$viewValue);
            });
            var maxValidator = function (value) {
                var max = scope.$eval(attr.ngMax) || Infinity;
                if (value > max) {
                    ctrl.$setValidity('maxValue', false);
                    return undefined;
                } else {
                    ctrl.$setValidity('maxValue', true);
                    return value;
                }
            };

            ctrl.$parsers.push(maxValidator);
            ctrl.$formatters.push(maxValidator);
        }
    };
});
//ToanTQ(12/04/2021)
//tự động thêm class css (fix-height) vào trên modal để xuất hiện thanh scroll dọc tùy chiều cao màn hình
app.directive('fixHeightAuto', ['$window', function ($window) {
    return {
        restrict: 'ACE',
        link: function postLink(scope, iElement, iAttrs) {
            setTimeout(function () {
                var top_bott = 52 + 58;  // vùng tiêu đề + vùng bottom
                var div_height = $(iElement).height(); // chiều cao của panel body modal
                var modal_height = top_bott + div_height;
                if (modal_height > $(window).height()) {
                    $(iAttrs.$$element).addClass('fix-height');
                } else {
                    if ($(iAttrs.$$element).parents('.modal-lg').length > 0 || $(iAttrs.$$element).parents('.modal-fs').length > 0)
                        $(iAttrs.$$element).css({ 'min-height': 'calc(100vh - 110px)' })
                }
            }, 500);
        }
    };
}]);

//sự kiện nhấn phím enter
app.directive('myEnter', ['growl', function (growl) {
    return function (scope, element, attrs) {
        var lastClick = null;
        var IGNORE_TIME = 1000; // One second
        element.bind("keydown keypress", function (event) {
            if (event.which === 13) {
                scope.$apply(function () {
                    var now = Date.now();
                    if (!lastClick || now - lastClick > IGNORE_TIME) {
                        lastClick = now;
                        scope.$eval(attrs.myEnter);
                    } else {
                        growl.info("please_wait_a_moment", { ttl: 2500 });
                    }
                });
                event.preventDefault();
            }
        });
    };
}]);
//enter and submitted, shift + enter: = enter
app.directive('enterSubmit', function () {
    return {
        restrict: 'A',
        link: function (scope, elem, attrs) {
            elem.bind('keydown', function (event) {
                var code = event.keyCode || event.which;
                if (code === 13) {
                    if (event.shiftKey) {
                        event.preventDefault();
                        scope.$apply(attrs.enterSubmit);
                    }
                }
            });
        }
    }
});

app.directive('focusMe', ['$timeout', '$parse', function ($timeout, $parse) {
    return {
        link: function (scope, element, attrs) {
            var model = $parse(attrs.focusMe);
            scope.$watch(model, function (value) {
                if (value === true) {
                    $timeout(function () {
                        element[0].focus();
                    });
                }
            });
            element.bind('blur', function () {
                scope.$apply(model.assign(scope, false));
            })
        }
    };
}]);

app.directive('focus', ['$timeout', function ($timeout) {
    return {
        scope: {
            trigger: '@focus'
        },
        link: function (scope, element) {
            scope.$watch('trigger', function (value) {
                if (value === "true") {
                    $timeout(function () {
                        element[0].focus();
                    });
                }
            });
        }
    };
}]);

//focus or prev khi nhấn vào phím page down/page up
app.directive('myFocus', function () {
    return {
        restrict: 'A',
        link: function ($scope, elem, attrs) {
            elem.bind('keydown', function (e) {
                var code = e.keyCode || e.which;
                if (code === 40) {
                    e.preventDefault();
                    elem.next().focus();
                }
                else if (code === 38) {
                    e.preventDefault();
                    elem.prev().focus();
                }
            });
        }
    }
});

//------------------dùng cho View Document---------------
app.directive('contextDocument', [function () {
    return {
        restrict: 'A',
        scope: '@&',
        compile: function compile(tElement, tAttrs, transclude) {
            return {
                post: function postLink(scope, iElement, iAttrs, controller) {
                    var ul = $('#' + iAttrs.context),
                      last = null;

                    ul.css({
                        'display': 'none'
                    });
                    $(iElement).bind('contextmenu', function (event) {
                        $('#context10').css({ 'display': 'none' });
                        $('#context01').css({ 'display': 'none' });
                        event.preventDefault();
                        if ($(event.target).parents().is(".cboxElement")) {
                            var id = $(event.target).parents(".cboxElement").get(0).id;
                            ul = $('#context10');
                            for (var i = 0; i < scope.list_items.length; i++) {
                                if (scope.list_items[i].id == id) {
                                    scope.widgetView = angular.copy(scope.list_items[i]);
                                    break;
                                }
                            }
                        }
                        else
                            ul = $('#context01');
                        scope.$apply();
                        ul.css({
                            position: "fixed",
                            display: "block",
                            left: event.clientX + 'px',
                            top: event.clientY + 'px'
                        });
                        last = event.timeStamp;
                    });

                    $(document).click(function (event) {
                        var target = $(event.target);
                        if (!target.is(".popover") && !target.parents().is(".popover")) {
                            if (last === event.timeStamp)
                                return;
                            ul.css({
                                'display': 'none'
                            });
                        }
                    });
                }
            };
        }
    };
}]);

app.directive('colResize', [function () {
    return function (scope, element, attrs) {
        var pressed = false;
        var start = undefined;
        var startX, startWidth;
        var totalLength;
        var totalTable;
        var index;
        var ele_pa, length_e;
        element.bind("mousedown", function (event) {
            start = $(element);
            index = start[0].cellIndex;
            totalLength = $(start).parents('table').width();
            totalTable = $(start).parents('thead').width();
            ele_pa = 'table#' + $(start).parents('table')[0].id + ' tbody tr td:nth-child(' + (index + 1) + ')';
            if ($(element).children('div.vcursur').is(':hover')) {
                pressed = true;
                startX = event.pageX;
                startWidth = $(start).width();
                $(start).addClass("resizing");
                var change = true;
                $(document).mousemove(function (e) {
                    if (pressed) {
                        var size = (e.pageX - startX);
                        var totalsize = totalTable + size;
                        if (totalsize < totalLength && (startWidth + size) > 0) {
                            $(start).width(startWidth + size);
                            $(ele_pa).width(startWidth + size);
                            $(start).parents('table').children('tbody').width($(start).parents('table').children('thead').width());
                        }
                    }
                });

                $(document).mouseup(function () {
                    if (pressed) {
                        $(start).removeClass("resizing");
                        pressed = false;
                    }
                });
            }
        });

        element.bind("click", function (event) {
            if (!$(element).children('div.vcursur').is(':hover')) {
                var ele_th = $(element).parent().children();
                var size = 0;
                index = $(element)[0].cellIndex;
                for (var i = 0; i < ele_th.length; i++) {
                    if (index != i) {
                        $(ele_th[i]).children().last().removeClass("fa-angle-up");
                        $(ele_th[i]).children().last().removeClass("fa-angle-down");
                    }
                }
                if (attrs.class == "date_ht") {

                }
                if ($(element).children().length > 2) {
                    if ($(element).children().last().hasClass("fa-angle-up")) {
                        $(element).children().last().removeClass("fa-angle-up");
                        $(element).children().last().addClass("fa-angle-down");
                        quickSort(scope.list_items, 0, scope.list_items.length - 1, true, attrs.class);
                    } else {
                        $(element).children().last().removeClass("fa-angle-down");
                        $(element).children().last().addClass("fa-angle-up");
                        quickSort(scope.list_items, 0, scope.list_items.length - 1, false, attrs.class);
                    }
                } else {
                    $(element).append('<i class="fa fa-angle-down" aria-hidden="true"></i>');
                    quickSort(scope.list_items, 0, scope.list_items.length - 1, true, attrs.class);
                }
                scope.$apply();
            }
        });
        // tính toán độ dài của td phải = th
        function update() {
            var ele_th = $(element).parent().children();
            var size = 0;
            for (var i = 0; i < ele_th.length; i++) {
                index = ele_th[i].cellIndex;
                size = $(ele_th[i]).width()
                var ele_pa = 'table#' + $(element).parents('table')[0].id + ' tbody tr td:nth-child(' + (index + 1) + ')';
                $(ele_pa).width(size);
            }
            for (var i = 0; i < scope.list_items.length; i++) {
                if (scope.list_items[i].date_ht) {
                    var date = scope.list_items[i].date_ht.split(' '), date_ct = date[0].split('/');
                    scope.list_items[i].date_temp = new Date(date_ct[2] + '-' + date_ct[1] + '-' + date_ct[0] + 'T' + date[1] + ':00');
                }
            }
        }

        function quickSort(arr, left, right, max, title) {
            if (arr == null || arr.length == 0)
                return;

            if (left >= right)
                return;
            var middle = left + (right - left) / 2;
            var pivot = arr[parseInt(middle)];
            var i = left, j = right;
            while (i <= j) {
                if (max) {
                    if (title === "date_ht") {
                        while (arr[i].date_temp < pivot.date_temp) {
                            i++;
                        }

                        while (arr[j].date_temp > pivot.date_temp) {
                            j--;
                        }
                    }
                    else if (typeof pivot[title] === "string") {
                        while (arr[i][title].toLowerCase().localeCompare(pivot[title].toLowerCase()) < 0) {
                            i++;
                        }

                        while (arr[j][title].toLowerCase().localeCompare(pivot[title].toLowerCase()) > 0) {
                            j--;
                        }
                    } else if (typeof pivot[title] === "boolean") {
                        arr.sort(function (x, y) {
                            // true values first
                            return (x[title] === y[title]) ? 0 : x ? -1 : 1;
                            // false values first
                            // return (x === y)? 0 : x? 1 : -1;
                        });
                        return;

                    } else if (typeof pivot[title] === "number") {
                        while (arr[i][title] < pivot[title]) {
                            i++;
                        }

                        while (arr[i][title] > pivot[title]) {
                            j--;
                        }
                    } else {
                        return;
                    }
                }
                else {
                    if (title === "date_ht") {
                        while (arr[i].date_temp > pivot.date_temp) {
                            i++;
                        }

                        while (arr[j].date_temp < pivot.date_temp) {
                            j--;
                        }
                    }
                    else
                        if (typeof pivot[title] === "string") {
                            while (arr[i][title].toLowerCase().localeCompare(pivot[title].toLowerCase()) > 0) {
                                i++;
                            }

                            while (arr[j][title].toLowerCase().localeCompare(pivot[title].toLowerCase()) < 0) {
                                j--;
                            }
                        }
                        else if (typeof pivot[title] === "number") {
                            while (arr[i][title] > pivot[title]) {
                                i++;
                            }

                            while (arr[i][title] < pivot[title]) {
                                j--;
                            }
                        } else {
                            return;
                        }

                }
                if (i <= j) {
                    var temp = arr[i];
                    arr[i] = arr[j];
                    arr[j] = temp;
                    i++;
                    j--;
                }
            }
            if (left < j)
                quickSort(arr, left, j, max, title);

            if (right > i)
                quickSort(arr, i, right, max, title);
        }

        scope.$watch(function () { return scope.list_items }, function (newvalue, oldvalue) {
            if (!angular.equals(newvalue, oldvalue)) {
                $(element).parents('table').children('tbody').width($(element).parents('thead').width());
                update();
            }
        });
    }
}]);

