app.directive('totalNoticeShow', ['$compile', function ($compile) {
    return {
        restrict: 'E',
        replace: true,
        scope: {
            totalNotice: '=',
            callback: '&'
        },
        replace: false,
        controller: ['$scope', '$element', '$compile', function ($scope, $element, $compile) {

            var template = '';
            if ($scope.totalNotice > 0) {
                template = '<a class="dropdown-toggle" data-toggle="dropdown" href="" '
                + ' title="Cảnh báo" '
                + ' id="canh_bao" >'
                + ' <i class="ti-bell"></i> '
                + ' <span id="notify"'
                + '          class="badge badge-important" ng-bind="' + $scope.totalNotice + ' | number"></span>'
                + '</a>';
            }
            else {
                template =
                 '<a class="dropdown-toggle" data-toggle="dropdown" href="" '
               + ' title="Cảnh báo" '
               + ' id="canh_bao">'
               + ' <i class="ti-bell"></i> '
               + ' </a>';
            }
            $element.append($compile(template)($scope));
        }]
    };
}]);
