app.directive('onLastRepeat', function () {
    return {
        scope: {
            funlast: '='
        },
        link: function (scope, element, attrs) {
            if (scope.$last == true)
                setTimeout(function () {
                    scope.$emit('onRepeatLast', element, attrs);
                }, 1);
        }
    }
});
app.directive('flexibleDiv', function () {
    return {
        scope: {
            opts: '='
        },
        link: function (scope, element, attr) {
            // Watching height of parent div
            scope.$watch(function () {
                return element.parent(0).height();
            }, updateHeight);

            // Watching width of parent div
            scope.$watch(function () {
                return element.parent(0).width();
            }, updateWidth);

            function updateHeight() {
                scope.opts.chart.height = element.parent(0).height() - 150; //150 custom padding
            }

            function updateWidth() {
                scope.opts.chart.width = element.parent(0).width() - 50; //50 custom padding
            }
        }
    }
});

app.directive('directiveLoop', ['$compile', function ($compile) {
    return {
        restrict: 'E',
        replace: true,
        scope: {
            content: '=',
            ngModel: '='
        },
        link: function (scope, elem, attrs) {
            var template = '<render-type content = "' + scope.content + '" ng-model = "' + scope.ngModel + '"></div>';
            template = $compile(template)(scope);
            //elem.replaceWith(template);
        }
    };
}]);

app.directive('fixedHeader', ['$timeout', function ($timeout) {
    return {
        restrict: 'A',
        link: link
    };

    function link($scope, $elem, $attrs, $ctrl) {
        var elem = $elem[0];
        var min_width = 0;
        var last_height = 0;
        var index = -1, scrollBarWidth = 0;
        // wait for data to load and then transform the table
        $scope.$watch(tableDataLoaded, function (isTableDataLoaded) {
            if (isTableDataLoaded) {
                transformTable();
            }
        });
        function tableDataLoaded() {
            // first cell in the tbody exists when data is loaded
            // until after the table is transformed
            var firstCell = elem.querySelector('tbody tr:first-child td:first-child:not([style*="border-right: 1px solid #ddd !important"])');
            return firstCell;
        }

        function transformTable() {
            // reset display styles so column widths are correct when measured below
            angular.element(elem.querySelectorAll('thead, tbody, tfoot')).css('display', '');

            //ToanTQ(01/06/2021)
            var all_ele = elem.querySelectorAll('tr:first-child th:not([class*="ng-hide"])');
            var widthPX = 0;
            if (all_ele.length > 0) {
                angular.forEach(all_ele, function (thElem, i) {
                    widthPX += parseInt(thElem.style.width);
                })
            }
            angular.element(elem.querySelectorAll('thead')).css('width', widthPX + 'px');
            ///
            // wrap in $timeout to give table a chance to finish rendering
            $timeout(function () {
                // set widths of columns
                var tbody = elem.querySelector('tbody');
                scrollBarWidth = (tbody.offsetWidth - tbody.clientWidth);
                tHeadTotBody(scrollBarWidth);
                // set css styles on thead and tbody
                angular.element(elem.querySelectorAll('thead, tfoot')).css('display', 'block');
                angular.element(elem.querySelectorAll('tbody')).css({
                    'display': 'block',
                    'height': $attrs.tableHeight || 'inherit',
                    'overflow': 'auto'
                });
                // reduce width of last column by width of scrollbar
                $scope.$watch(function () { return tbody.offsetWidth - tbody.clientWidth; }, function (newValue) {
                    if (newValue && newValue != 0 && scrollBarWidth != newValue) {
                        scrollBarWidth = newValue;
                        tHeadTotBody(scrollBarWidth);
                    }
                });
            }, 500);
        }
        // căn chỉnh độ rộng vùng tbody phù hợp với thead
        function tHeadTotBody(scrollBarWidth) {
            min_width = 0;
            var all_ele = elem.querySelectorAll('tr:first-child th:not([class*="ng-hide"])');
            if (all_ele.length > 0) {
                angular.forEach(all_ele, function (thElem, i) {
                    var tdElems = elem.querySelectorAll('tbody tr td:nth-child(' + (i + 1) + ')');
                    var tfElems = elem.querySelectorAll('tfoot tr td:nth-child(' + (i + 1) + ')');
                    // lấy độ rộng của từng thẻ th
                    var columnWidth = thElem ? parseInt(thElem.style.width) : 0;
                    min_width += columnWidth;
                    //nếu là th cuối cùng -> trừ cho độ rộng của thanh scroll
                    if (i == (all_ele.length - 1)) {
                        var lastTH = all_ele[i];
                        columnWidth = columnWidth - (thElem.cellIndex == lastTH.cellIndex ? (scrollBarWidth + 2) : 0);
                    }

                    $(thElem).css('border-right', '.1px solid #ddd');
                    if (tdElems) {
                        $(tdElems).attr('style', 'width: ' + columnWidth + 'px !important;float:left;height:30px;border-right: .1px solid #ddd !important;border-bottom: .1px solid #ddd !important;');
                    }
                    if (tfElems) {
                        $(tfElems).attr('style', 'width: ' + columnWidth + 'px !important;float:left;height:30px;border-right: .1px solid #ddd !important;border-bottom: .1px solid #ddd !important;');
                    }
                });
                //set width on table equas total th on firse time
                elem.style.width = (min_width) + 'px';

                angular.element(elem.querySelectorAll('tbody tr')).css('display', 'inline');
                index = elem.querySelectorAll('tbody tr').length;
            }
        }
        // Chỉnh sửa độ cao của bảng phù hợp với độ cao của thẻ bao ngoài
        // nếu độ cao bị thay đổi-> kiểm tra thanh scroll dọc còn tồn tại hay không
        $scope.$watch(function () {
            if ($($elem).parent().height() - last_height > 20 || $($elem).parent().height() - last_height < -20)
                return $($elem).parent().height();
        }, function (newValue, old_value) {
            if (newValue && newValue != 0) {
                last_height = newValue;
                $($elem).css('height', newValue - 55);
                var tbody = elem.querySelector('tbody');
                setTimeout(function () {
                    if ($(tbody).children().length < 1)
                        $($elem).css('height', 'auto');
                }, 100);

                if (tbody != null)
                    if ((tbody.offsetWidth - tbody.clientWidth) != scrollBarWidth) {
                        scrollBarWidth = (tbody.offsetWidth - tbody.clientWidth);
                        tHeadTotBody(scrollBarWidth);
                    }
            }
        });
        //// Kiểm tra nếu có sự thay đổi dữ liệu-- sử dụng khi lazyload
        $scope.$watch(function () {
            // kiểm tra tbody có dữ liệu và có độ dài thay đổi hoặc nội dung bị thay đổi
            if (elem.querySelectorAll('tbody tr') && (elem.querySelectorAll('tbody tr').length - index > 0) && index != -1) {
                index = -1;
                return elem.querySelectorAll('tbody tr').length;
            }
        }, function (newValue, old_value) {
            if (newValue && newValue > 0) {
                tHeadTotBody(scrollBarWidth);
            }
        });
    }
}]);
