                            var arr_item = [];
                            for (var item in $scope.ctlo) {
                                arr_item = arr_item.concat($scope.ctlo[item]);
                            }
                            if (arr_item.length > 0) {
                                maxLn = parseInt(_.max(arr_item, function (o) { return parseFloat(o.ln); }).ln) + 1;
                            }
                            ctData["ma_lo"] = rowData.ma_lo;
                            ctData["ma_lo_ncc"] = rowData.ma_lo_ncc;
