                    $scope.duyetnotify_yn = JSON.CheckExistInArray('state', 'DuyetNotify', $scope.array_list) >= 0;

                    $scope.noticetask_yn = JSON.CheckExistInArray('state', 'NoticeFromTask', $scope.array_list) >= 0;

