app.controller('DuyetNotifyController',
    ['$scope', 'CRUDServices', 'SessionService', '$state', '$stateParams', '$dialogs', '$compile', '$filter', '$cookies', 'sysDataShare', '$timeout', 'ListBase', 'SystemBase', 'jqgridFactory',
        function ($scope, CRUDServices, SessionService, $state, $stateParams, $dialogs, $compile, $filter, $cookies, sysDataShare, $timeout, ListBase, SystemBase, jqgridFactory) {
            /////1. khai báo 
            var vm = this;
            vm.lang = "vi";
            var index = 1, limit = 50;
            var reachedLast = false;
            vm.selectedAll = false;
            var totalPages;

            vm.ds_status = [
                { status: 'all', statusname: 'Tất cả' },
                { status: '0', statusname: 'Chưa đọc' },
                { status: '1', statusname: 'Đã đọc' }
            ];
            vm.search = {
                key: '',
                status: vm.ds_status[0].status
            };
            var gridID = "crmaccount";
            vm.gridData = [];
            vm.header = []; var header = [];
            vm.menu = [];
            vm.totalItems = 0;
            var events_data = {
                gridID: gridID,
                edit: EditPage, //edit dòng
                delete: DeleteRows,//xóa dòng
                //phần tùy chỉnh bổ sung (chỉ phần menu row)
                array_menu: []
            }
            vm.right_click = jqgridFactory.RightClickMenu(events_data);
            
            //jqgrid mới
            vm.myGridOptions = {
                //các thuộc tính mặc định của jqgrid
                scroll: false,
                datatype: 'local',
                rownumbers: true,
                rownumWidth: 50,
                multiselect: true,
                multiboxonly: true, // chỉ chọn nhiều dòng khi click ô checkbox
                //height: 420,
                colMenu: true,
                shrinkToFit: false, //tự động co dãn kích thước các cột
                //các thuộc tính bổ sung cho directive
                outerID: 'all_items',
                id: gridID,
                autoBinding: true,
                config_server: true,
                radio_btn: false,
                frozen: true,
                lazy_yn: true,
                pageSize: 50,
                remove_loadding: false,
                contextMenu: true,//rightclick trên grid
                contextMenuRow: vm.right_click.menu_row,
                contextMenuHeader: vm.right_click.menu_header,
                configServer: true, //lấy cấu hình từ server
                actionNav: false,
                actionWidth: 50,
                actionsNavOptions: {
                    deleteUsericon: "ui-icon-trash",
                    align: 'center',
                    deleteUsertitle: "Xóa",
                    custom: [
                        {
                            action: "deleteUser",
                            //onClick: DeleteRow
                        }
                    ]
                },
                loadComplete: function () {

                },
                report: false,
                pivot: false,
                treeGrid: false,
                ondblClickRow: EditPage,
                filterToolbar: true,
                groupHeader: true,
                useColSpanStyle: true,
            };

            //#endregion

            //#region DIRECTIVE PARAMS
            //truyền các tham số cần thiết về directive để xử lý thiết lập
            vm.passData = {
                gridConfig: vm.myGridOptions,
                txtHeader: 'Danh sách thông báo duyệt', //tiêu đề của danh mục
                totalItems: 0,
                params: $stateParams.params, //load lại dữ liệu vừa tìm kiếm nếu vừa từ detail của bản ghi trở ra
                status: {
                    ma_ct: 'ACC',   //mã chứng từ cấu hình trong bảng sysdmtt
                    owner_yn: true, //check danh mục này có trạng thái: Của tôi hay ko,
                    selected: 'all', //trạng thái mặc định hiển thị khi load lần đầu (dựa vào bảng sysdmtt để điền value)
                },
                command: {
                    gridid: 'DuyetNotify',
                    state: 'DuyetNotify',
                    form_trans: 'DuyetNotify',
                    role_yn: false,
                }
            };

            //nhận giá trị cấu hình từ directive trả về
            (function first() {
                vm.resultData = function (item) {
                    vm.search.trang_thai = item.status.status;
                    role = item.role;
                    vm.header = item.header;

                    sysDataShare.sendData({ header: item.header, array_yn: true });

                    //tránh tham chiếu cùng một biến
                    //var header_show = angular.copy(item.header_show);
                    //hideshowShare.sendData({ ds_column: header_show, gridid: gridID, array_yn: true });

                }
                if ($stateParams.params != "") {
                    vm.search = $stateParams.params.paramsearch;
                };
            })();

            //gọi từ directive
            vm.GetData = function (index) {
                setTimeout(function () {
                    GetData(index);
                }, 1000);

            };
            //sự kiện chọn item trên list trạng thái
            vm.StatusClick = function (item) {
                if (!angular.isUndefined(item)) {
                    vm.search.trang_thai = item.status;
                }
                TimKiem();
            }

            //#endregion
            //get data
            function GetData(index) {
                //debugger;
                var kq = CRUDServices.getdata({
                    user_id: SessionService.getItems().user_id,
                    key: vm.search.key,
                    status: vm.search.status,
                    index: 1
                },
                    '/SysAPI/api/NoticeAPI/DSDuyetChungTu/', 'GET');
                kq.then(function (value) {
                    SystemBase.DisplaySearch(vm.search.status);
                    var dl = JSON.parse(value.data);
                    vm.gridData = vm.gridData.concat(dl.Items);
                    vm.totalSearchPages = dl.TotalPages;
                    vm.totalItems = dl.TotalItems;
                    if (vm.totalSearchPages == 0) {
                        reachedLast = true;
                    }
                    if (vm.totalSearchPages == index) {
                        reachedLast = true;
                    }
                    SystemBase.RemoveLoading();
                });
            };

            function TimKiem() {
                index = 1;
                reachedLast = false;
                vm.gridData = [];
                jqgridFactory.ClearGridData(gridID);
                GetData(index);
            }

            vm.TimKiem = function (id, status) {
                //debugger;
                if (!angular.isUndefined(id) && !angular.isUndefined(status)) {
                    SystemBase.DisplaySearch(id);
                    vm.search.status = status;
                }
                TimKiem();
            }

            vm.Paging = function () {
                if (reachedLast) {
                    return false;
                }
                else {
                    reachedLast = false;
                    index++;
                    GetData(index);

                    if (index <= vm.totalPages) {
                        return false;
                    }
                    if (index > vm.totalPages) {
                        reachedLast = true;
                    }
                }
            }

            vm.SearchChange = function (key) {
                if (key == null || key == "") {
                    TimKiem();
                }
            }

            /////3.2. Function trên grid
            //thêm bản ghi mới
            function Add() {
                var add = SystemBase.AddModal("/CRM/Modify/ActivityModal", "ActivityModalController", "md", "crmactivity", role);
                if (!angular.isUndefined(add)) {
                    add.then(function (value) {
                        if (!angular.isUndefined(value) && value.length > 0) {
                            var data_edit = {
                                ct: value[value.length - 1],
                                trang_thai: 'edit',
                                from: 'notify',
                                role: role,
                                search: vm.search
                            };
                            //console.log(data_edit);
                            $state.go('ActivityOverview', { params: data_edit });
                        }
                    });
                }
            }

            function EditPage(id, state, event) {
                var rowData = jqgridFactory.GetRowData(gridID, id);
                Detail(rowData);
            }

            function Detail(item) {
                switch (item.ma_ct) {
                    //phiếu báo giá (61)
                    case 'SQ1': {
                        var data_edit = {
                            ct: {
                                stt_rec: item.stt_rec
                            },
                            search: '',
                            status: '1'
                        };
                        $state.go('CTBAOGIA', { params: data_edit });
                        break;
                    }
                        //đơn hàng bán(64)
                    case 'SO1': {
                        var data_edit = {
                            ct: {
                                stt_rec: item.stt_rec
                            },
                            search: '',
                            status: '1'
                        };
                        $state.go('CTDHBAN', { params: data_edit });
                        break;
                    }
                        //phiếu yc đổi, trả hàng bán(66)
                    case 'RQ1': {
                        var data_edit = {
                            ct: {
                                stt_rec: item.stt_rec
                            },
                            search: '',
                            status: '1'
                        };
                        $state.go('CTYCDOITRAHANGBAN', { params: data_edit });
                        break;
                    }
                        //phiếu yc mua hàng
                    case 'PR0': {
                        var data_edit = {
                            ct: {
                                stt_rec: item.stt_rec
                            },
                            search: '',
                            status: '1'
                        };
                        $state.go('CTYCMUAHANG', { params: data_edit });
                        break;
                    }
                        //đơn hàng mua(94)
                    case 'PO1': {
                        var data_edit = {
                            ct: {
                                stt_rec: item.stt_rec
                            },
                            search: '',
                            status: '1'
                        };
                        $state.go('CTDHMUA', { params: data_edit });
                        break;
                    }
                        //phiếu yc đổi, trả lại nhà cc(67)
                    case 'RQ2': {
                        var data_edit = {
                            ct: {
                                stt_rec: item.stt_rec
                            },
                            search: '',
                            status: '1'
                        };
                        $state.go('CTYCDOITRANCC', { params: data_edit });
                        break;
                    }

                        //Lệnh điều chuyển(95)
                    case 'TO1': {
                        var data_edit = {
                            ct: {
                                stt_rec: item.stt_rec
                            },
                            search: '',
                            status: '1'
                        };
                        $state.go('CTLENHDIEUCHUYEN', { params: data_edit });
                        break;
                    }
                        //đề nghị thanh toán
                    case 'RC1': {
                        var data_edit = {
                            ct: {
                                stt_rec: item.stt_rec
                            },
                            search: '',
                            status: '0'
                        };
                        $state.go('CTDENGHITT', { params: data_edit });
                        break;
                    }
                        //phiếu chi(46)
                    case 'PC1': {
                        var data_edit = {
                            ct: {
                                stt_rec: item.stt_rec
                            },
                            search: '',
                            status: '0'
                        };
                        $state.go('CTPHIEUCHI', { params: data_edit });
                        break;
                    }
                    default:
                }
            }

            function ReLoad() {
                TimKiem();
            }

            function DeleteRows() {
                var params = {
                    gridID: gridID,
                    api: '/ConfigAPI/api/GanttChart/PMListAPI/Delete/',
                    entities: 'listdm',
                    role: role,
                    check_owner: true,
                    field_display: 'ten',
                    field_key: 'account_id',
                    check_arise: true,
                    state: 'TempDanhMuc',
                }
                var del = ListBase.DeleteRows(params);
                del.then(function (value) {
                    if (value.data > 0) {
                        TimKiem();
                        var dialog = $dialogs.notify("Thông báo", "Xóa thành công " + value.data + " bản ghi");
                    }
                    if (angular.isDefined(value.message_check_owner) && value.message_check_owner != "") {
                        var dialog = $dialogs.notify("Thông báo", "Bản ghi: " + value.message_check_owner + " của user khác. Không thể xóa");
                    }

                    if (angular.isDefined(value.message_check_arise) && value.message_check_arise != "") {
                        var dialog = $dialogs.notify("Thông báo", "Bản ghi: " + value.message_check_arise + " đã phát sinh dữ liệu. Không thể xóa");
                    }
                });
            }

            vm.OnClickMenu = function (id) {
                switch (id) {
                    case 'reload': {
                        ReLoad();
                        break;
                    }
                    case 'add': {
                        Add();
                        break;
                    }
                    case 'edit': {
                        EditModal();
                        break;
                    }
                    case 'delete': {
                        DeleteRows();
                        break;
                    }
                    case "expExcel": {
                        Export("excel");
                        break;
                    }
                    case "expPDF": {
                        Export("pdf");
                        break;
                    }
                    case "expCSV": {
                        Export("csv");
                        break;
                    }
                }
            }

            vm.OnKeyDown = function (value) {
                //console.log(value);
                switch (value.keyCode) {
                    case 46: //delete
                        {
                            DeleteRows();
                            break;
                        }
                    case 113: //f2
                        {
                            Add();
                            break;
                        }
                    case 118://f7
                        {
                            EditModal();
                            break;
                        }
                    default:
                        break;

                }
            }

            $scope.$on('data_shared', function () {
                if (!sysDataShare.getData().array_yn) {
                    if (sysDataShare.getData().error == "") {
                        strSQL = sysDataShare.getData().where;
                        error_logic = "";
                    }
                    else {
                        strSQL = "";
                        error_logic = sysDataShare.getData().error;
                    }
                }
            })

            vm.SetWidth = function (id, id1) {
                SystemBase.SetWidthCollapse(id, id1, gridID);
            }

            $(document).on('settings.ace.jqGrid', function (ev, event_name, collapsed) {
                SystemBase.SetWidthSideBar(gridID, event_name);
            })

            function Export(type) {
                SystemBase.Export(gridID, type);
            }

            $scope.$watch(function () { return $cookies.__APPLICATION_LANGUAGE; }, function (newValue) {
                if (newValue == "vi-VN") {
                    vm.lang = "vi";
                    vm.tieng_viet = true;
                }
                else {
                    vm.lang = "en";
                    vm.tieng_viet = false;
                }
            });
        }]);


