app.controller('NoticeTaskHubController', ['$scope', '$location', '$http', 'SessionService', 'CRUDServices', '$window', '$state', '$dialogs', '$interval',
        '$timeout', 'SystemBase', 'growl', 'signalR', 'FormatComment',
        function ($scope, $location, $http, SessionService, CRUDServices, $window, $state, $dialogs, $interval, $timeout, SystemBase, growl, signalR, FormatComment) {
            var vm = this;
            vm.promise = null;
            vm.TongSLCanhBao = 0;
            vm.message = "";
            vm.top5 = [];
            //initNotify();
            //60s chạy function initNotify 1 lần
            //$scope.promise = $interval(initNotify, 60000);

            //hiện số lượng thông báo trên giao diện
            function initNotify() {
                vm.TongSLCanhBao = 0;
                var total = CRUDServices.getdata({ user_id: SessionService.getItems().user_id },
                        "/SysAPI/api/NoticeAPI/GetTongSLThongBaoTask/", "GET");
                total.then(function (value) {
                    if (value.status == 200) {
                        vm.TongSLCanhBao = value.data > 99 ? 99 : value.data;
                        if (vm.TongSLCanhBao > 0 && $("#notify1").not('badge badge-important')) {
                            $("#notify1").addClass("badge badge-important");
                        }
                        else if (vm.TongSLCanhBao <= 0) {
                            $("#notify1").removeClass("badge badge-important");
                            vm.TongSLCanhBao = null;
                        }
                    }
                }, function (err) {//lỗi
                    console.log('error')
                });
            };
            //load lại số lượng thông báo khi có phát sinh thông báo
            //signalR.NewNotification(function (data) {
            //    var new_notice = (JSON.parse(data));
            //    //hiển thị thông báo - 
            //    if (new_notice.userid_to == SessionService.getItems().user_id) {
            //        //hiển thị thông báo 
            //        FormatComment.createNotice(new_notice, function () {
            //            //callback nếu người dùng click vào xem thông báo đó
            //            //$state.go(new_notice.url_name);
            //            $scope.Detail(new_notice)
            //        });
            //        ////
            //        //tính và hiển thị lại số lượng thông báo
            //        initNotify();
            //        $scope.GetTop5ThongBao();
            //    }
            //});
            //ds top 5 thông báo mới nhất
            vm.GetTop5ThongBao = function () {
                //dropdown chưa đc mở
                if (vm.TongSLCanhBao > 0 && !$("#li-notify").hasClass('open')) {
                    var top5 = CRUDServices.getdata({ user_id: SessionService.getItems().user_id },
                        "/SysAPI/api/NoticeAPI/GetTopThongBaoTask/", "GET");
                    top5.then(function (value) {
                        vm.top5 = JSON.parse(value.data);
                    }, function (err) {
                        console.log('Không lấy được dữ liệu');
                    });
                }
            }

            //chi tiết thông báo    
            vm.Detail = function (item) {
                ///udpate trạng thái của thông báo
                //update trạng thái của thông báo thành đã xem, đồng thời load lại số lượng trên cảnh báo
                RESULT = CRUDServices.postdata(item, '/BsHubAPI/api/Task/DMTaskAPI/SaveStatusRead/', 'POST', SessionService.getItems().user_id);
                RESULT.then(function (res) {
                    var total = CRUDServices.getdata({ user_id: SessionService.getItems().user_id },
                  "/SysAPI/api/NoticeAPI/GetTongSLThongBaoTask/", "GET");
                    total.then(function (value) {
                        vm.TongSLCanhBao = value.data > 99 ? 99 : value.data;
                    })
                });
                ///
                var data_edit = {
                    ct: item,
                    paramsearch: {
                        key: '',
                        this_state: $state.current.state == "BSTask",
                        trang_thai: item.status == null ? '0' : item.status,
                        display: "list",
                        defaultView: 'month',
                        ngay_bd: '',
                        ngay_kt: '',
                        view_bd: '',
                        view_kt: '',
                    },
                    status: item.status == null ? '0' : item.status,
                };

                $state.go('BSTask', { params: data_edit });
            }
        }]);

