app.controller('PrintVoucherController', ['$scope', '$state', '$stateParams', 'data', '$dialogs',
    '$uibModalInstance', '$translate', 'CRUDServices', 'SessionService', '$sce',
   function ($scope, $state, $stateParams, data, $dialogs, $uibModalInstance, $translate, CRUDServices, SessionService, $sce) {
       var RESULT;
       $scope.opt = {
           tieu_de: '',
           mau_in: '',
           so_lien: 1,
           so_ct_goc: '',
       }
       //load ds mẫu tin theo mã chứng từ
       $uibModalInstance.rendered.then(function () {
           $scope.ma_ct = data.params.ma_ct;
           var RES = CRUDServices.getdata({ ma_ct: data.params.ma_ct }, '/ExtenAPI/api/LVRBaseExtention/VoucherBaseExtentionAPI/GetListPrintForm', 'GET');
           RES.then(function (value) {
               $scope.list_mauin = value.data.Result;
               if ($scope.list_mauin.length > 0) {
                   $scope.mau_in = $scope.list_mauin[0];
                   //khai báo mẫu in mặc định
                   if (data.params.dataset["mau_in_df"]) {
                       for (var i = 0; i < $scope.list_mauin.length; i++) {
                           if (data.params.dataset["mau_in_df"] == $scope.list_mauin[i].rep_id) {
                               $scope.mau_in = $scope.list_mauin[i];
                               break;
                           }
                       }
                   }
                   $scope.opt = {
                       tieu_de: $scope.mau_in.rep_title,
                       mau_in: $scope.mau_in.rep_id,
                       so_lien: 1,
                       so_ct_goc: ''
                   }
               }
           })
       });
       //gọi phương thức in
       $scope.print = function (opt, print_yn, download_yn) {
           if ($scope.list_mauin.length > 0) {
               data.params.dataset['printoptions'] = _.clone($scope.opt);
               data.params.dataset["download_yn"] = download_yn;
               if (data.params.dataset.ph.status == 0 || data.params.dataset.ph.status == 9) {
                   var text_prev = $translate.instant('sys_view_pre');
                   data.params.dataset['printoptions'].tieu_de = $scope.opt.tieu_de + ' (' + text_prev + ')';
               }
               //nếu chứng từ đang ở trạng thái nháp
               CRUDServices.print(data.params.dataset, data.params.api).then(function (value) {
                   if (value.status == 500 || value.status == 404) {
                       var dialog = $dialogs.notify("notify_header", "notify_error_filenotexists");
                   }
                   else {
                       //4/2/2021: thêm button In. bật hộp thoại Print của trình duyệt nếu nhấn In
                       //in luôn
                       if (print_yn) {
                           var myBlob = new Blob([value.data], { type: 'application/pdf' });
                           var blobURL = (window.URL || window.webkitURL).createObjectURL(myBlob);
                           $scope.content = $sce.trustAsResourceUrl(blobURL);
                           printJS({
                               printable: $scope.content,
                               type: 'pdf'
                           });
                       }
                       else if (download_yn) {
                           var headers = value.headers();
                           var contentType = headers['content-type'];
                           var myBlob = new Blob([value.data], { type: contentType });
                           var blobURL = (window.URL || window.webkitURL).createObjectURL(myBlob);
                           var anchor = document.createElement("a");
                           anchor.download = data.params.dataset['printoptions'].tieu_de + ".xlsx";
                           anchor.href = blobURL;
                           anchor.click();
                       }
                           //xem trước
                       else {
                           var addDialog = $dialogs.create("/Scripts/SYSTEM/Htmls/ViewPDF.html", "ViewPDFController", {
                               file: {
                                   content: value.data,
                                   filename: data.filename
                               }
                           }, { key: false, back: false, size: 'fs' });
                           addDialog.result.then(function (data) {
                           }, function () {
                           });
                       }
                   }
               });
           }
           else {
               setTimeout(function () {
                   $('#tieu_de').focus();
               }, 100);
           }
       }
       $scope.ChangeCombobox = function (data) {
           $scope.opt.tieu_de = data.rep_title;
       }

       $scope.close = function () {
           $uibModalInstance.dismiss('cancel');
       }

   }]);


