app.controller('DashBoardController', ['$scope', '$state', 'CRUDServices', 'Module', '$sce', 'runtimeStates', 'DashboardServices',
function ($scope, $state, CRUDServices, Module, $sce, runtimeStates, DashboardServices) {
    //#region THAM SỐ KHỞI TẠO

    var RESULT;
    var vm = this;
    vm.list_gr_db = [];
    var port = '';
    var first = true;
    var all_state = '';
    vm.group_db_df = {
        ma_group: ''
    }
    var host_graf = "";
    var screenHeight = 0;
    var viewHeight = 0;
    // Biến khai báo cho sự kiện click vào nav top trong Overview
    var menuHeight = 0;
    var elementOffset = 0;
    // Biến khai báo cho sự kiện scroll
    var navbar_main = document.getElementsByClassName("main-nav");
    var navbarLinks;
    var obj_main = document.getElementsByClassName("div-main");
    var langGDB = {};

    // Danh sách menu theo quyền user
    var array_menu = JSON.parse(localStorage.getItem('user_role'));
    // DS Dashboard theo quyền user
    // lấy tất cả menu có type là GDB theo quyền user
    vm.dashboardList = array_menu.filter(function (item) {
        var role = JSON.parse(item.role);
        if (item.type === 'GDB' && item.option_ext && !item.app_yn && role && role.r_access == '1') {
            item['href'] = '#' + item.state;
            return item;
        }
    });

    vm.GoToState = GoToState;
    vm.NavTopScrollHandler = NavTopScrollHandler;
    vm.ToggleContent = ToggleContent;
    vm.CollapseChosen = CollapseChosen;

    //#region Event Client
    vm.SidebarToggle = SidebarToggle;
    function SidebarToggle(e) {
        $('#layoutSidenav').toggleClass('in');
        e.stopPropagation();
    }
    $("#sidebarToggle").click(function (e) {
        $('#layoutSidenav').toggleClass('in');
        e.stopPropagation();
    });
    function GoToState(stateid, evt) {
        $state.go(stateid);
        evt.preventDefault();
        evt.stopPropagation();
    }
    // bắt sự kiện cho thanh điều hướng ds overview
    function NavTopScrollHandler(stateid, href, evt) {
        menuHeight = $('.main-nav').outerHeight(true);
        elementOffset = (document.querySelector(href).offsetTop) - menuHeight;
        state_list = '';
        for (let i = 0; i < vm.dashboardList.length; i++) {
            if (angular.isUndefined(vm.dashboardList[i].ok)) {
                viewHeight += parseFloat(vm.dashboardList[i]['height']);
                vm.dashboardList[i]['ok'] = true;
                // Gán state vào state_list để lấy ds ngôn ngữ theo state
                state_list = state_list + vm.dashboardList[i]['state'] + ',';
                vm.dashboardList[i]['link'] = $sce.trustAsResourceUrl(vm.dashboardList[i]['link_temp']);
            }
            if (vm.dashboardList[i].state == stateid) {
                break;
            }
        }
        DashboardServices.GetLanguagesGrafana(state_list, langGDB);
        $('.div-main').stop().animate({
            scrollTop: elementOffset
        }, 200);
        setTimeout(function () {
            $('#header .main-nav a').removeClass("active");
            $('#header .main-nav a[href="' + href + '"]').addClass("active");
        }, 250);

        evt.preventDefault();
    }
    function ToggleContent(evt, stateid) {
        viewHeight -= $('#' + stateid)[0].clientHeight;
        $('#collapse' + stateid).toggleClass('in');
        viewHeight += $('#' + stateid)[0].clientHeight;
        evt.stopPropagation();
        evt.preventDefault();
    }
    //Scroll main
    obj_main[0].addEventListener("scroll", function (e) {
        var scrollPos = obj_main[0].scrollTop;
        if (viewHeight < (scrollPos + screenHeight / 2)) {
            state_list = '';
            vm.dashboardList.forEach(function (val, index) {
                if (angular.isUndefined(val.ok) && viewHeight < (scrollPos + screenHeight / 2)) {
                    viewHeight += parseFloat(val['height']);
                    val['ok'] = true;
                    // Gán state vào state_list để lấy ds ngôn ngữ theo state
                    state_list = state_list + val['state'] + ',';
                    val['link'] = $sce.trustAsResourceUrl(val['link_temp']);
                }
            });
            DashboardServices.GetLanguagesGrafana(state_list, langGDB);
        }
        navbarLinks = document.querySelectorAll(".main-nav a");
        navbarLinks.forEach(function (link) {
            var section = document.querySelector(link.hash);
            if (scrollPos + 200 > section.offsetTop && scrollPos + 200 < section.offsetTop + section.offsetHeight) {
                link.classList.add("active");
            } else {
                link.classList.remove("active");
            }
        });
    });
    //#endregion


    //#endregion
    (function first() {
        //xử lý user/pass grafana
        var options = JSON.parse(localStorage.options);
        pass_graf = options.CRYPTO_GRAFANA || options.PASS_GRAFANA;
        user_graf = options.USER_GRAFANA;
        host_graf = options.HOST_GRAFANA;
        if (host_graf.lastIndexOf('/') < host_graf.length - 1) {
            host_graf += '/';
        }
        if (runtimeStates.readCookie("vs") == null) {
            runtimeStates.createCookie("vs", user_graf);
        }
        if (runtimeStates.readCookie("va") == null) {
            runtimeStates.createCookie("va", pass_graf);
        }

        if (runtimeStates.readCookie("erp") == null) {
            runtimeStates.createCookie("erp", true);
        }
        //Get_Group_Dashboard();
        var a = host_graf.split(':');
        port = a[a.length - 1];

    })();

    function CollapseChosen() {
        var isCollapsed = $('.row.collapse.in');
        if (isCollapsed.length > 0) {
            $('.dashboard-view').attr('style', 'margin-top: 45px');
            $('.iframe-grafana').css('height', 'calc(100vh - 100px)');
        }
        else {
            $('.dashboard-view').attr('style', 'margin-top: 80px');
            $('.iframe-grafana').css('height', 'calc(100vh - 133px)');
        }
    }

    function Get_Group_Dashboard() {
        if (angular.isUndefined(vm.dashboardList) || vm.dashboardList.length === '') {
            console.log('Không có quyền xem Dashboard');
        }
        else {
            state_list = '';
            screenHeight = ($('body').height() - 95);
            vm.dashboardList.forEach(function (val, index) {
                val['height'] = JSON.parse(val.option_ext).height ? JSON.parse(val.option_ext).height : '410';
                all_state = all_state + val['state'] + ',';
                // Thay thế các params mặc định đăng nhập
                link = JSON.parse(val.option_ext).link;
                let params = [
                    { name: 'ma_dvcs', value: localStorage.dvcs },
                    { name: 'user_id', value: localStorage.user_id },
                    { name: 'lang', value: localStorage.language },
                ];
                link = DashboardServices.ReplaceParamSearch(link, params);
                // Thay đổi link theo máy chủ 
                link = link.replace(link.match(/^(?:https?:\/\/)?(?:[^@\/\n]+@)?(?:www\.)?([^:\/?\n]+)(:\d*)?(\/)?/)[0], host_graf);
                if (window.location.origin != host_graf) {
                    if (window.location.origin.includes('localhost')) {
                        link = link.replace(host_graf, window.location.origin.replace(window.location.port, port));
                    } else {
                        link = link.replace(host_graf, window.location.origin.replace(window.location.port, port));
                    }
                }
                if (viewHeight < screenHeight && index < 1) {
                    runtimeStates.createCookie("redirect_to_overview", link + '&no_menu_left&is_app&no_view');
                    viewHeight += parseFloat(val['height']);
                    val.ok = true;
                    // Gán state vào state_list để lấy ds ngôn ngữ theo state
                    state_list = state_list + val['state'] + ',';
                    val.link = $sce.trustAsResourceUrl(link + '&no_menu_left&is_app&no_view');
                }
                val['link_temp'] = (link + "&no_menu_left&is_app&no_view");
            });
            DashboardServices.GetLanguagesGrafana(state_list, langGDB);
            //DashboardServices.GetParamConfigGrafana(all_state);
        }
    };

    $scope.$watch(function () { return localStorage.language; }, function (newValue) {
        if (newValue) {
            Get_Group_Dashboard();
        }
    });

}]);
;
//Cấu hình và lưu các confing của widget   (ngoài Dashboard main)
app.controller('ConfigWidgetModalController', ['$scope', '$timeout', '$http', 'SessionService', 'data', '$cookies', '$uibModalInstance', 'CRUDServices', 'ConfigGridFactory', '$window', 'Module',
        function ($scope, $timeout, $http, SessionService, data, $cookies, $uibModalInstance, CRUDServices, ConfigGridFactory, $window, Module) {
            //khai báo các biến toàn cục sử dụng
            //#region DECLARE
            var vm = this;
            vm.models = {};
            var res_arr = JSON.parse(data.widget.params_config);
            var params_value = JSON.parse(data.widget.params_value);
            if (res_arr != null) {
                for (var i = 0; i < res_arr.length; i++) {
                    for (var item in params_value) {
                        if (item == res_arr[i].params_name) {
                            res_arr[i].value_df = params_value[item];
                            vm.models[res_arr[i].params_name] = params_value[item];
                            break;
                        }
                    }
                }
                vm.formControls = angular.copy(res_arr);
            } else {
                vm.formControls = [];
            }
            vm.ds_typechart = [
                {
                    value: 'discreteBarChart',
                    name: 'DiscreteBarChart'
                },
                 {
                     value: 'multiBarChart',
                     name: 'Multibarchart'
                 }, {
                     value: 'pieChart',
                     name: 'Piechart'
                 }, {
                     value: 'lineChart',
                     name: 'Linechart'
                 }, {
                     value: 'multiBarHorizontalChart',
                     name: 'Barchart'
                 }];

            vm.ds_widthsize = [{
                value: 2,
                name: '2'
            }, {
                value: 3,
                name: '3'
            }, {
                value: 4,
                name: '4'
            }, {
                value: 5,
                name: '5'
            }, {
                value: 6,
                name: '6'
            }];

            vm.ds_status = [{
                value: false,
                name: 'status_notuse'
            }, {
                value: true,
                name: 'status_using'
            }];


            vm.show_error = false;//thông báo nếu giá trị không đúng

            //chỉ cho chọn kiểu biểu đồ là Piechart nếu đang thể hiện 1 đối tượng
            if (data.widget.col_value == null) data.widget.col_value = data.widget.col_shows;

            vm.check_option_piechart = data.widget.col_value.split(';').length <= 1;

            var RESULT;
            vm.show_save = true;
            vm.edit_modal = true;

            var value_thamso;
            var type_thamso;
            var type_control;
            var css_class = '';

            vm.bieudo = data.widget;

            vm.ten_widget = data.widget.ten_widget;
            //#endregion

            //#region EXTENSION
            //hủy bỏ thao tác, đóng cửa sổ modal, không lưu dữ liệu
            vm.exitDialog = function () {
                $uibModalInstance.dismiss('cancel');
            }
            //lưu dữ liệu, đóng modal, đồng thời hiển thị dữ liệu widget với tham số mới
            vm.saveConfig = function (widget) {
                vm.models['user_id'] = SessionService.getItems().user_id;
                if (angular.isUndefined(vm.models["dfrom"]))
                    vm.models = _.extend(vm.models, { "dfrom": "2018/04/30", "dto": "2021/12/07" });

                vm.bieudo['params_value'] = JSON.stringify(vm.models);
                vm.bieudo["status"] = vm.bieudo["status_show"]
                $uibModalInstance.close(vm.bieudo);
            }
            //nhấn enter để lưu các thông tin 
            $(document).keypress(function (e) {
                if (e.which == 13) {
                    vm.saveConfig(vm.bieudo);
                }
            });
            //#endregion
        }])

//update tham số của widget
app.controller('UpdateParamsWidgetModalController',
    ['$scope', '$timeout', '$http', '$translate', 'SessionService', 'SystemBase', 'data', 'growl', '$cookies', '$uibModalInstance', 'CRUDServices', 'ConfigGridFactory', '$window', 'Module',
        function ($scope, $timeout, $http, $translate, SessionService, SystemBase, data, growl, $cookies, $uibModalInstance, CRUDServices, ConfigGridFactory, $window, Module) {
            //khai báo các biến toàn cục sử dụng
            //#region KHAI BÁO
            SystemBase.Init(data.widget.ma_widget);
            $scope.show_save = true;
            $scope.models = {};
            $scope.formControls = [];
            $scope.ten_widget = data.widget.ten_widget;
            for (var pro in data.widget) {
                if (data.widget.hasOwnProperty(pro)) {
                    if (data.widget[pro] == null)
                        data.widget[pro] = '';
                }
            }
            //#endregion

            LoadData();
            function LoadData() {
                var result = CRUDServices.getdata({ id: data.widget.ma_widget },
               '/ConfigAPI/api/Widget/DashboardConfigAPI/GetParams/', 'GET');
                result.then(function (res) {
                    var res_arr = res.data.Result;
                    for (var i = 0; i < res_arr.length; i++) {
                        var resdata = JSON.parse(data.widget.params_value);
                        for (var item in resdata) {
                            if (item == res_arr[i].params_name) {
                                res_arr[i].value_df = resdata[item];
                                $scope.models[res_arr[i].params_name] = resdata[item];
                                break;
                            }
                        }
                    }
                    //xử lý để khi lưu kiểm tra điều kiện ngày sau phải lớn hơn ngày trước
                    $scope.index_date1 = -1;
                    $scope.index_date2 = -1;
                    for (var i = 0; i < res_arr.length; i++) {
                        if (res_arr[i].control_type == 'date' && $scope.index_date1 < 0) {
                            $scope.index_date1 = i;
                        } else if (res_arr[i].control_type == 'date' && $scope.index_date1 >= 0) {
                            $scope.index_date2 = i;
                            break;
                        }
                    }
                    if ($scope.index_date1 >= 0 || $scope.index_date2 >= 0) {
                        $scope.date1 = res_arr[$scope.index_date1].params_name;
                        $scope.date2 = res_arr[$scope.index_date2].params_name;

                        $scope.title_date1 = res_arr[$scope.index_date1].title;
                        $scope.title_date2 = res_arr[$scope.index_date2].title;
                    }
                    $scope.formControls = angular.copy(res_arr);
                });
            };
            if (data.widget.user_id != data.widget.user_idold && data.from == 'dashboard') {
                $scope.show_save = false;
            }

            //kiểm tra điều kiện cho thay đổi thuộc tính của biểu đồ hay không
            if (data.from == 'groupdt' && (data.widget.user_id == SessionService.getItems().user_id))
                $scope.edit_modal = true;
            else if (data.from == 'dashboard') $scope.edit_modal = true;

            else if (data.from == 'groupdt' && (data.widget.user_id != SessionService.getItems().user_id))
                if (data.widget.user_id == null)
                    $scope.edit_modal = true;
                else $scope.edit_modal = false;

            $scope.bieudo = angular.copy(data.widget);

            //hủy bỏ thao tác, đóng cửa sổ modal, không lưu dữ liệu
            $scope.exitDialog = function () {
                $uibModalInstance.dismiss('cancel');
            }
            //lưu dữ liệu, đóng modal, đồng thời hiển thị dữ liệu widget với tham số mới
            $scope.saveConfig = function () {
                if ($scope.index_date1 > 0 && $scope.index_date2 > 0) {
                    var d1 = new Date($scope.models[$scope.date1]);
                    var d2 = new Date($scope.models[$scope.date2]);
                    if (d2 < d1) {
                        var notice = $translate.instant('e_date1_compare_date2');
                        notice = notice.replace("@value1", $translate.instant($scope.title_date2));
                        notice = notice.replace("@value2", $translate.instant($scope.title_date1))
                        growl.error(notice);
                        return false;
                    }
                }
                $scope.models['user_id'] = SessionService.getItems().user_id;
                $scope.bieudo['params_value'] = $scope.models;
                $uibModalInstance.close($scope.bieudo);
            }
            //nhấn enter để lưu các thông tin 
            $(document).keypress(function (e) {
                if (e.which == 13) {
                    $scope.saveConfig($scope.bieudo);
                }
            });
        }]);

//Xem dữ liệu chi tiết đối với widget dạng biểu đồ
app.controller('ViewDetailChartModalController', ['$scope', 'SessionService', 'ConfigGridFactory', '$cookies', 'data', '$cookies', '$uibModalInstance', 'CRUDServices', 'Module',
       function ($scope, SessionService, ConfigGridFactory, $cookies, data, $cookies, $uibModalInstance, CRUDServices, Module) {
           var from_overview = (data.from == 'overview');
           var from_dashboard = (data.from == 'dashboard');
           var RESULT;
           $scope.file_name = data.pass_widget.ten_widget;
           var arr_prop = Object.keys(data.pass_widget.data_server);
           var prop_first = Object.keys(data.pass_widget.data_server)[0];

           if (arr_prop.length > 1) {
               $scope.res_bind_data = {
                   data_server: []
               };
               var arr_res = [];
               for (var pro in arr_prop) {
                   var arr_deep = data.pass_widget.data_server[arr_prop[pro]];
                   if (arr_deep != undefined && !arr_prop[pro].includes('params') )
                       for (var i = 0; i < arr_deep.length; i++) {
                           arr_deep[i]['type'] = arr_prop[pro];
                           arr_res.push(arr_deep[i]);
                       }
               }
               $scope.res_bind_data.data_server = $scope.res_bind_data.data_server.concat(arr_res);
           } else {
               $scope.res_bind_data = {
                   data_server: data.pass_widget.data_server[prop_first],
               };
           }
           $scope.sortType = ''; // set the default sort type
           $scope.sortReverse = false;  // set the default sort order
           //sắp xếp trên grid
           $scope.OrderBy_GridView = function (map) {
               if ($scope.compare_order != map) {
                   for (var i = 0; i < data.pass_widget.grid.datagrid.my_list_data.length; i++) {
                       if (data.pass_widget.grid.datagrid.my_list_data[i].fieldcaption === map) {
                           $scope.sortType = data.pass_widget.grid.datagrid.my_list_data[i].fieldname;
                           break;
                       }
                   }
                   $scope.compare_order = map;
               } else {
                   if ($scope.sortReverse) $scope.sortReverse = false;
                   else $scope.sortReverse = true;
               }
           }
           $scope.exitDialog = function () {
               $uibModalInstance.dismiss('cancel');
           }

           Kiem_Tra_Factory_Config();

           //lấy cấu hình gridview từ server
           function Kiem_Tra_Factory_Config() {
               //vì ở dashboard có gắn thêm vào mã để xử lý, còn overview thì ko gắn, nên phải tách đoạn này ra
               var grid_id = from_dashboard ? (data.pass_widget.ma_widget).substring(5) : (data.pass_widget.ma_widget)
               var grid_id = {
                   gridid: (data.pass_widget.ma_widget)
               }
               RESULT = CRUDServices.getdata(grid_id, '/ConfigAPI/api/Widget/OverviewConfigAPI/Get_FieldCaption/', 'GET');
               RESULT.then(function (res) {
                   //lấy dữ liệu từ bảng gridInfo : cấu hình các thông số dữ liệu trả về từ tên hàm
                   $scope.my_list_data = typeof res.data.Result === 'string' ? JSON.parse(res.data.Result) : res.data.Result;
                   var config_table = ConfigGridFactory.renderGridview($scope.res_bind_data.data_server, $scope.my_list_data);
                   $scope.list_map = config_table.list_map;
                   $scope.list_map_el = config_table.list_map_el;
                   $scope.list_pro_bind = config_table.list_pro_bind;
               });
           }
           //save file from server
           function base64ToArrayBuffer(base64) {
               var binaryString = window.atob(base64);
               var binaryLen = binaryString.length;
               var bytes = new Uint8Array(binaryLen);
               for (var i = 0; i < binaryLen; i++) {
                   var ascii = binaryString.charCodeAt(i);
                   bytes[i] = ascii;
               }
               return bytes;
           }
           var saveByteArray = (function (data, name, type) {
               return function (data, name, type) {
                   var a = document.createElement("a");
                   document.body.appendChild(a);
                   a.style = "display: none";
                   var blob = new Blob(data, { type: type }),
                       url = window.URL.createObjectURL(blob);
                   a.href = url;
                   a.download = name;
                   a.click();
                   window.URL.revokeObjectURL(url);
               };
           }());
           ///////
           $(document).keypress(function (e) {
               if (e.which == 13) {
                   $uibModalInstance.dismiss('cancel');
               }
           });
       }])

//Xem dữ liệu chi tiết của bản ghi khi click vào mỗi dòng trên griview
//chỉ khả dụng đối với các widget có cấu hình chi tiết
app.controller('ViewDetailGridOnModalController',
   ['$scope', '$cookies', 'data', '$cookies', '$uibModalInstance', '$window',
       'CRUDServices', 'ConfigGridFactory', 'SessionService', 'Module',
       function ($scope, $cookies, data, $cookies, $uibModalInstance, $window,
           CRUDServices, ConfigGridFactory, SessionService, Module) {
           var RESULT;
           var widget = data.pass_widget;

           //mã widget sẽ thêm đuôi _CT để phân biệt, đã cấu hình dưới bảng CSDL
           var ma_widget_ct = data.pass_widget.ma_widget + '_CT';
           $scope.pass_data = data.pass_data;
           $scope.ten_widget = data.pass_widget.ten_widget;
           $scope.item_focus = $scope.pass_data[data.pass_widget.detail_pro.property];
           $scope.name_focus = data.pass_widget.detail_pro.property;

           //truyền tên function và giá trị tham số về server để lấy dữ liệu
           var paras = {
               ten_ham: widget.command_fun_details, //tên hàm xem chi tiết trên gridview
               tham_so: data.params_value,
               user_name: SessionService.getItems().user_name,
               lst_params: widget.params_fun_details,
               lst_type: widget.params_type_details,
               ma_widget: ma_widget_ct,
               offset: 0
           };
           GetData_FromServer(paras);

           $scope.sortType = ''; // set the default sort type
           $scope.sortReverse = false;  // set the default sort order
           //sắp xếp trên grid
           $scope.OrderBy_GridView = function (map) {
               if ($scope.compare_order != map) {
                   for (var i = 0; i < data.pass_widget.grid.datagrid.my_list_data.length; i++) {
                       if (data.pass_widget.grid.datagrid.my_list_data[i].fieldcaption === map) {
                           $scope.sortType = data.pass_widget.grid.datagrid.my_list_data[i].fieldname;
                           break;
                       }
                   }
                   $scope.compare_order = map;
               } else {
                   if ($scope.sortReverse) $scope.sortReverse = false;
                   else $scope.sortReverse = true;
               }
           }

           //lấy thông tin từ function chi tiết
           function GetData_FromServer(paras) {
               RESULT = CRUDServices.getdata(paras, '/ConfigAPI/api/DashboardConfigAPI/Get_DataDetailGridview/', 'GET');
               RESULT.then(function (res) {
                   var data = JSON.parse(res.data);
                   $scope.totalItems = data.total_record;
                   $scope.res_bind_data = {
                       data_server: data.data_return,
                   };
                   //lấy cấu hình gridview từ server
                   var config_table = ConfigGridFactory.renderGridview(data.data_return, data.data_config)
                   $scope.list_map = config_table.list_map;
                   $scope.list_map_el = config_table.list_map_el;
                   $scope.list_pro_bind = config_table.list_pro_bind;
               });
           };

           //kiểm tra sự tồn tại để update vào factory
           //Kiem_Tra_Factory_Config(data_bind);

           //kiểm tra dữ liệu trong factory: lưu trữ cấu hình của dashboard
           function Kiem_Tra_Factory_Config() {
               if (ConfigGridFactory.getItems().length == 0) {
                   //push thêm dữ liệu vào factory
                   var grid_id = {
                       gridid: (data.pass_widget.ma_widget.substring(5)) + "_MDCT"
                   }
                   //lấy dữ liệu từ server
                   RESULT = CRUDServices.getdata(grid_id,
                       '/ConfigAPI/api/widget/OverviewConfigAPI/Get_FieldCaption/', 'GET');
                   RESULT.then(function (res) {
                       //lấy dữ liệu từ bảng gridInfo : cấu hình các thông số dữ liệu trả về từ tên hàm
                       $scope.my_list_data = JSON.parse(res.data);
                       //thêm vào factory lưu trữ
                       ConfigGridFactory.addItem({
                           ma_widget: data.pass_widget.ma_widget,
                           data_sys_arr: $scope.my_list_data
                       });
                       //GetData_Server();
                   });
               }
               else {
                   var grid_id = {
                       gridid: (data.pass_widget.ma_widget.substring(5)) + "_MDCT"
                   }
                   RESULT = CRUDServices.getdata(grid_id,
                       '/ConfigAPI/api/Widget/OverviewConfigAPI/Get_FieldCaption/', 'GET');
                   RESULT.then(function (res) {
                       //lấy dữ liệu từ bảng gridInfo : cấu hình các thông số dữ liệu trả về từ tên hàm
                       $scope.my_list_data = JSON.parse(res.data);
                       var data_push = {
                           ma_widget: data.pass_widget.ma_widget,
                           data_sys_arr: $scope.my_list_data
                       }
                       //thêm vào factory lưu trữ
                       ConfigGridFactory.addItem(data_push);
                       GetData_Server();
                   });
               }
           }
           //lấy dữ liệu từ server để hiển thị lên giao diện
           function GetData_Server() {
               //lấy header của gridview
               var pass_data =
                {
                    user_id: data.pass_data.user_id,
                }
               RESULT = CRUDServices.getdata(pass_data,
                   '/ConfigAPI/api/DashboardConfigAPI/Get_DetailRowOnDashboard/', 'GET',
                   SessionService.getItems().user_id);
               RESULT.then(function (res) {
                   $scope.res_bind_data = {
                       task_notyet: JSON.parse(res.data.task_notyet),
                       task_ok: JSON.parse(res.data.task_ok)
                   };
                   View_Data_Table();
               });
           }
           ///////
           $(document).keypress(function (e) {
               if (e.which == 13) {
                   $uibModalInstance.dismiss('cancel');
               }
           });

           $scope.exitDialog = function () {
               $uibModalInstance.dismiss('cancel');
           }
       }])

