app.controller('CreateNewFolderModalController', ['$scope', '$state', '$stateParams', 'data',
    '$uibModalInstance', 'CRUDServices', 'SessionService', '$dialogs', '$cookies', 'Module',
   function ($scope, $state, $stateParams, data, $uibModalInstance, CRUDServices, SessionService, $dialogs, $cookies, Module) {
       var res_level_folder = 0;

       var currentParentFolder = JSON.parse(localStorage.getItem('parentCurrent'));
       if (currentParentFolder == null)
           currentParentFolder = {
               ds_bp_share_f: '',
               ds_bp_share_r: '',
               ds_bp_share_w: '',
               ds_user_share_f: '',
               ds_user_share_r: '',
               ds_user_share_w: '',
           }
       //console.log(currentParentFolder);
       setTimeout(function () {
           $('#name_folder').focus();
       }, 200)
       var url_path = data.params.widget.url_path;
       url_path = url_path ? url_path : SessionService.getItems().user_id;
       //kiểm tra để xác định level của thư mục

       if (data.params.parent_doc == 0)
           res_level_folder = 1;
       else {
           res_level_folder = data.params.widget.level_folder + 1;
       };

       //tạo thư mục lưu vào trong CSDL
       $scope.CreateNewFolder = function (name_folder) {
           if (name_folder != '' && name_folder != null) {
               var module = Module;
               var var_add = {
                   file_name: name_folder,
                   file_name2: name_folder,
                   parent_doc: data.params.id != null ? data.params.id : 1,
                   size: 0,
                   status: 1,
                   url_path: url_path + "/{#}",  //lưu tạm {#} để xử lý update sau khi đã tạo thành công folder
                   headers: '',
                   type_doc: 'folder',
                   type_icon: 'icon-folder',
                   module: module,
                   folder_yn: true,
                   user_id0: SessionService.getItems().user_id,
                   level_folder: res_level_folder,
                   ds_bp_share_f: currentParentFolder.ds_bp_share_f,
                   ds_bp_share_r: currentParentFolder.ds_bp_share_r,
                   ds_bp_share_w: currentParentFolder.ds_bp_share_w,
                   ds_user_share_f: currentParentFolder.ds_user_share_f,
                   ds_user_share_r: currentParentFolder.ds_user_share_r,
                   ds_user_share_w: currentParentFolder.ds_user_share_w,
               };
               RESULT = CRUDServices.postdata(var_add, '/ConfigAPI/api/Document/DocumentConfigAPI/CreateNewFolder/', 'POST');
               RESULT.then(function (res) {
                   $uibModalInstance.close(JSON.parse(res.data.Result));
               });
           }
           else {
               $('#name_folder').focus();
           }
       }
       $scope.close = function () {
           $uibModalInstance.dismiss('cancel');
       }
   }]);

;
