    vm.index_object = 0;
    //thay đổi đối tượng view của biểu đồ tròn khi có từ hai đối tượng trở lên
    vm.ChangeObjectPieChart = function (widget) {
        if (widget.indexObject == 0) {
            widget.indexObject = 1;
            vm.index_object = 0;
        }
        else if (widget.indexObject == 1) {
            widget.indexObject = 0;
            vm.index_object = 1;
        }
        if (localStorage.language == 'vi-VN') {
            vm.object_piechart = widget.col_shows.split(';')[widget.indexObject];
        }
        else {
            vm.object_piechart = widget.col_shows2.split(';')[widget.indexObject];
        }
        widget.chart.data = widget.chart.store[widget.indexObject].values;
        widget.titleText = vm.object_piechart;
        widget.chart.options.title = {
            enable: widget.type_chart == 'pieChart' && widget.col_shows.split(';').length == 2 ? true : false,
            text: widget.titleText,
            className: 'h5',
            css: {
                textAlign: 'center',
                color: widget.indexObject == 0 ? 'green' : 'red'
            }
        };
        vm.refresh_no_update(widget);
        if (localStorage.language == 'vi-VN') {
            vm.object_piechart = widget.col_shows.split(';')[vm.index_object];
        }
        else {
            vm.object_piechart = widget.col_shows2.split(';')[vm.index_object];
        }
    };

    //click trên menu của widget
    vm.ClickMenu = function (item, widget) {
        switch (item.menuid) {
            case 'reload':
                vm.refresh(widget);
                break;
            case 'viewdetail':
                vm.viewdetail(widget);
                break;
            case 'setting':
                vm.setting(widget);
                break;
            case 'filter':
                vm.setting(widget);
                break;
            case 'list':
                if (widget.ma_widget == 'THONG_BAO')
                    $state.go("Notification")
                break;
            case 'add':
                if (widget.ma_widget == 'MY_WORK')
                    vm.add_new_task(widget);
                break;
            default:
        }
    }
    //xem cấu hình và điều chỉnh các widget có kiểu là biểu đồ
    vm.setting = function (widget) {

        var createdialog = $dialogs.create("/CONFIG/Overview/SettingWidgetModal", "OverviewModalController as ctrl", {
            widget: widget,
            from: 'overview'
        }, {
            key: true,
            back: true,
            size: 'md'
        });
        createdialog.result.then(function (data) {
            vm.temp_widget = data;
            var widgetconfig = {
                ma_widget: data.ma_widget,
                ma_group: data.ma_group,
                user_id: data.user_id,
                user_name: data.user_name,
                status: data.status,
                sizeX: parseInt(data.sizeX),
                sizeY: parseInt(data.sizeY),
                unit_value: data.unit_value,
                is_grid: data.is_grid,
                wid_sizex: data.wid_sizex,
                type_chart: data.type_chart,
                params_value: data.params_value,

            };

            if (widgetconfig.status == true || widgetconfig.status == 'True') {
                widgetconfig.ten_widget = widget.ten_widget.replace(widget.params_value, widgetconfig.params_value);
                widget.ten_widget = widgetconfig.ten_widget;
            }
            else {
                vm.remove(widget);
            }
            //tránh trường hợp vừa upadte vừa refresh (làm biểu đồ giật 2 lần)
            //trong tường hợp thay đổi kiểu từ biểu đồ sang grid và ngược lại
            var _check_refresh = false;
            if (data.is_grid != widget.is_grid) {
                _check_refresh = true;
            }
            widget.is_grid = widgetconfig.is_grid;

            if (widget.chart.api != null) {
                if (localStorage.language == 'vi-VN')
                    vm.object_piechart = widget.col_shows.split(';')[widget.indexObject];
                else vm.object_piechart = widget.col_shows2.split(';')[widget.indexObject];
                var passdata = {
                    widget: widget,
                    format_money_yn: true,
                    index_object: widget.indexObject,
                    current_height: vm.currentHeight
                };

                widget.chart.options.chart = ChartOptions.Options_Config_Chart(passdata);//update cấu hình  cho biểu đồ
                widget.chart.options.title = {
                    enable: data.type_chart == 'pieChart' && data.col_shows.split(';').length == 2 ? true : false,
                    text: widget.titleText,
                    className: 'h5',
                    css: {
                        textAlign: 'center',
                        color: widget.indexObject == 0 ? 'green' : 'red'
                    }
                };
                vm.object_piechart = widget.col_shows.split(';')[1];
            }
            if (widget.type_chart != data.type_chart) {
                vm.object_piechart = widget.col_shows.split(';')[widget.indexObject];
                //chuyển đổi dữ liệu cho kiểu biểu đồ mới
                widget.chart.data = ChartOptions.Exchange_Data_Between_Chart(data.type_chart, widget, data.col_shows, vm.object_piechart);
            }
            //nếu đang trong sự kiện full màn hình, kiểm tra độ rộng
            if (vm.check_fullscreen != null) {
                if (!vm.this_mobile) {
                    widget.chart.options.chart.height = (1 / 2) * $(window).height() + (1 / 3) * $(window).height();
                }
                else widget.chart.options.chart.height = 280;
            }

            //căn lại chiều cao của biểu đồ
            if (widgetconfig.sizeY > 1)
                widget.chart.options.chart.height = (widget.chart.options.chart.height * parseInt(widgetconfig.sizeY)) + 50;
            widget.type_chart = widgetconfig.type_chart;

            ////////////////////////////////////

            if (widgetconfig.params_value != widget.params_value) {
                //nếu thay đổi tham số thì phải set limit và offset về giá trị khởi tạo, để lazyloading
                //nếu là grid và trong tham số có tham biến là offset thì phải set lại giá trị của offset để lazyloading
                if (widgetconfig.params_value.hasOwnProperty('poffset'))
                    widgetconfig.params_value['poffset'] = 0;

                var paras = {
                    command_name: widget.command_fun,
                    params_value: widgetconfig.params_value,
                    is_grid: widget.is_grid,
                    lst_params: widget.params_name,
                    lst_type: widget.params_type,
                    ma_widget: widget.ma_widget,
                    offset: 0,
                    params_default: widget.params_default,
                    params_typedate: widget.params_typedate
                };
                var config = {
                    ma_widget: widget.ma_widget,
                    type_chart: widget.type_chart,
                    col_shows: widget.col_shows,
                    col_value: widget.col_value,
                    col_name: widget.col_name
                };
                //gọi hàm update dữ liệu cho biểu đồ

                if (data.status)
                    Update_Data_With_NewPara(paras, config, widget, false);
                else {
                    vm.dashboards.arrwidget.splice(jQuery.inArray(data, vm.dashboards.arrwidget), 1);
                }

                for (var i = 0; i < vm.dashboards.arrwidget.length; i++) {
                    if (vm.dashboards.arrwidget[i].ma_widget == data.ma_widget) {
                        vm.dashboards.arrwidget[i].params_value = data.params_value;
                        break;
                    }
                }

            }
            /////
            //NẾU BIỂU ĐỒ CÓ ĐỘ RỘNG TRÀN RA NGOÀI DASHBOARD THÌ ĐẨY XUỐNG DÒNG DƯỚI
            if (widget.col + parseInt(widget.wid_sizex) > 6) {
                widget.row = widget.row + 1;
            }
            if (!widgetconfig.is_grid) {
                $timeout(function () {
                    if (widget.chart.api != null) {
                        widget.chart.api.update();
                        if (_check_refresh || true) {//tránh trường hợp vừa update vừa refresh
                            widget.chart.api.refresh();
                        }
                    }
                }, 500);
            };
            //refresh lại để tránh trường hợp piechart có các vùng biểu diễn dữ liệu trùng màu sắc
            if (widget.type_chart == 'pieChart') {
                vm.refresh_no_update(widget);
                vm.ChangeObjectPieChart(widget)
            }

        }, function () { });
    };


