    //thay đổi tham số tùy chọn điều kiện lọc
    vm.ViewDataByFilter = function (days, widget, qua_han, hoan_thanh, events) {
        //thay đổi màu nền của lựa chọn đc chọn
        var arr_list = $("#DROP" + widget.ma_widget).find("li");
        for (var i = 0; i < arr_list.length; i++) {
            if ($(arr_list[i]).hasClass("active")) {
                $(arr_list[i]).removeClass("active");
                break;
            }
        }
        $(events.target).parent("li").addClass("active");
        //lấy vị trí của phần tử để thay đổi giá trị của tham số 
        var arr_params_value_name = widget.params_name.split(";");
        var index_days = arr_params_value_name.indexOf("_number");
        var index_qua_han = arr_params_value_name.indexOf("_overdue");
        var index_hoan_thanh = arr_params_value_name.indexOf("_complete");
        var arr_params_value_value = widget.params_value.split(";");
        var days_old = (arr_params_value_value[index_days])
        arr_params_value_value[index_days] = days;
        arr_params_value_value[index_qua_han] = qua_han;
        arr_params_value_value[index_hoan_thanh] = hoan_thanh;
        widget.params_value = arr_params_value_value.join(';');
        vm.refresh(widget);
        var res_text_new = ConvertDaysFilterToText(days);
        var text_days_old = ConvertDaysFilterToText(days_old);
        widget.ten_widget = widget.ten_widget.replace(text_days_old.res_text_vn.toString(), res_text_new.res_text_vn);
        widget.ten_widget2 = widget.ten_widget2.replace(text_days_old.res_text_en.toString(), res_text_new.res_text_en);
        //widget.grid.datagrid.my_server_data = [];
    }
    function ConvertDaysFilterToText(days) {
        days = parseInt(days);
        var res_text = {};
        switch (days) {
            case 0:
                {
                    res_text.res_text_vn = "hôm nay";
                    res_text.res_text_en = "today";
                    return res_text;
                }
            case 1:
                {
                    res_text.res_text_vn = "ngày mai";
                    res_text.res_text_en = "tomorrow";
                    return res_text;
                }
            case 2:
                {
                    res_text.res_text_vn = "ngày tiếp theo";
                    res_text.res_text_en = "The day after tomorrow";
                    return res_text;
                }
            case -7:
                {
                    res_text.res_text_vn = "đã hoàn thành (7 ngày gần nhất)";
                    res_text.res_text_en = "completed last 7 days";
                    return res_text;
                }
            default:
                {
                    res_text.res_text_vn = "đã quá hạn";
                    res_text.res_text_en = "overdue";
                    return res_text;
                }
        }
    }
