    vm.arr_mawidget_lazyload = [];

    ///
    vm.list_db = [];
    vm.list_db_view = [];
    vm.list_gr_db = [];

    vm.my_widget_pos = [];
    vm.widget_size_list = [];
    //#endregion
    //thu nhỏ menu để nhìn dashboad

    //HÀM CHẠY KHI LOAD 
    //kiểm tra thiết bị có phải là mobile ko
    vm.this_mobile = (localStorage.getItem('isMobile') == 'false' ? false : true);
    //cấu hình vùng vẽ biểu đồ widget           
    (function () {
        //nếu độ rộng màn hình nhỏ thì chỉ drag đc khi người dùng di chuột vào tiêu đề biểu đồ
        //ngược lại thì có thể di chuột tại header của widget
        var width_screen = (window.innerWidth > 0) ? window.innerWidth : screen.width;
        if (width_screen <= 767) width_screen = '.widget-title';
        else width_screen = '.widget-header';
        if (vm.this_mobile) vm.grid_height = 400;
        else vm.grid_height = 360;
        vm.gridsterOptions = {
            isMobile: false, // stacks the grid items if true
            mobileBreakPoint: 720, // if the screen is not wider that this, remove the grid layout and stack the items
            mobileModeEnabled: true, //true: nếu độ rộng màn hình nhỏ hơn mobileBreakPoint -> chuyển sang chế độ Mobile;và ngược lại 
            margins: [5, 10],//khoảng cách giữa các vùng widget
            columns: 6, //chiều rộng set max là 6 cột  
            width: 'auto', //chiều rộng của widget 
            colWidth: 'auto', // can be an integer or 'auto'.  'auto' uses the pixel width of the element divided by 'columns'
            rowHeight: 'match', //set chiều cao theo pixcel (1 dòng tương đương bao nhiêu pixcel)

            defaultSizeX: 6, //mặc định chiều rộng là 6 cột
            defaultSizeY: 1, // the default height of a gridster item, if not specified
            maxSizeY: 4, //chiều cao tối đa của widget
            maxSizeX: 6, //chiều rộng tối đa (tương ứng 6 cột)
            minSizeX: 2, //chiều rộng tối thiều (tương ứng 1 cột)
            minRows: 2, //dòng tối thiêu (tương ứng 1 dòng)
            resizable: {
                enabled: true,
                handles: ['n', 'e', 's', 'w', 'ne', 'se', 'sw', 'nw'],
                start: function (event, $element, widget) {
                    //chèn lưới vào grid để người dùng căn chỉnh phù hợp
                    $("#Gridster").addClass("show_gridlines");
                },
                resize: function (event, $element, widget) { },
                stop: function (event, $element, widget) {
                    //chèn lưới vào grid để người dùng căn chỉnh phù hợp
                    $("#Gridster").removeClass("show_gridlines");
                    vm.state_save = true;
                    AfterResizeWidget(vm.dashboards.arrwidget, widget);
                    if (widget.is_chart) {
                        if (widget.chart.api != null) {
                            widget.chart.api.refreshWithTimeout(500);
                        }
                    }
                    //update lại chiều cao của widget dạng table gridview
                    setTimeout(function () {
                        document.getElementById('tbody-' + widget.ma_widget).style.height = (vm.currentHeight * widget.sizeY) - (widget.sizeY * 10) + "px";
                        document.getElementById(widget.ma_widget).style.height = (vm.currentHeight * widget.sizeY) - (widget.sizeY * 10) + "px";
                    }, 100);
                }
            },
            draggable: {
                enabled: true,
                handle: '.text-limit2',
                start: function (event, $element, widget) {
                    //chèn lưới vào grid để người dùng căn chỉnh phù hợp
                    $("#Gridster").addClass("show_gridlines");
                },
                drag: function (event, $element, widget) { },
                stop: function (event, $element, widget) {
                    var check_drag = false;
                    //chèn lưới vào grid để người dùng căn chỉnh phù hợp
                    $("#Gridster").removeClass("show_gridlines");
                    vm.state_save = true;

                    for (var i = 0; i < vm.my_widget_pos.length; i++) {
                        if (widget.ma_widget == vm.my_widget_pos[i].ma_widget) {
                            if (widget.col != vm.my_widget_pos[i].col || widget.row != vm.my_widget_pos[i].row) {
                                check_drag = true;
                                vm.my_widget_pos.splice(i, 1);
                                vm.my_widget_pos.push({
                                    ma_widget: widget.ma_widget,
                                    col: widget.col,
                                    row: widget.row
                                });
                                break;
                            }
                        }
                    }
                }
            }
        }
        //tự động điều chỉnh kích thước biểu đồ khi màn hình thay đổi kích thước    
        vm.events = {
            //nếu k là điện thoại
            resize: function (e, scope) {
                var type_chart = scope.options.chart.type;
                if (!vm.this_mobile && type_chart != "") {
                    if (scope.api && scope.api.update) {
                        scope.api.refreshWithTimeout(200);
                    }
                }
            },
            //nếu là điện thoại
            orientationchange: function (e, scope) {
                if (vm.this_mobile) {
                    scope.api.refreshWithTimeout(200);
                }
            }
        };
        vm.config = {
            visible: false,
            deepWatchData: false,
            refreshDataOnly: true
        };
        //lấy độ rộng của thiết bị hiện tại
        vm.width_wid = $(window).width();
        $timeout(function () {
            vm.config.visible = true;
        }, 200);
        angular.element(window).on('resize', function (e) {
            AfterResizeWidget(vm.dashboards.arrwidget);
        });
        //sự kiện xoay ngang-dọc thiết bị di động
        angular.element(window).on('orientationchange', function (event) {
            if (event.orientation) {
                vm.orientation_check = event.orientation;
                if (vm.check_fullscreen != null) {
                    for (var i = 0; i < vm.widget_size_list.length; i++) {
                        if (vm.check_fullscreen.ma_widget === vm.widget_size_list[i].ma_widget) {
                            vm.check_fullscreen.chart.options.chart.height = vm.widget_size_list[i].wid_height;
                            vm.check_fullscreen.chart.options.chart.width = vm.widget_size_list[i].wid_width;
                            break;
                        }
                    }
                    //remove class css full màn hình
                    $('#' + vm.check_fullscreen.ma_widget).removeClass("fullscreen");
                    vm.check_fullscreen.chart.api.updateWithOptions(vm.check_fullscreen.chart.options);
                    vm.check_fullscreen.chart.api.update();
                    vm.check_fullscreen = null;
                }
                $rootScope.$broadcast('orientationchange');
            }
        });
    })();
    var check = null;
    vm.list_db_test = [];
    (function init() {
        Get_ListWidgets();
        vm.data = [];
    })();

    //render vùng vẽ biểu đồ, có sử dụng lazy-loading
    //lưu lại kích thước của tất cả vùng widget sau khi repeat hoàn thành
    $scope.$on('ngRepeatFinished', function (event) {
        AfterResizeWidget(vm.dashboards.arrwidget);
        if (vm.widget_size_list.length < vm.dashboards.arrwidget.length) {
            $.each(vm.dashboards.arrwidget, function (i) {
                vm.widget_size_list.push({
                    ma_widget: vm.dashboards.arrwidget[i].ma_widget,
                    wid_width: $('#' + vm.dashboards.arrwidget[i].ma_widget).width(),
                    wid_height: $('#' + vm.dashboards.arrwidget[i].ma_widget).height()
                });
            });
        }
        else return;
    })
