    //chức năng ẩn hiển vùng danh sách, mở rộng vùng edit
    vm.Hide_ShowListWidget = function () {
        setTimeout(function () {
            $window.dispatchEvent(new Event("resize"));
        }, 100);
        if (vm.showlist_yn) {
            vm.showlist_yn = false;
            vm.showlist_class = 'ti-layout-sidebar-none';
        } else {
            vm.showlist_yn = true;
            vm.showlist_class = 'ti-layout-sidebar-left';
        }
    }

    vm.addItem = function (data) {
        vm.Add_Widget(data.widget);
    }
    //thêm widget vào overview
    vm.Add_Widget = function (widget) {
        if (JSON.CheckExistInArray('command_fun', widget.command_fun, vm.dashboards.arrwidget) < 0) {
            vm.arr_add.push(widget);
            var params_value = 'null';
            widget.using_yn = true;
            var paras = {
                command_name: widget.command_fun,
                is_grid: widget.is_grid,
                params_default: widget.params_default, //format tham số được lưu trong bảng
                params_value: widget.params_value, //giá trị tham số đc lưu trong bảng
                lst_params: widget.params_name,
                lst_type: widget.params_type,
                ma_widget: widget.ma_widget,
                params_typedate: widget.params_typedate,
                offset: 0
            };
            var my_dashboard = widget;
            my_dashboard["user_idold"] = SessionService.getItems().user_id;
            my_dashboard["wid_row"] = 2;
            my_dashboard["wid_col"] = 2;

            my_dashboard["sizeX"] = widget.wid_sizex;
            my_dashboard["sizeY"] = widget.wid_sizey;

            my_dashboard["height"] = vm.currentHeight;
            my_dashboard["params_value"] = params_value;
            //có sự thay đổi thì hiển thị button lưu lại overview
            vm.state_save = true;
            ProcessingDataFromSever(paras, my_dashboard, true);
        }
        else
            $dialogs.notify("notify_header", "notify_this_widget_added");
    }
    //xem cấu hình và điều chỉnh  - OK
    vm.setting = function (widget) {
        var createdialog = $dialogs.create("/CONFIG/Overview/SettingWidgetModal", "OverviewModalController as ctrl", {
            widget: widget,
            from: 'setting'
        }, { key: true, back: true, size: 'md' });
        createdialog.result.then(function (data) {
            data.user_name = SessionService.getItems().user_name;
            var view = {
                ma_widget: data.ma_widget,
                ten_widget: data.ten_widget,
                ten_widget2: data.ten_widget2,
                type_chart: data.type_chart,
                command_fun: data.command_fun,
                params_value: data.params_value,
                col_shows: data.col_shows,
                col_shows2: data.col_shows2,
                unit_value: data.unit_value,
                chieu_rong: data.chieu_rong,
                col_name: data.col_name,
                col_name2: data.col_name2,
                col_value: data.col_value,
                wid_row: data.row,
                wid_col: data.col,
                wid_sizex: data.sizeX,
                wid_sizey: data.sizeY,
                user_id: data.user_id,
                user_name: data.user_name,
                status: data.status,
                is_chart: data.is_chart,
                module: Module
            };
            //update thông tin cài đặt cho mỗi widget và theo từng user
            RESULT = CRUDServices.postdata({ view: view }, '/ConfigAPI/api/Widget/OverviewConfigAPI/Put_ConfigChartUser/', 'PUT', SessionService.getItems().user_id);
            RESULT.then(function (res) {
                vm.state_save = true;
                for (var i = 0; i < vm.dashboards.arrwidget.length; i++) {
                    if (vm.dashboards.arrwidget[i].ma_widget === view.ma_widget) {
                        vm.dashboards.arrwidget[i].ten_widget = data.ten_widget;
                        vm.dashboards.arrwidget[i].status = data.status;
                        vm.dashboards.arrwidget[i].view_number = data.view_number;
                        vm.dashboards.arrwidget[i].wid_sizex = data.wid_sizex;
                        break;
                    }
                }
                widget.sizeX = parseInt(data.wid_sizex);
                if (widget.chart.api != null) {
                    if (localStorage.language == 'vi-VN')
                        vm.object_piechart = widget.col_shows.split(';')[widget.indexObject];
                    else vm.object_piechart = widget.col_shows2.split(';')[widget.indexObject];
                    var passdata = {
                        widget: widget,
                        format_money_yn: true,
                        index_object: widget.indexObject,
                        current_height: vm.currentHeight
                    };
                    widget.chart.options.chart = ChartOptions.Options_Config_Chart(passdata);//update cấu hình  cho biểu đồ

                    widget.chart.options.title = {
                        enable: data.type_chart == 'pieChart' && data.col_shows.split(';').length == 2 ? true : false,
                        text: widget.titleText,
                        className: 'h5',
                        css: {
                            textAlign: 'center',
                            color: widget.indexObject == 0 ? 'green' : 'red'
                        }
                    };
                    vm.object_piechart = widget.col_shows.split(';')[1];
                }
                if (widget.type_chart != data.type_chart) {
                    vm.object_piechart = widget.col_shows.split(';')[widget.indexObject];
                    //chuyển đổi dữ liệu cho kiểu biểu đồ mới
                    widget.chart.data = ChartOptions.Exchange_Data_Between_Chart(data.type_chart, widget, data.col_shows, vm.object_piechart);
                }
                //nếu đang trong sự kiện full màn hình, kiểm tra độ rộng
                if (vm.check_fullscreen != null) {
                    if (!vm.this_mobile) {
                        widget.chart.options.chart.height = (1 / 2) * $(window).height() + (1 / 3) * $(window).height();
                    }
                    else widget.chart.options.chart.height = 280;
                }
                widget.type_chart = view.type_chart;

                ////////////////////////////////////
                if (view.params_value != widget.params_value) {
                    widget.params_value = view.params_value;
                    //nếu là grid và trong tham số có tham biến là offset thì phải set lại giá trị của offset để lazyloading
                    if (widget.params_name.includes("_offset") || widget.params_name.includes("poffset")) {
                        var name_params = widget.params_name.split(';');
                        var value_params = view.params_value.split(';');
                        value_params[name_params.indexOf("_offset")] = 0;
                        value_params[name_params.indexOf("poffset")] = 0;
                        view.params_value = value_params.join(';');
                    }
                    ///
                    var paras = {
                        command_name: widget.command_fun,
                        params_value: view.params_value,
                        is_grid: widget.is_grid,
                        lst_params: widget.params_name,
                        lst_type: widget.params_type,
                        ma_widget: widget.ma_widget,
                        offset: 0
                    };
                    var config = {
                        ma_widget: widget.ma_widget,
                        type_chart: widget.type_chart,
                        col_shows: widget.col_shows,
                        col_value: widget.col_value,
                        col_name: widget.col_name
                    }
                    //gọi hàm update dữ liệu cho biểu đồ
                    if (data.status)
                        Update_Data_With_NewPara(paras, config, widget, false);
                    else {
                        var chiso = jQuery.inArray(data, vm.dashboards.arrwidget);
                        vm.dashboards.arrwidget.splice(chiso, 1);
                    }
                }
                /////
                //NẾU BIỂU ĐỒ CÓ ĐỘ RỘNG TRÀN RA NGOÀI DASHBOARD THÌ ĐẨY XUỐNG DÒNG DƯỚI
                if (widget.col + parseInt(widget.wid_sizex) > 6) {
                    widget.row = widget.row + 1;
                }
                if (view.is_chart) {
                    $timeout(function () {
                        if (widget.chart.api != null) {
                            //widget.chart.api.update();
                            //if (_check_refresh) {//tránh trường hợp vừa update vừa refresh
                            widget.chart.api.refresh();
                            //}
                        }
                    }, 500);
                };
                //refresh lại để tránh trường hợp piechart có các vùng biểu diễn dữ liệu trùng màu sắc
                if (widget.type_chart == 'pieChart') {
                    vm.refresh_no_update(widget);
                    vm.ChangeObjectPieChart(widget)
                }
            });
        }, function () { });
    }

    //làm tươi từng biểu đồ đc chọn 
    vm.refresh = function (widget) {
        //nếu là dạng bảng thì mới xử lý lazyloading
        if (widget.is_grid) {
            // nếu là widget là dạng thống kê TOP, thì ko có lazyloading
            var index = widget.ma_widget.includes("top") || widget.ma_widget.includes("TOP");
            if (!index) {
                widget.params_value = Execute_ThamSo(0, widget);
            }
        }

        //lấy data từ server
        var paras = {
            command_name: widget.command_fun,
            params_value: widget.params_value,
            is_grid: widget.is_grid,
            lst_params: widget.params_name,
            lst_type: widget.params_type,
            ma_widget: widget.ma_widget,
            offset: 0
        };
        var config = {
            ma_widget: widget.ma_widget,
            type_chart: widget.type_chart,
            col_shows: widget.col_shows,
            col_value: widget.col_value,
            col_name: widget.col_name
        }
        //làm mới dữ liệu 
        Update_Data_With_NewPara(paras, config, widget, false);

        //update lại data của biểu đồ khi có sự thay đổi tham số
        if (widget.is_chart) {
            if (widget.chart.api != null) {
                widget.chart.api.refreshWithTimeout(500);
            }
        }
    }

    function ReturnBoolean(string) {
        if (string != null) string = string.toString();
        if ((string.toUpperCase()) == "TRUE" || string) return true;
        else if ((string.toUpperCase()) == "FALSE" || string) return false;
        else if (string == null) return false;
        else return false;
    }

    //---------------
    //function apply
    vm.safeApply = function (fn) {
        var phase = this.$root.$$phase;
        if (phase == '$apply' || phase == '$digest') {
            if (fn && (typeof (fn) === 'function')) {
                fn();
            }
        } else {
            this.$apply(fn);
        }
    };
    //xem bảng biểu chi tiết - OK
    //#endregion
    //lazy loading các widgets
    //#region XỬ LÝ HIỂN THỊ DỮ LIỆU
    vm.PagingMain = function () {
        if (reachedLast) {
            return false;
        }
        else {
            offset++;
            Render_Widget(limit, limit * offset);
            if (offset * limit <= vm.total_lazy) {
                return false;
            }
            if (offset * limit > vm.total_lazy) {
                reachedLast = true;
                vm.loadmore = "";
            }
        }
    };
    //lazyloading dữ liệu trên các widgets dạng bảng
    vm.PagingTableWidget = function (widget) {
        var ma_widget = widget.ma_widget;
        vm.current_page_now = 0;
        vm.check_load_more = false;
        //tăng số thứ tự trang để load thêm
        //điều quan trọng là phải load thêm đúng widget đang load dở
        //kiểm tra điều kiện load thêm, số trang không lớn hơn số trang dữ liệu có trong database
        for (var i = 0; i < vm.arr_mawidget_lazyload.length; i++) {
            if (ma_widget == vm.arr_mawidget_lazyload[i].ma_widget) {
                if (vm.arr_mawidget_lazyload[i].current_page <= vm.arr_mawidget_lazyload[i].total_pages) {
                    vm.check_load_more = true;
                    vm.current_page_now = vm.arr_mawidget_lazyload[i].current_page;
                }
                else vm.check_load_more = false;
                break;
            }
        }
        ///
        if (vm.check_load_more) {
            var offset_val = 0;
            vm.current_page_now++;
            widget.params_value = Execute_ThamSo(vm.current_page_now, widget);

            var paras = {
                command_name: widget.command_fun,
                params_value: widget.params_value,
                is_grid: widget.is_grid,
                lst_params: widget.params_name,
                lst_type: widget.params_type,
                ma_widget: ma_widget,
                offset: offset_val
            };
            var config = {
                id_widget: widget.ma_widget,
                type_chart: widget.type_chart,
                col_shows: widget.col_shows,
                col_value: widget.col_value,
                col_name: widget.col_name
            }
            //gọi hàm update dữ liệu cho biểu đồ
            Update_Data_With_NewPara(paras, config, widget, true);
            //update lại số trang hiện tại cho lần lazy tiếp theo
            for (var i = 0; i < vm.arr_mawidget_lazyload.length; i++) {
                if (ma_widget == vm.arr_mawidget_lazyload[i].ma_widget) {
                    vm.arr_mawidget_lazyload[i].current_page = vm.current_page_now;
                    break;
                }
            }
        }
        else {
            return;
        }
    }
    //tùy chọn xem dữ liệu cá nhân hay theo nhóm quản lý  
    vm.ViewDashboardWithStatusData = function (status) {
        if (vm.status_view != status.status) {
            var old_list_widget = vm.dashboards.arrwidget;
            vm.status_view = status.status;
            for (var i = 0; i < vm.ds_status.length; i++) {
                if (vm.ds_status[i].status === vm.status_view)
                    vm.ds_status[i].css_class = 'dropdown-selected';
                else vm.ds_status[i].css_class = '';
            }
            var ma_widget = '';

            vm.dashboards.arrwidget = [];
            for (var i = 0; i < old_list_widget.length; i++) {
                if (old_list_widget[i].params_default.indexOf('user_id') >= 0) {
                    ma_widget = old_list_widget[i].ma_widget;//.substring(5, old_list_widget[i].ma_widget.length);
                    status_old = old_list_widget[i].params_value.substring(old_list_widget[i].params_value.lastIndexOf(';'));
                    old_list_widget[i].params_value = old_list_widget[i].params_value.replace(status_old, ';' + vm.status_view);
                }
                var paras = {
                    command_name: old_list_widget[i].command_fun,
                    is_grid: old_list_widget[i].is_grid,
                    params_default: old_list_widget[i].params_default, //format tham số được lưu trong bảng
                    params_value: old_list_widget[i].params_value, //giá trị tham số đc lưu trong bảng
                    lst_params: old_list_widget[i].params_name,
                    lst_type: old_list_widget[i].params_type,
                    ma_widget: ma_widget,
                    offset: 0
                };
                var my_dashboard = old_list_widget[i];
                my_dashboard["ma_widget"] = ma_widget;
                ProcessingDataFromSever(paras, my_dashboard, false);
            }
        }
    }
    //thay đổi nhóm dashboard để xem
    vm.Chon_NhomDashboard = function (ma_group) {
        if (ma_group.user_id != SessionService.getItems().user_id) {
            vm.ds_status[1].statusname = 'Dữ liệu của ' + ma_group.ten;
            vm.ds_status[1].statusname2 = 'Data of ' + ma_group.ten;
        }
        else {
            vm.ds_status[1].statusname = 'Dữ liệu của tôi';
            vm.ds_status[1].statusname2 = 'My own data';
        }
        if (ma_group != null) {
            vm.ma_group_db = ma_group;
            limit = 20; offset = 0;
            vm.dashboards.arrwidget = [];//xóa bộ nhớ đệm
            Render_Widget(limit, offset);//vẽ lại vùng biều đồ theo nhóm mới
        }
    }
