            //kiểm tra nếu có sự thay đổi ngày tháng, hoặc duration thì mới update mới task vào csdl
            gantt.attachEvent("onBeforeTaskDrag", function (id, mode, task) {
                if (gantt.getTask(id).lock_date) {
                    return false;      //denies dragging if the global task index is odd
                }
                //
                $scope.task_change_startdate = {
                    start_date: gantt.getTask(id).start_date,
                    duration: gantt.getTask(id).duration
                }
                //

                if (!$('div.js-detail-right').hasClass('hidden')) {
                    $('div.js-detail-right').addClass('hidden');
                    $scope.showing_detail = true;
                }
                //
                return true;
            });
            //fires after the user has finished to drag and released the mouse button
            gantt.attachEvent("onAfterTaskDrag", function (id, mode) {
                console.log(21);
                var task_update = gantt.getTask(id);
                if ($scope.showing_detail == true) {
                    $('div.js-detail-right').removeClass('hidden');
                }
                if (mode == gantt.config.drag_mode.progress) {
                    //update progress
                    var pr = Math.floor(task_update.progress * 100 * 10) / 10;
                    if ($scope.count > 1) {
                        $scope.update_TaskPlan(task_update, 'Completed percent');
                        show_DetailTask(id, "change");
                    }
                } else {
                    //debugger;
                    //update start date, end date
                    if (diff != 0)
                        if ((task_update.start_date != $scope.task_change_startdate.start_date) ||
                          (task_update.duration != $scope.task_change_startdate.duration)) {
                            $scope.update_TaskPlan(task_update, 'Date changed by ');
                            show_DetailTask(id, "change");
                        }
                }
            });
            //prevent moving to another sub-branch:
            gantt.attachEvent("onBeforeRowDragEnd", function (id, target) {
                console.log(21);
                //update index into database, 
                var task = gantt.getTask(id);
                task.index = task.$index + 1;
                //console.log(task)
                //console.log($scope.gantt_tasks.data)
                update_IndexListTask($scope.gantt_tasks.data, id);
                //$scope.update_TaskPlan(task, "Change");
                if (task.parent !== target.parent)
                    return false;
                return true;
            });

            //logically when change date time of activity
            var diff = 0;
            gantt.attachEvent("onBeforeTaskChanged", function (id, mode, originalTask) {
                var modes = gantt.config.drag_mode;
                if (mode === modes.move) {
                    var modifiedTask = gantt.getTask(id);
                    diff = modifiedTask.start_date - originalTask.start_date;
                }
                else if (mode === modes.resize) {
                    var modifiedTask = gantt.getTask(id);
                    diff = diff + 1;
                }
                return true;
            });
            //sự kiện kéo thả task để thay đổi ngày bắt đầu, kết thúc, thay đổi progess
            gantt.attachEvent("onTaskDrag", function (id, mode, task, original) {
                var modes = gantt.config.drag_mode;
                if (mode === modes.move) {
                    var diff = task.start_date - original.start_date;
                    gantt.eachTask(function (child) {
                        child.start_date = new Date(+child.start_date + diff);
                        child.end_date = new Date(+child.end_date + diff);
                        gantt.refreshTask(child.id, true);
                    }, id);
                }
                return true;
            });
            //rounds positions of the child items to scale
            gantt.attachEvent("onAfterTaskDrag", function (id, mode, e) {
                var modes = gantt.config.drag_mode;
                if (mode === modes.move) {
                    var state = gantt.getState();
                    gantt.eachTask(function (child) {
                        child.start_date = gantt.roundDate({
                            date: child.start_date,
                            unit: state.scale_unit,
                            step: state.scale_step
                        });
                        child.end_date = gantt.calculateEndDate(child.start_date,
                            child.duration, gantt.config.duration_unit);
                        gantt.updateTask(child.id);
                    }, id);
                }
            });

