            //nhận dữ liệu từ server khi tải trang
            function fun_Get_GanttPlan(current_project, type) {
                gantt.clearAll();
                //////////
                if (current_project) {
                    RESULT = CRUDServices.getdata({ current_project_id: current_project.id_project },
                      '/ConfigAPI/api/GanttChart/GanttChartAPI/Get_GanttData/', 'GET');
                    RESULT.then(function (res) {

                        if (res.data.data.length > 0) {
                            $scope.gantt_tasks = {
                                "data": (res.data.data),
                                "links": (res.data.link)
                            }

                            //
                            //danh sách chọn người thực hiện
                            $scope.list_users = (res.data.users);

                            //convert to datetime of gantt chart
                            var date = {};
                            for (var i = 0; i < $scope.gantt_tasks.data.length; i++) {

                                date = new Date($scope.gantt_tasks.data[i].start_date);
                                $scope.gantt_tasks.data[i].start_date = (date.getDate()) + '-' + (date.getMonth() + 1) + '-' + date.getFullYear();// + ' 00:00'
                            }

                            gantt.init($scope.gantt_here);
                            gantt.clearAll();
                            gantt.parse($scope.gantt_tasks);

                            gantt.eachTask(function (task) {
                                task.$open = true;
                                $scope.thu_nho_all = false;
                            });
                            gantt.render();

                            if ($stateParams.params.from == 'notice') {
                                if ($stateParams.params.task.id_task != null) {
                                    setTimeout(function () {
                                        $('.js-detail-right').removeClass('hidden');
                                        $scope.details_task = null;
                                        $scope.showing_detail = false;
                                        //refresh comment area
                                        $(".js-edit-textarea").addClass('hidden');
                                        $('.pp-tooltip__wrapper').removeClass('hidden');

                                        $("textarea#js-textarea-add-new-comment").val("");
                                        $("textarea#js-textarea-add-new-comment").css('height', 36);
                                        $("div#js-div-add-new-comment").children("div.pp-newpost__container").removeClass("pp-newpost__container--edit");
                                        $("div.pp-newpost__utilitybelt").addClass("hidden");
                                        show_DetailTask($stateParams.params.task.id_task, "show");
                                    }, 500);
                                }
                            }
                        }
                    });
                }
            }
            //function view detail on the right
            function show_DetailTask(id, type) {
                $(".pp-dropdown__content").css("display", "none");
                $scope.connect_board = null;
                $scope.comment_list = [];//demo comment list
                for (var i = 0; i < $scope.gantt_tasks.data.length; i++) {
                    if ($scope.gantt_tasks.data[i].id == id) {
                        //nếu id == id0: project gốc, ko render từ template
                        if ($scope.gantt_tasks.data[i].id0 == $scope.gantt_tasks.data[i].id) {
                            $scope.details_task = $scope.gantt_tasks.data[i];
                            break;
                        }
                            //id  != id0: project đc render từ template
                        else {
                            for (var j = 0; j < $scope.gantt_tasks.data.length; j++) {
                                if ($scope.gantt_tasks.data[i].id0 === $scope.gantt_tasks.data[j].id0) {
                                    $scope.details_task = $scope.gantt_tasks.data[i];
                                    break;
                                }
                            }
                        }
                    }
                }
                //lưu vào để so sánh sửa description hay không
                $scope.details_task.$original = angular.copy($scope.details_task);

                if ($scope.details_task == null) $scope.details_task = $scope.gantt_tasks.data[0];
                //console.log($scope.details_task);
                if ($scope.details_task != null) {
                    //format date in simple to view on the screen
                    $scope.date_from = CommonFunc.formatDateFromStr($scope.details_task.start_date,
                        'DDMMYYYY', '-')
                    $scope.date_to = CommonFunc.formatDateFromStr($scope.details_task.end_date,
                       'DDMMYYYY', '-');
                    $scope.date_from_view = ($scope.details_task.start_date);
                    $scope.date_to_view = ($scope.details_task.end_date);
                }
                //console.log($scope.details_task)
                //show task lock date or unlock date
                if ($scope.details_task.lock_date == false) {
                    $('div.js-lockdate').text('Lock date');
                }
                else {
                    $('div.js-lockdate').text('Unlock date');
                }
                //view text convert into milestone or acvitity
                if ($scope.details_task.type == 'task') {
                    $('div.js-convert-task').text('Convert into milestone');
                }
                else {
                    $('div.js-convert-task').text('Convert into activity');
                }

                //view color task
                $scope.status_color_task = {
                    label: 'label-4'
                };
                for (var i = 0; i < $scope.list_status.length; i++) {
                    if ($scope.details_task.color_task == $scope.list_status[i].id_label) {
                        $scope.status_color_task = $scope.list_status[i];
                        break;
                    }
                }

                ////order theo thuộc tính để giao diện hiển thị đúng mã màu được sắp xếp
                $scope.list_status = $filter('orderBy')($scope.list_status, 'id_label');

                //get list action from database
                $scope.list_actions = [];
                RESULT = CRUDServices.getdata(
                    {
                        id_project: $scope.details_task.id_project,
                        id_task: $scope.details_task.id,
                        id_card: 0
                    },
                 '/ConfigAPI/api/GanttChart/GanttChartAPI/Get_ListActionsTask/', 'GET');
                RESULT.then(function (res) {
                    $scope.list_actions = JSON.parse(res.data);
                });
                //get list comment on task
                $scope.comment_list = [];
                RESULT = CRUDServices.getdata(
                  {
                      id_project: $scope.details_task.id_project,
                      id_task: $scope.details_task.id
                  },
               '/ConfigAPI/api/GanttChart/GanttChartAPI/Get_ListCommentTask/', 'GET');
                RESULT.then(function (res) {
                    var list_comment = JSON.parse((res.data).list_comment);
                    var list_file = JSON.parse((res.data).list_file);
                    //lặp để lấy file đính kèm theo từng comment
                    for (var i = 0; i < list_comment.length; i++) {
                        list_comment[i].content_conver_html = FormatComment.changeColorDynamic(list_comment[i].content_cmt);
                        var item = {
                            listfile: [],
                            arrayup: [],
                            comment: list_comment[i]
                        }
                        for (var j = 0; j < list_file.length; j++) {
                            if (list_comment[i].id_comment == list_file[j].id_comment) {
                                item.listfile.push(list_file[j]);
                            }
                        }
                        $scope.comment_list.push(item);
                    }
                    //console.log($scope.comment_list)
                });
                //get list comment on task
                $scope.links_dependency = [];
                RESULT = CRUDServices.getdata(
                    {
                        id_project: $scope.details_task.id_project,
                        id_task: $scope.details_task.id
                    },
                 '/ConfigAPI/api/GanttChart/GanttChartAPI/Get_ListDependency/', 'GET');
                RESULT.then(function (res) {
                    var server_data = res.data;
                    if (server_data.length > 0) {
                        $scope.linked_dependencies = get_ArrayFromArray($scope.gantt_tasks.data,
                           server_data, "id", "id_task");
                    }
                    //view list dependencies options
                    //$scope.list_dependencies = [];
                    var tem_array = [];
                    for (var i = 0; i < $scope.gantt_tasks.data.length; i++) {
                        if ($scope.gantt_tasks.data[i].id != $scope.details_task.id) {
                            tem_array.push($scope.gantt_tasks.data[i]);
                        }
                    }
                    var arr_linked = [];
                    for (var i = 0; i < $scope.linked_dependencies.length; i++) {
                        arr_linked.push($scope.linked_dependencies[i].data);
                    }
                    $scope.list_dependencies =
                        get_NotExistArrayFromArray(tem_array, arr_linked, "id", "id");
                    //sắp xếp theo $index
                    $scope.list_dependencies.sort(function (a, b) {
                        return a.source.$index - b.source.$index;
                    });
                });
                //view board container task
                for (var i = 0; i < $scope.list_board_in_project.length; i++) {
                    if ($scope.list_board_in_project[i].id_board === $scope.details_task.id_board) {
                        $scope.connect_board = $scope.list_board_in_project[i];
                        break;
                    }
                }
                //list_activity_intask
                $scope.list_activity_intask = [];
                RESULT = CRUDServices.getdata(
                   {
                       id_project: $scope.details_task.id_project,
                       id_task: $scope.details_task.id
                   },
                '/ConfigAPI/api/GanttChart/GanttChartAPI/Get_ListActivityInTask/', 'GET');
                RESULT.then(function (res) {
                    $scope.list_activity_intask = JSON.parse(res.data);
                });
                ////
                $scope.list_activity_chosen = [];
                RESULT = CRUDServices.getdata(
                   {
                       id_project: $scope.details_task.id_project
                   },
                '/ConfigAPI/api/GanttChart/GanttChartAPI/Get_ListCardChosenTask/', 'GET');
                RESULT.then(function (res) {
                    $scope.list_activity_chosen = JSON.parse(res.data);
                });
                ///
                //get list attachments
                var get_data = {
                    id_project: $scope.current_project.id_project,
                    id_comment: 0,
                    id_board: $scope.details_task.id_board,
                    id_conver: 0,
                    id_card: 0,
                    id_task: $scope.details_task.id
                }
                //list file attached
                RESULT = CRUDServices.getdata(get_data,
                   '/ConfigAPI/api/GanttChart/GanttChartAPI/Get_ListFileAttached/', 'GET');
                RESULT.then(function (res) {
                    $scope.list_attachments = JSON.parse(res.data);
                });
                //
                //list user to mention in comment
                get_members_canbe_mention($scope.details_task.id_project);
                //
                if (type != "addnew")
                    $scope.$apply();
                // });
            }
            //contain properties
            function get_ArrayFromArray(arr_source, arr_target, s_pro, t_pro) {
                var array_out = [];
                for (var i = 0; i < arr_source.length; i++) {
                    for (var j = 0; j < arr_target.length; j++) {
                        if (arr_target[j][t_pro] === arr_source[i][s_pro]) {
                            array_out.push({
                                source: arr_source[i],
                                data: arr_target[j]
                            });
                            break;
                        }
                    }
                }
                return array_out;
            };
            //not exists
            function get_NotExistArrayFromArray(arr_source, arr_target, s_pro, t_pro) {
                var array_out = [];
                var check = false;
                for (var i = 0; i < arr_source.length; i++) {
                    if (Check_Exist_In_Array(t_pro, arr_source[i][s_pro], arr_target) < 0) {
                        array_out.push({
                            source: arr_source[i],
                        });
                    }
                }
                return array_out;
            };
            //
            //kiem tra su ton tai cua phan tu trong mang
            function Check_Exist_In_Array(prop, value, data) {
                var result = -1;
                data.forEach(function (obj, index) {
                    if (prop in obj && obj[prop] === value) {
                        result = index;
                        return false;
                    }
                });
                return result;
            }
            //update $index into database
            function update_IndexListTask(array, id_task) {
                for (var i = 0; i < array.length; i++) {
                    array[i].index = array[i].$index + 1;
                }
                var update = {
                    array: array,
                    data: {
                        id_project: $scope.current_project.id_project,
                        id_task: id_task
                    }
                }
                //console.log(array)
                RESULT = CRUDServices.postdata(update, '/ConfigAPI/api/GanttChart/GanttChartAPI/Put_IndexListTask/', 'PUT');
                RESULT.then(function (res) {
                    //fun_Get_GanttPlan($scope.current_project, "show");
                });
            }

