            //#region SỰ KIỆN TRÊN MENU TOP CỦA GANTT CHART
            //thêm nhanh trên task trên menu top (input text)
            $scope.add_NewTaskPlan = function (text_task) {
                if (text_task !== '' && text_task != null) {
                    ////var d = new Date();
                    //var current_date = CommonFunc.formatDateForGanttPlan(new Date());
                    var type_of_task = gantt.config.types.milestone;
                    if ($('button.calendaritem-kind-selector-button.active').hasClass('js-milestone'))
                        type_of_task = gantt.config.types.milestone;
                    else type_of_task = gantt.config.types.task;
                    var max_index = 1;
                    if ($scope.gantt_tasks.data.length > 0)
                        max_index = get_MaxIdTaskInListByProperty($scope.gantt_tasks.data, "$index");
                    var startdate = CommonFunc.formatDateTo(new Date(), 'MMDDYYYY', '-');
                    //đẩy dữ liệu về server
                    var new_task = {
                        data: {
                            index: max_index.$index + 1,
                            type: type_of_task,
                            text: text_task,
                            start_date: null,
                            color_task: "LB04",//mặc định (màu xanh dương)
                            duration: 1,
                            open: true,
                            parent: 0,
                            user_id0: SessionService.getItems().user_id
                        },
                        project: $scope.current_project,
                        user_name: SessionService.getItems().user_name,
                        user_id: SessionService.getItems().user_id,
                        kanbanboard: false
                    };
                    //console.log(new_task)
                    RESULT = CRUDServices.postdata(new_task,
                      '/ConfigAPI/api/GanttChart/GanttChartAPI/Post_AddNewTaskToPlan/', 'POST');
                    RESULT.then(function (res) {

                        $scope.name_task = 'Untitled Activity';
                        new_task.data.id = res.data.id;
                        new_task.data.id0 = res.data.id0;
                        new_task.data.id_project = res.data.id_project;
                        new_task.data.id_board = res.data.id_board;
                        new_task.data.duration = res.data.duration;
                        $scope.gantt_tasks.data = $scope.gantt_tasks.data.concat(new_task.data);

                        //thêm task mới trên giao diện
                        new_task.data.start_date = new Date(CommonFunc.formatDateTo(res.data.start_date, 'MMDDYYYY', '-'));
                        var taskId = gantt.addTask(new_task.data, 0);

                        //sau khi thêm thì bật cửa sổ để có thể edit task vừa tạo
                        //focus into task with max id, just added in plan
                        show_DetailTask(res.data.id, "addnew");
                        $("div.js-detail-right").removeClass('hidden');

                        $("div.pp-dropdown__content").css('display', 'none');
                        //update index of list task in tree
                        Put_WBSListTask($scope.gantt_tasks.data, new_task.data.id)
                        gantt.refreshData();
                        return false;
                    });
                }
                else $('input[name="name"]').focus();
                //set value default for intput text
                $('input.calendaritem-name-input-toolbar').val('Untitled Activity');
                $('input.calendaritem-name-input-toolbar').blur();
                $('input[name="name"]').focus();
            }

