//# sourceMappingURL=TestDanhMucController.min.js.map
;

//phần test control kanban board

app.controller('TestKanbanBoardController',
   ['$scope', 'CRUDServices', 'SessionService', '$state', '$stateParams', '$dialogs', '$timeout', '$compile', '$filter', '$cookies', 'sysDataShare', 'SystemBase', 'jqgridFactory', 'ListBase',
       function ($scope, CRUDServices, SessionService, $state, $stateParams, $dialogs, $timeout, $compile, $filter, $cookies, sysDataShare, SystemBase, jqgridFactory, ListBase) {

           var $thisState = $state.current.state;
           var vm = this;
           var index = 0;
           var limit = SessionService.getItems().paging_limit;
           vm.gridData = [];
           vm.kanbanData = {
               list_card: [],
               list_column: []
           };

           //#region DIRECTIVE PARAMS
           //truyền các tham số cần thiết về directive để xử lý thiết lập
           vm.passData = {
               gridConfig: {},
               command: {
                   gridid: $thisState,
                   state: $thisState,
                   role_yn: true,
               }
           };


           //nhận giá trị cấu hình từ directive trả về
           (function Init() {
               vm.resultData = function (item) {


                   vm.search = item.search;
                   vm.header = item.header;
                   sysDataShare.shareData('data_shared', {
                       formulaid: item.formulaid,
                       header: item.header,
                       array_yn: true
                   });

                   sysDataShare.sendData('hideshow_shared', {
                       ds_column: angular.copy(item.header_show),
                       gridid: "",
                       array_yn: true
                   });

                   var data = {
                       index: index,
                       search: vm.search,
                       where: {
                           default_sql: vm.search.sql,
                           search_sql: vm.searchResult,
                       }
                   };
                   ListBase.GetData(data, '/TempAPI/api/List/TestDanhMucAPI/GetData/', 'GET')
                      .then(function (res) {
                          var value = res.value;
                          vm.gridData = vm.gridData.concat(value.Items);
                          vm.column_lst = [
                            {
                                name_column: 'Kế hoạch',
                                total_card: 0,
                                index_column: 0,
                                id_column: 0
                            },
                            {
                                name_column: 'Thực hiện',
                                total_card: 0,
                                index_column: 1,
                                id_column: 1
                            },
                            {
                                name_column: 'Hoàn thành',
                                total_card: 0,
                                index_column: 2,
                                id_column: 2
                            }
                          ];
                          vm.kanbanData = {
                              list_card: vm.gridData,
                              list_column: vm.column_lst
                          };
                          vm.returnData = function (item) {
                              vm.my_KanbanBoard = item;
                          }
                      });
               }

           })();

           //sự kiện chọn item trên list trạng thái
           vm.StatusClick = function (item) {
               if (!angular.isUndefined(item)) {
                   vm.search.trang_thai = item.status;
               }
               SearchData();
           }
           vm.SearchData = function (data_search) {
               if (data_search) {
                   vm.search = data_search.advan;
                   vm.search.search_dynamic = data_search.searchDynamic;
                   SearchData();
               }
               else {
                   SystemBase.DisplaySearchError();
               }
           }
           //#endregion


           //config to drag-drop card in kabanboard
           vm.kanbanSortOptions = {
               itemMoved: function (event) {
                   $('.action-card').removeClass('selected');
                   var id = (event.source.itemScope.element[0].id);

                   $("#" + id).addClass('selected');

                   event.source.itemScope.modelValue.status = event.dest.sortableScope.$parent.column.name;
                   var dest_column;
                   var array_column = event.dest.sortableScope.$parent.item.column;
                   for (var i = 0; i < array_column.length; i++) {
                       if (array_column[i].cards.length > 0) {
                           for (var j = 0; j < array_column[i].cards.length; j++) {
                               if (array_column[i].cards[j].activity_id === event.source.itemScope.modelValue.activity_id) {
                                   dest_column = {
                                       id_column: array_column[i].column.id_column,
                                       index_column: array_column[i].column.index_column
                                   }
                                   break;
                               }
                           }
                       }
                       else continue;
                   }
                   var card = event.source.itemScope.card;
                   card.status = dest_column.index_column.toString();
                   card.bcc_arraddress = card.bcc_arraddress == null ? [] : card.bcc_arraddress;
                   card.cc_arraddress = card.cc_arraddress == null ? [] : card.cc_arraddress;
                   card.from_arraddress = card.from_arraddress == null ? [] : card.from_arraddress;
                   card.to_arraddress = card.to_arraddress == null ? [] : card.to_arraddress;
                   //console.log(card);
                   var data_save = {
                       listdm: [card],
                       listdmct: [{
                           subject_type: "DRAGG", //kiểm tra điều kiện là dragg để lưu xuống database
                       }],
                       listfile: [],
                       listatt: [],
                       list_image_inside: [],
                       send_email: false
                   };

                   //update trạng thái khi thay đổi cột
                   //var kq = SystemBase.SaveEdit('/CrmAPI/api/Modify/ActivityAPI/SaveEdit/', data_save, card);
                   var array_full = vm.my_KanbanBoard.list_task.concat(vm.my_KanbanBoard.no_list_task);
                   ///tính tổng point, tổng card theo column (hàng dọc)
                   var total_card = 0;
                   var total_point = 0;
                   angular.forEach(vm.my_KanbanBoard.column_list, function (item) {
                       total_card = 0;
                       total_point = 0;
                       for (var i = 0; i < array_full.length; i++) {
                           if (array_full[i] != null) {
                               for (var j = 0; j < array_full[i].column.length; j++) {
                                   if (array_full[i].column[j].column.id_column === item.id_column) {
                                       total_card = total_card + array_full[i].column[j].cards.length;
                                       for (var ik = 0; ik < array_full[i].column[j].cards.length; ik++) {
                                           total_point = total_point + array_full[i].column[j].cards[ik].value_point;
                                       }
                                   }
                                   else continue;
                               };
                           }
                       }
                       item.total_card = total_card;
                       item.total_point = total_point;
                       total_card = 0;
                       total_point = 0;
                   });
               },
               update: function (event) {
               },
               orderChanged: function (event) {
               },
               longTouch: true,//tranh sau kien drag chuot vs scroll tren cac thiet bi cam ung
               containment: '#board',
               isDisabled: true
           };

           //event click into card to show detail on the right
           vm.ShowDetail_Card = function ($event, column, card) {
               var view = FullCalendar.GetView('calendar');
               vm.search.defaultView = view.name;
               //chuyển màu nền của card đang đc focus
               $('.action-card').removeClass('selected');

               localStorage.setItem("preValue", null);
               localStorage.setItem("preValue", JSON.stringify(vm.search))
               ////////
               vm.search.id = card.activity_id.toString();
               SystemBase.EditCalendarPage(card, 'activity', 'ActivityOverview', '', vm.search, role);
           }
           //mở thông tin của KH để sửa
           vm.ShowCustomer = function ($event, card) {
               var result;
               if (card.ma_ct == "ACC") {
                   //lấy quyền thêm sửa xóa đối với tài khoản
                   RESULT = SystemBase.InitGridMenu("41_a1_02", "41_a1_02");
                   RESULT.then(function (value) {
                       var this_role = value.role;
                       //console.log(this_role)
                       //sau khi lấy quyền thì mới kiểm tra có được sửa hay ko
                       RESULT = SystemBase.GetDataCRM(0, 'all',
                           vm.search.key, 'a.account_id = ' + card.related_id + '',
                           '/CrmAPI/api/Modify/AccountAPI/GetData/');
                       RESULT.then(function (value) {
                           result = JSON.parse(value)[0];
                           var edit = SystemBase.EditOverview(result, "lookup", "/CRM/Modify/AccountModal",
                           "AccountModalController", "md", vm.formatDate, this_role, SessionService.getItems().user_id);
                           if (!angular.isUndefined(edit)) {
                               edit.then(function (res) {
                                   if (res.length > 0) {
                                       growl.success('Khách hàng <b> ' + result.ten + ' </b> đã được cập nhật', {});
                                       SearchData();
                                   }
                               });
                           }
                       });
                   })

               } else if (card.ma_ct == "LEA") {
                   //lấy quyền thêm sửa xóa đối với tài khoản
                   RESULT = SystemBase.InitGridMenu("41_a1_01", "41_a1_01");
                   RESULT.then(function (value) {
                       var this_role = value.role;
                       //console.log(this_role)
                       //sau khi lấy quyền thì mới kiểm tra có được sửa hay ko
                       RESULT = SystemBase.GetDataCRM(0, 'all',
                          vm.search.key, 'a.lead_id = ' + card.related_id + '',
                          '/CrmAPI/api/Modify/LeadAPI/GetData/');
                       RESULT.then(function (value) {
                           result = JSON.parse(value)[0];
                           var edit = SystemBase.EditOverview(result, "lookup", "/CRM/Modify/LeadModal",
                           "LeadModalController", "md", vm.formatDate, this_role, SessionService.getItems().user_id);
                           if (!angular.isUndefined(edit)) {
                               edit.then(function (res) {
                                   if (res.length > 0) {
                                       growl.success('Đầu mối <b> ' + result.ten + ' </b> đã được cập nhật', {});
                                       SearchData();
                                   }
                               });
                           }
                       });
                   })
               }
               else if (card.ma_ct == "CON") {
                   //lấy quyền thêm sửa xóa đối với tài khoản
                   RESULT = SystemBase.InitGridMenu("41_a1_03", "41_a1_03");
                   RESULT.then(function (value) {
                       var this_role = value.role;
                       //console.log(this_role)
                       //sau khi lấy quyền thì mới kiểm tra có được sửa hay ko
                       RESULT = SystemBase.GetDataCRM(0, 'all',
                           vm.search.key, 'a.contact_id = ' + card.related_id + '',
                           '/CrmAPI/api/Modify/ContactAPI/GetData/');
                       RESULT.then(function (value) {
                           result = JSON.parse(value)[0];
                           var edit = SystemBase.EditOverview(result, "lookup", "/CRM/Modify/ContactModal",
                           "ContactModalController", "md", vm.formatDate, this_role, SessionService.getItems().user_id);
                           if (!angular.isUndefined(edit)) {
                               edit.then(function (res) {
                                   if (res.length > 0) {
                                       growl.success('Liên hệ <b> ' + result.ten + ' </b> đã được cập nhật', {});
                                       SearchData();
                                   }
                               });
                           }
                       });
                   })
               }
           }
           //sửa thông tin lịch làm việc trên modal
           vm.EditCard = function ($event, card) {
               //chuyển màu nền của card đang đc focus
               $('.action-card').removeClass('selected');
               card.selected = 'selected';

               var edit = SystemBase.EditOverview(card, "activity", "/CRM/Modify/ActivityModal",
                 "ActivityModalController", "md", '', role, SessionService.getItems().user_id);
               if (!angular.isUndefined(edit)) {
                   edit.then(function (res) {
                       if (res.length > 0) {
                           growl.success('Giao dịch <b> ' + res[0].ten + ' </b> đã được cập nhật', {});
                           SearchData();
                       }
                   });
               }
           }
           //sửa thông tin lịch làm việc trên modal
           vm.DeleteCard = function (card) {
               RESULT = SystemBase.DeleteOverview('/CrmAPI/api/Modify/ActivityAPI/Delete/',
                   card, "listdm", role, SessionService.getItems().user_id);
               if (!angular.isUndefined(RESULT)) {
                   RESULT.then(function (value) {
                       if (value.data > 0) {
                           SearchData();
                       }
                   });
               }
           }
       }]);
;
app.controller('TestVoucherController', ['$scope', 'CRUDServices', 'SessionService', '$state', '$stateParams', '$dialogs',
         '$window', 'SystemBase', 'jqgridFactory', 'growl', 'ListBase', 'VoucherBase', 'sysDataShare',
        function ($scope, CRUDServices, SessionService, $state, $stateParams, $dialogs,
             $window, SystemBase, jqgridFactory, growl, ListBase, VoucherBase, sysDataShare) {
            //#region KHAI BÁO - KHỞI TẠO
            var vm = this;
            $thisState = $state.current.state;

            $sys = angular.copy(SystemBase.SysParams());
            SystemBase.Init();
            vm.search = $sys.search;
            var gridID = "StateTemplateVC";
            vm.gridData = [];
            vm.header = [];
            vm.show_css = false;
            var events_data = {
                gridID: gridID,
                edit: EditPage, //edit dòng
                delete: DeleteRows,//xóa dòng
                hideshow: HideColumn, //ẩn hiện cột
                //phần tùy chỉnh bổ sung (chỉ phần menu row)
                array_menu: [{ id: 'edit', gridid: gridID, class: 'ti-pencil-alt', name: 'edit_btn', func: DeleteRows }]
            }
            vm.right_click = jqgridFactory.RightClickMenu(events_data);
            vm.myGridOptions = {
                //các thuộc tính mặc định của jqgrid
                scroll: false,
                datatype: 'local',
                rownumbers: true,
                rownumWidth: 50,
                multiselect: true,
                multiboxonly: true, // chỉ chọn nhiều dòng khi click ô checkbox
                //height: 420,
                colMenu: true,
                shrinkToFit: false, //tự động co dãn kích thước các cột
                //các thuộc tính bổ sung cho directive
                outerID: 'all_items',
                id: gridID,
                autoBinding: true,
                config_server: true,
                radio_btn: false,
                frozen: true,
                lazy_yn: true,
                pageSize: $sys.limit,
                remove_loadding: false,
                contextMenu: true,//rightclick trên grid
                contextMenuRowID: 'contextMenuRow',
                contextMenuRow: vm.right_click.menu_row,
                contextMenuHeaderID: 'contextMenuHeader',
                contextMenuHeader: vm.right_click.menu_header,
                configServer: true, //lấy cấu hình từ server
                actionNav: false,
                actionWidth: 50,
                actionsNavOptions: {},

                loadComplete: function () { },
                report: false,
                pivot: false,
                treeGrid: false,
                ondblClickRow: EditPage,
                filterToolbar: true,
                groupHeader: true
            };

            //#endregion

            //#region DIRECTIVE PARAMS
            //truyền các tham số cần thiết về directive để cấu hình 
            vm.passData = {
                gridConfig: vm.myGridOptions, //cấu hình của gridview  
                command: {
                    gridid: $thisState, //tên gridid cấu hình trong DB
                    state: $thisState,  //trạng thái hiện tại
                    role_yn: true,      //có check quyền hay không
                }
            };

            //nhận giá trị cấu hình từ directive trả về
            (function Init() {
                vm.resultData = function (item) {
                    vm.search = item.search;                        //các thuộc tính để tìm kiếm mà Directive trả về
                    vm.header = item.header;                        //tiêu để của jqgrid

                    sysDataShare.shareData('data_shared', {
                        formulaid: item.formulaid,                  //công thức tạo mã của danh mục (nếu có)
                        header: item.header,                        //tiêu đề của jqgrid 
                        array_yn: true                              //tham số check điều kiện bên Directive
                    });
                    sysDataShare.sendData('hideshow_shared', {
                        ds_column: angular.copy(item.header_show),  //danh sách các cột đang hiển thị trên jqgrid
                        gridid: gridID,                             //id của jqgrid    
                        array_yn: true                              //tham số check điều kiện, xử lý bên jqgrid
                    });
                }
            })();
            vm.Paging = Paging;
            vm.GetData = GetData;
            vm.StatusClick = StatusClick;
            vm.SearchData = SearchData;
            vm.OnClickMenu = OnClickMenu;
            vm.OnKeyDown = OnKeyDown;
            //#region CALL FROM DIRECTIVE

            function GetData(index) {
                GetData(index);
            };
            function StatusClick(item) {
                if (item.error_logic === "") {
                    if (!angular.isUndefined(item)) {
                        vm.search.status = item.status;
                    }
                    SearchData();
                }
                else {
                    SystemBase.DisplaySearchError();
                }
            }

            function SearchData(data_search) {
                if (data_search) {
                    if (data_search.search_col_yn)
                        $sys.searchResult = data_search.advan;
                    vm.search.search_dynamic = data_search.searchDynamic;
                    SearchData();
                }
                else {
                    SystemBase.DisplaySearchError();
                }
            }
            //#endregion

            //#region DATA

            function GetData(index) {
                var data = {
                    index: index,
                    search: vm.search,
                    where: {
                        default_sql: vm.search.sql,
                        search_sql: vm.searchResult,
                        search_dynamic: vm.search.search_dynamic
                    }
                }
                VoucherBase.GetData(data, '/TempAPI/api/List/TestVoucherAPI/GetData/', 'GET').then(function (res) {
                    $sys.reachedLast = res.reachedLast;
                    vm.gridData = vm.gridData.concat(res.value.Items);
                    vm.passData.totalItems = res.value.TotalItems;
                });
            };

            function SearchData() {
                $sys.index = 0;
                $sys.reachedLast = false;
                vm.gridData = [];
                jqgridFactory.ClearGridData(gridID);
                GetData($sys.index);
            }

            function Paging() {
                if ($sys.reachedLast) {
                    return false;
                }
                else {
                    $sys.index++;
                    GetData($sys.index);
                }
            }
            //#endregion

            //#REGION GRID - MENU
            function Add() {
                var params = {
                    state: $thisState,
                    state_next: 'VCOverview',
                    paramsearch: vm.search,
                    from: 'listdm',
                }
                ListBase.AddPage(params);
            }

            function EditPage() {
                var params = {
                    gridID: gridID,
                    state: $thisState,
                    state_next: 'VCOverview',
                    paramsearch: vm.search,
                    from: 'listdm',
                }
                ListBase.EditRowPage(params);
            }

            function EditModal(id, data) {
                var params = {
                    gridID: gridID,
                    view: '/TEMPLATE/Template/TestVoucherAddModal',
                    controller: 'VoucherModalController',
                    size: 'fs',
                    from: 'listdm',
                    state: $thisState,
                    check_owner: true,
                    check_arise: true,
                    field_display: 'so_ct',
                    field_key: 'stt_rec',
                }
                var edit = ListBase.EditRowModal(params);
                edit.then(function (edited) {
                    if (edited.length > 0) {
                        growl.success('Đơn hàng ' + edited[0].ten + ' đã được cập nhật', {});
                        SearchData();
                    }
                });
            }

            function DeleteRows() {
                var params = {
                    gridID: gridID,
                    api: '/TempAPI/api/List/TestVoucherAPI/Delete/',
                    entities: 'listdm',
                    check_owner: true,
                    field_display: 'so_ct',
                    field_key: 'stt_rec',
                    check_arise: true,
                    state: $thisState,
                }
                ListBase.Delete(params).then(function (res) {
                    if (res)
                        SearchData();
                });
            }

            function Import() {
                var idlg = $dialogs.create("/Scripts/SYSTEM/Htmls/ImportData.html", "ImportController", {
                    params: {
                        id: 'crmaccount',
                        apiimport: '/CrmAPI/api/Category/AccountAPI/ImportData/',
                        entity: 'listdm'
                    }
                }, { key: true, back: 'static', size: 'md' })
                idlg.result.then(function (kq) {
                    if (kq > 0) {
                        SearchData();
                    }
                });
            }

            function HideColumn(column) {
                sysDataShare.sendData('from_ctrl', { hiddenColumn: column });
            }

            function Export(type) {
                var params = {
                    state: $thisState,
                    gridID: vm.passData.command.gridid,
                    txtHeader: vm.passData.txtHeader,
                    type: type,
                    isReport: false, //true => danh mục, false => báo cáo
                    filename: 'Danh sách khách hàng',
                    configColumn: $sys.configColumn,
                    functionName: 'danhmuc_test',
                    api: '/TempAPI/api/List/TestDanhMucAPI/ExportToExcel/',
                    search: {
                        index: index,
                        limit: $sys.limit,
                        status: vm.search.status,
                        key: vm.search.key,
                        where_adv: vm.search.sql != "" ? vm.search.sql + " and " + vm.searchResult : vm.searchResult,
                        dm_yn: true,
                        searchDynamic: vm.search.searchDynamic
                    }
                }
                console.log(params);
                ListBase.Export(params);
            }

            function Approve(type) {
                var params = {
                    gridID: gridID,
                    state: $thisState,
                    type: type
                }
                VoucherBase.Approve(params).then(function (value) {
                    if (value > 0) {
                        SearchData();
                    }
                });
            }

            //#endregion

            //#region REFERENCES

            function OnClickMenu(menu) {
                switch (menu.menuid) {
                    case 'addcampaign': {
                        AddToCampaign();
                        break;
                    }
                    case 'reload': {
                        SearchData();
                        break;
                    }
                    case 'add': {
                        Add();
                        break;
                    }
                    case 'edit': {
                        EditPage();
                        break;
                    }
                    case 'delete': {
                        DeleteRows();
                        break;
                    }
                    case "expExcel": {
                        Export("excel", menu.hideShowColumn);
                        break;
                    }
                    case "expPDF": {
                        Export("pdf");
                        break;
                    }
                    case "expCSV": {
                        Export("csv");
                        break;
                    }
                    case "import": {
                        Import();
                        break;
                    }
                    case "duplicate": {
                        Duplicate();
                        break;
                    }
                    case "approve_vc":
                    case "close_vc": {
                        Approve(menu.menuid);
                        break;
                    }
                }
                $('#btnNav').trigger('click');
            }

            function OnKeyDown(value) {
                switch (value.keyCode) {
                    case 46: //delete
                        {
                            //DeleteRows();
                            break;
                        }
                    case 113: //f2
                        {
                            //Add();
                            break;
                        }
                    case 118://f7
                        {
                            //EditPage();
                            break;
                        }
                    default:
                        break;
                }
            }
            //#endregion
        }]);

app.controller('VoucherOverviewController',
    ['$scope', 'CRUDServices', 'SessionService', '$state', '$window', '$stateParams', '$dialogs', '$cookies', 'stateStorage', '$timeout', 'growl',
        'SystemBase', 'ngFabForm', 'CommonFunc', 'jqgridFactory', 'LookUpServiceNew', 'WizardHandler', 'processShare', 'VoucherBase', 'sysDataShare',
        function ($scope, CRUDServices, SessionService, $state, $window, $stateParams, $dialogs, $cookies, stateStorage, $timeout, growl,
            SystemBase, ngFabForm, CommonFunc, jqgridFactory, LookUpServiceNew, WizardHandler, processShare, VoucherBase, sysDataShare) {

            //#region KHAI BÁO
            SystemBase.Init();
            stateStorage.checkData($state.current.url);
            var stateParent = 'TES';


            var vm = this;
            $thisState = $state.current.state;
            $sys = angular.copy(SystemBase.SysParams());
            vm.show_yn = true;
            vm.ph = null;
            vm.from = $stateParams.params.from;
            vm.add_yn = $stateParams.params.add_yn;
            vm.submitted = false;
            vm.ds_thanhtoan = [{ ma_tt: '', ten_tt: 'Chọn loại thanh toán' }];
            vm.ds_htthanhtoan = [{ ma_httt: '', ten_httt: 'Chọn hình thức thanh toán' }];
            vm.ds_loaixe = [{ ma_loai: '', ten_loai: 'Chọn loại xe' }];
            vm.ds_tinh = []; vm.ds_huyen = [];
            vm.ma_nt = "VND";
            vm.lastID = null;
            vm.ct = [];
            var ct = [];
            var ds_vert_data = [];
            var get_step_yn = false;        //biến ktra đã lấy thông tin chưa để lấy thông tin - chỉ lấy 1 lần đầu
            var gridID = "grid_ct";
            var outerID = "parentID";
            var ds_column_hidden = [];
            //lưu quyền vào để check
            sysDataShare.shareData($thisState, $stateParams.params.role);
            //#endregion

            //#region PIVOT JQGRID 

            vm.gridData = [];

            //lưu lại giá trị của dòng đang sửa trước khi bắt đầu đc sửa (lấy giá trị khi click vào dòng)
            vm.old_data = {};

            vm.gridConfig = {
                //các thuộc tính mặc định của jqgrid
                scroll: false,
                rownumbers: true,
                rownumWidth: 50,
                multiselect: false,
                multiboxonly: true, // chỉ chọn nhiều dòng khi click ô checkbox
                //height: 420,
                shrinkToFit: false, //tự động co dãn kích thước các cột
                forceFit: true,
                inlineNav: false,
                gridview: true,
                loadonce: false,
                //các thuộc tính bổ sung cho directive
                outerID: outerID,
                id: gridID,
                //lazy_yn: true,
                //autoBinding: true,
                config_server: true,
                frozen: false,
                remove_loadding: false,
                report: false,
                group: false,
                configServer: true, //lấy cấu hình từ server
                actionNav: false,
                contextMenu: false,//rightclick trên grid
                contextMenuRowID: '',
                contextMenuRow: [],
                contextMenuHeaderID: 'contextMenuHeader',
                contextMenuHeader: [],
                onSelectRow: OnSelectRow,
                actionsNavOptions: {},
                loadComplete: function () { },
            };

            //#endregion

            //#region DIRECTIVE PARAMS
            //truyền các tham số cần thiết về directive để xử lý thiết lập

            vm.passData = {
                propertyShow: 'so_ct',     //tên thuộc tính để  hiển thị tên
                editOnPage: true,          //cho phép sửa trên page hay không 
                add_yn: vm.add_yn,         //trạng thái: thêm - sửa 
                params: $stateParams.params,
                validClick: { form: 'rowForm', gridID: gridID, scope: $scope },
                command: {
                    gridid: $thisState,
                    state: $thisState,
                    role_yn: false,
                    ma_ct: 'TES'
                },
                list_userinfo: [],
                history: [],
                importData: []
            };
            //nhận giá trị cấu hình từ directive trả về
            (function first() {
                vm.resultData = function (item) {
                    VoucherBase.InitVoucher({
                        voucher: item,
                        scope: vm
                    });
                    if (vm.header) {
                        LoadData(1, null, null);
                    }
                }
            })();

            //#region LOOKUP - CONFIG
            /*
             *   multiple_yn: true,
          where: '',
          size_md: 'md',
          arr_tbls: [{
              gridid: 'LK_dmkh',
          }],
          callback: function (data) {
              //function gọi lại sau khi đóng cửa sổ lookup
              console.log(data)
          }
             * 
             */
            vm.lookupKH = {
                multi_yn: false,
                arr_tbls: [{
                    gridid: 'LK_dmkh',
                }],
                size_md: 'md',
                where_search: [],
                callback: function (data) {
                    //function gọi lại sau khi đóng cửa sổ lookup
                }

            };

            vm.lookupNVBH = {
                multi_yn: false,
                arr_tbls: [{
                    gridid: 'LK_dmnv',
                }],
                size_md: 'md',
                where_search: [],
                callback: function (data) {
                    //function gọi lại sau khi đóng cửa sổ lookup
                }
            };

            //#endregion

            //#endregion

            vm.Tinh_Change = Tinh_Change;
            vm.HideGroupInfo = HideGroupInfo;
            vm.CheckShowGridview = CheckShowGridview;
            vm.ChangeTyGiaNT = ChangeTyGiaNT;
            vm.OnClickMenu = OnClickMenu;
            vm.GetStepInfo = GetStepInfo;

            //#region FUNCTION DATA
            function LoadData(times, stt_rec, so_ct) {
                $sys.deleteList = [];
                if (times === 2) {
                    $stateParams.params.add_yn = false;
                    $stateParams.params.ct = {
                        stt_rec: stt_rec,
                        so_ct: so_ct
                    };
                    vm.EditMode = false;
                    get_step_yn = false;
                    //lưu lại params
                    stateStorage.checkData($state.current.url);
                }
                console.log($stateParams.params.ct);
                if (!vm.add_yn) {
                    vm.EditMode = false;
                    GetById($stateParams.params.ct.stt_rec, times);
                }
                else {
                    vm.EditMode = true;
                    var kq = CRUDServices.getdata('', '/TempAPI/api/List/TestVoucherAPI/GetNew/', 'GET');
                    kq.then(function (res) {
                        var value = res.data.Result;
                        vm.ph = JSON.parse(value.ph);
                        vm.ph.$original = angular.copy(vm.ph);
                        jqgridFactory.ClearGridData(gridID);

                        AddRow(false);
                        jqgridFactory.SetGridWidth(gridID, outerID);

                        ds_vert_data = value.ds_vert_data;
                        vm.passData.importData = ds_vert_data;
                    });
                }
            }

            //get chi tiết của chứng từ theo stt_rec
            function GetById(id_obj, times) {
                console.log(id_obj);
                var kq = CRUDServices.getdata({ id: id_obj }, '/TempAPI/api/List/TestVoucherAPI/GetById/', 'GET');
                kq.then(function (res) {
                    vm.ph = null;
                    var value = res.data.Result;
                    vm.ph = (value.ctdm) != null ? angular.copy(value.ctdm) : null;
                    //vm.ph["giaodich"] = [];
                    vm.passData.history = (value.history) != null ? (value.history) : null;
                    vm.passData.list_userinfo = (value.userinfo) != null ? (value.userinfo) : null;
                    vm.ct = value.ctdmct.length > 0 ? value.ctdmct : [];
                    ct = angular.copy(vm.ct);
                    $sys.max_ln = vm.ct.length > 0 ? vm.ct[0].max_ln + 1 : $sys.max_ln;
                    vm.ph.ngay_ct = CommonFunc.FormatDateToV(vm.ph.ngay_ct, $sys.separatorDate);
                    vm.ph.ngay_lct = CommonFunc.FormatDateToV(vm.ph.ngay_lct, $sys.separatorDate);
                    vm.ph.ngay_gh = CommonFunc.FormatDateToV(vm.ph.ngay_gh, $sys.separatorDate);
                    vm.ph.ngay_tt = CommonFunc.FormatDateToV(vm.ph.ngay_tt, $sys.separatorDate);
                    if (vm.ph.ma_nvbh != "" && vm.ph.ten_nvbh != "") {
                        vm.ph.nvbh = [{
                            ma_nvbh: vm.ph.ma_nvbh,
                            ten_nvbh: vm.ph.ten_nvbh
                        }];
                    }
                    if (vm.ph.ma_kh != "" && vm.ph.ten_kh != "") {
                        vm.ph.khachhang = [{
                            ma_kh: vm.ph.ma_kh,
                            ten_kh: vm.ph.ten_kh,
                            dia_chi: vm.ph.dia_chi,
                            dien_thoai: vm.ph.dien_thoai,
                            dien_thoai2: vm.ph.dien_thoai2
                        }];
                    }

                    if (times == 1) {
                        //LoadCombobox(vm.ph);
                    }

                    $sys.lastSelected = 0;

                    jqgridFactory.ClearGridData(gridID);
                    jqgridFactory.AddRowData(gridID, vm.ct);

                    vm.ph.$original = angular.copy(vm.ph);

                    //co dãn gridview để xuất hiện thanh scroll
                    setTimeout(function () {
                        jqgridFactory.SetGridWidth(gridID, outerID);
                        //jqgridFactory.SetGridWidth(gridID, 'grid_dsvt');
                    }, 500);
                    if (vm.ph.ma_nt != $sys.ma_nt_df) {
                        //show cột ngoại tệ trong db
                        jqgridFactory.ShowCol(gridID, ds_column_hidden);
                    } else {
                        //ẩn cột ngoại tệ
                        jqgridFactory.HideCol(gridID, ds_column_hidden);
                    }

                    ds_vert_data = value.data.ds_vert_data;
                    vm.passData.importData = ds_vert_data;
                });
            }

            //load các danh sách lựa chọn trong mỗi combobox từ server
            function LoadCombobox(ctdm) {
                var dvcs = CRUDServices.getdata({
                    ma_tinh: ctdm.ma_tinh != null ? ctdm.ma_tinh : ''
                }, '/TempAPI/api/List/TestVoucherAPI/LoadComboBox/', 'GET');
                dvcs.then(function (value) {

                    vm.ds_giaodich = JSON.parse(value.data.ds_giaodich);
                    vm.ds_status = JSON.parse(value.data.ds_status);
                    vm.ds_tygia = JSON.parse(value.data.ds_tygia);

                    vm.ds_thanhtoan = vm.ds_thanhtoan.concat(JSON.parse(value.data.ds_thanhtoan));
                    vm.ds_htthanhtoan = vm.ds_htthanhtoan.concat(JSON.parse(value.data.ds_htthanhtoan));
                    vm.ds_loaixe = vm.ds_loaixe.concat(JSON.parse(value.data.ds_loaixe));
                    vm.ds_tinh = JSON.parse(value.data.ds_tinh);

                    if (value.data.ds_huyen != "") {
                        vm.ds_huyen = JSON.parse(value.data.ds_huyen);
                    } else {
                        vm.ds_huyen = [];
                    }
                });
            }

            //#endregion

            //#region EVENTS GRID
            function AddRow(add_yn) {

                $('#' + gridID).jqGrid('addRow', {
                    add_yn: add_yn, //kiểm tra addrow này khi click EditRow hay khi đang thêm liên tiếp để xác định có focus vào ô tiếp theo hay ko
                    key: true,
                    rowID: "id".concat($sys.id_grid),
                    initdata: {},
                    position: $sys.position,
                    useDefValues: false,
                    useFormatter: false,
                    addRowParams: {
                        keys: true,
                        errorSave: function (rowID, options, b) {
                            VoucherBase.ShowError(options);
                        },
                        lookUpItem: function (rowID, options, b) {
                            if (vm.check_modal == null) {
                                //xử lý sự kiện khi ô nhập liệu có gọi đến lookup
                                var passData = options.lookup;
                                passData.condition.selected = vm.ct;

                                var RESULT = LookUpServiceNew.LookUp(passData);
                                if (RESULT != null) {
                                    vm.check_modal = RESULT;
                                    RESULT.then(function (vt) {
                                        vm.check_modal = null;
                                        var params = {
                                            arr_sel: vt,
                                            arr_ct: vm.ct,
                                            rowID: rowID,
                                            keyID: 'ma_vt',
                                            lookUp: passData,
                                            add_yn: true,
                                            gridID: gridID,
                                            header: vm.header,
                                            oldData: {},
                                            max_ln: $sys.max_ln,
                                            callback: UpdateObject, //truyền hàm để callback trong nội tại của factory
                                        };
                                        var res = VoucherBase.UpdateGrid(params);
                                        //focus vào ô nhập liệu tiếp theo trên dòng hiện tại - nếu là chọn một dòng
                                        if (res.result.length == 1) {
                                            VoucherBase.FocusNextCell(rowID, passData.keyId);
                                        } else if (res.result.length > 1) {
                                            //add toàn bộ các items đc chọn resfresh gridview nếu là chọn nhiều 
                                            vm.ct = vm.ct.concat(res.result);
                                            TinhTongTien(vm.ph, vm.ct);
                                            jqgridFactory.ClearGridData(gridID);
                                            jqgridFactory.AddRowData(gridID, vm.ct);
                                            AddRow();
                                        }
                                    }, function () {

                                        //bật modal lookup nhưng sau đó nhấn cancel -> vớt lại data cũ
                                        document.getElementById(rowID + "_" + passData.keyId).value = vm.old_data[passData.keyId] ? vm.old_data[passData.keyId] : '';
                                        setTimeout(function () {
                                            $('#' + rowID + "_" + passData.keyId).focus();
                                        }, 200);
                                        vm.check_modal = null;
                                    });
                                }
                            }
                        },
                        //sự kiện xử lý sau khi lưu
                        aftersavefunc: function (rowid, response) {
                            var rowData = jqgridFactory.GetCurrentRow(gridID, rowid);
                            console.log(rowData);
                            rowData = UpdateObject(rowData, rowData, "A");
                            //chỉ khi là lựa chọn từ lookup thì mới add vào danh sách
                            if (rowData.check_save) {
                                vm.ct.push(rowData);
                            }
                            TinhTongTien(vm.ph, vm.ct);
                            $sys.lastSelected = 0;
                            jqgridFactory.ClearGridData(gridID);
                            jqgridFactory.AddRowData(gridID, vm.ct);
                            AddRow(true);
                            setTimeout(function () {
                                $scope.$apply();
                            }, 500);
                        },
                    }
                });
                $sys.id_grid++;
            }

            //Đón sự kiện lưu dòng sau khi sửa
            //id: id của dòng đang sửa và sẽ được lưu
            function EventEditRow(id) {
                //bắt đầu trạng thái  sửa, enable các ô nhập dữ liệu
                $('#' + gridID).jqGrid('editRow', id, {
                    keys: true,
                    focusField: event.target.cellIndex,
                    errorSave: function (rowID, options, b) {
                        VoucherBase.ShowError(options);
                    },
                    lookUpItem: function (rowID, options, b) {
                        if (vm.check_modal == null) {
                            //gọi lookup nếu ô nhập liệu có lookup
                            var passData = options.lookup;
                            var RESULT = LookUpServiceNew.LookUp(passData);
                            if (RESULT != null) {
                                RESULT.then(function (vt) {
                                    vm.check_modal = null;
                                    var params = {
                                        arr_sel: vt,
                                        arr_ct: vm.ct,
                                        rowID: rowID,
                                        keyID: 'ma_vt',
                                        lookUp: passData,
                                        add_yn: true,
                                        gridID: gridID,
                                        header: vm.header,
                                        oldData: {},
                                        max_ln: $sys.max_ln,
                                        callback: UpdateObject, //truyền hàm để callback trong nội tại của factory
                                    };
                                    var res = VoucherBase.UpdateGrid(params);
                                    //focus vào ô nhập liệu tiếp theo trên dòng hiện tại - nếu là chọn một dòng
                                    if (res.result.length == 1) {
                                        VoucherBase.FocusNextCell(rowID, passData.keyId);
                                    } else if (res.result.length > 1) {
                                        //add toàn bộ các items đc chọn resfresh gridview nếu là chọn nhiều 
                                        vm.ct = vm.ct.concat(res.result);
                                        TinhTongTien(vm.ph, vm.ct);
                                        jqgridFactory.ClearGridData(gridID);
                                        jqgridFactory.AddRowData(gridID, vm.ct);
                                        AddRow();
                                    }

                                }, function () {
                                    //bật modal lookup nhưng sau đó nhấn cancel -> vớt lại data cũ
                                    document.getElementById(rowID + "_" + passData.keyId).value = vm.old_data[passData.keyId] ? vm.old_data[passData.keyId] : '';
                                    setTimeout(function () {
                                        $('#' + rowID + "_" + passData.keyId).focus();
                                    }, 200);
                                    vm.check_modal = null;
                                });
                            }
                        }
                    },
                    aftersavefunc: function (rowID, response) {
                        var data = {
                            keyID: 'ma_vt', //xác định item đã tồn tại trong danh sách hay chưa
                            gridID: gridID,
                            array: 'gridData',
                            rowID: rowID,
                            vm: vm,
                            deleteList: $sys.deleteList,
                            callback: UpdateObject,
                        }
                        var res = VoucherBase.AfterSaveFunc(data);
                        TinhTongTien(vm.ph, vm.ct);
                        //vm[vm.ctDeleted] = res.deleteList;
                        $sys.lastSelected = 0;
                        //update dòng vừa sửa lên grid
                        RefreshGrid({
                            data: res.rowEdit,
                            add_yn: false,
                            search_yn: options.search_yn
                        });
                    }
                })
            }
            function RefreshGrid(params) {
                params["vm"] = vm;
                params["pKey"] = 'ma_vt';
                params["ct"] = 'gridData';
                //xử lý gộp dòng, hay tách dòng nếu nhập trùng mã  (dựa vào biến: vm.merger_row_yn)
                VoucherBase.GridviewExtension(params);

                $sys.id_grid++;

                //đang hiển thị kết quả tìm kiếm thì ko reset lại gridview
                if (!params.search_yn) {
                    jqgridFactory.ClearGridData(gridID);
                    jqgridFactory.AddRowData(gridID, vm['gridData']);
                    if (vm.EditMode) {
                        AddRow(params.add_yn);
                    }
                }
            }
            function OnSelectRow(id, state, event) {
                if (vm.EditMode) {
                    if (!angular.isUndefined(event) && $(event.target).hasClass('cbox')) {
                    }
                    else if (!angular.isUndefined(event) && $(event.target).hasClass('ui-icon-trash')) {
                    }
                    else {
                        // Dựa vào event để check: chỉ khi click vào dòng để edit thì mới lấy giá trị của old_data 
                        // để so sánh trước khi lưu lại dòng vừa sửa
                        if (event) {
                            vm.old_data = jqgridFactory.GetRowData(gridID, id);
                        }
                        //click vào từng vật tư để sửa trên gridview
                        if (id && id !== $sys.lastSelected) {
                            var grid = $("#" + gridID);
                            grid.restoreRow($sys.lastSelected);
                            grid.editRow(id, true);
                            $sys.lastSelected = id;
                        }
                        if (id && !isNaN(id) && JSON.stringify(vm.old_data) != '{}') {
                            jqgridFactory.ClearGridData(gridID);
                            jqgridFactory.AddRowData(gridID, vm.ct);
                            AddRow(false);
                            //bôi đen ô dữ liệu nếu click chuột vào
                            setTimeout(function () {
                                if ($(event.target).children()[0])
                                    $('#' + $(event.target).children()[0].id)[0].select();
                            }, 300);
                            //trường hợp sửa dòng, lưu lại giá trị và update vào grid
                            EventEditRow(id);
                            $sys.lastSelected = id;
                        }
                    }
                }
            }

            function DeleteRow(options) {
                if (vm.EditMode) {
                    //chỉ xóa các dòng có id là kiểu số
                    if (!isNaN(options.rowid)) {
                        var rowData = jqgridFactory.GetLocalRow(gridID, options.rowid);
                        //xóa dữ liệu trong dsnv
                        for (var i = vm.ct.length - 1; i > -1; i--) {
                            if (vm.ct[i].ma_vt === rowData.ma_vt && vm.ct[i].ln === rowData.ln) {
                                //nếu trạng thái = sửa và dòng này là dòng dữ liệu cũ 
                                if (!vm.add_yn && !vm.ct[i].action_type) {
                                    vm.ct[i].action_type = "D";
                                    $sys.deleteList.push(vm.ct[i]);
                                }
                                vm.ct.splice(i, 1);
                                break;
                            }
                        }
                        TinhTongTien(vm.ph, vm.ct);
                        $scope.$apply();
                        //xóa dòng trên grid cha
                        jqgridFactory.DelRowData(gridID, options.rowid);
                    }
                }
            }
            //#endregion

            //#region FUNCTION DATA

            function Edit() {
                vm.EditMode = true;
                vm.ph.$original = angular.copy(vm.ph);
                ct = angular.copy(vm.ct);
                AddRow(false);
                jqgridFactory.SetGridWidth(gridID, outerID);
            }

            function Save(closed) {
                console.log(vm.ct);

                var res = ngFabForm.submit({ form: 'rowForm', gridID: gridID, scope: $scope });
                if (res.result) {
                    vm.saving = true;
                    var data_save = {
                        listdm: vm.ph,
                        listdmct: vm.ct.concat($sys.deleteList),
                        options: {
                            add_yn: vm.add_yn,
                            closed_yn: closed
                        }
                    };

                    VoucherBase.Save(data_save, '/TempAPI/api/List/TestVoucherAPI/', vm.ph).then(function (res) {
                        if (vm.add_yn && !closed) {
                            //lưu và thêm tiếp
                            vm.submitted = false;
                            vm.saving = false;
                            ngFabForm.resetSubmit(vm.rowForm);
                            angular.element('#ctkh input').first().focus();
                            vm.add_more = true;
                            LoadData(2);
                        }
                        else if ((vm.add_yn && closed) || !vm.add_yn) {
                            //lưu(thêm/sửa) và đóng
                            if (res.Success) {
                                $state.go(stateParent, {
                                    params: {
                                        paramsearch: $stateParams.params.search
                                    }
                                });
                            } else {
                                angular.element('#ctkh input').first().focus();
                                vm.saving = false;
                            }
                        }
                    });
                }
                else {
                    switch (res.error.type) {
                        case 'FORM-INVALID':
                        case 'GRID-NO-DATA': {
                            vm.submitted = true;
                            break;
                        }
                        case 'GRID-INVALID-DATA': {
                            var err = growl.error(res.error.title + ": nhập liệu chưa đúng");
                            EventEditRow(res.error.id);
                            //focus vào ô dòng cần sửa thông tin
                            var $cellGrid = $("#" + res.error.id + "_" + res.error.name);
                            setTimeout(function () {
                                $cellGrid.focus();
                                $cellGrid.select();
                                $cellGrid.addClass('none');
                            }, 100);
                            break;
                        }
                    }
                }
            }

            function Copy() {
                var res = ngFabForm.submit({ form: 'rowForm', gridID: gridID, scope: $scope });
                if (res.result) {
                    listdm = [];
                    vm.EditMode = true;
                    //sinh mã tự động như khi tạo mới
                    var kq = CRUDServices.getdata('', '/TempAPI/api/List/TestVoucherAPI/GetNew/', 'GET');
                    kq.then(function (res) {
                        var value = res.data.Result;
                        vm.ph_copy = JSON.parse(value.ctdm);
                        vm.ph_copy.ngay_ct = CommonFunc.FormatDateToV(vm.ph_copy.ngay_ct, $sys.separatorDate);
                        vm.ph_copy.ngay_lct = CommonFunc.FormatDateToV(vm.ph_copy.ngay_lct, $sys.separatorDate);
                        vm.ph_copy.ngay_gh = CommonFunc.FormatDateToV(new Date(), $sys.separatorDate);
                        vm.ph_copy.ngay_tt = CommonFunc.FormatDateToV(new Date(), $sys.separatorDate);

                        if (vm.ph_copy.ma_nvbh != "" && vm.ph_copy.ten_nvbh != "") {
                            vm.ph_copy.nvbh = [{
                                ma_nvbh: vm.ph.ma_nvbh,
                                ten_nvbh: vm.ph.ten_nvbh
                            }];
                        }
                        ///
                        vm.saving = true;
                        $scopevmph_copy.ma_kh = vm.ph.khachhang[0].ma_kh;
                        vm.ph_copy.ma_kh2 = vm.ph.khachhang[0].ma_kh;
                        vm.ph_copy.ten_kh = vm.ph.khachhang[0].ten_kh;
                        vm.ph_copy.ten_kh2 = vm.ph.khachhang[0].ten_kh;
                        vm.ph_copy.dia_chi = vm.ph.khachhang[0].dia_chi;
                        vm.ph_copy.dia_chi2 = vm.ph.khachhang[0].dia_chi;
                        vm.ph_copy.dia_chi3 = vm.ph.khachhang[0].dia_chi;
                        vm.ph_copy.dien_thoai = JSON.toPhone(vm.ph.khachhang[0].dien_thoai);
                        vm.ph_copy.dien_thoai2 = JSON.toPhone(vm.ph.khachhang[0].dien_thoai2);

                        //vm.ph_copy.ma_nvbh = vm.ph.nvbh[0].ma_nvbh;
                        vm.ph_copy.ngay_ct = CommonFunc.FormatDateToE(vm.ph.ngay_ct, $sys.separatorDate);
                        vm.ph_copy.ngay_lct = CommonFunc.FormatDateToE(vm.ph.ngay_lct, $sys.separatorDate);
                        vm.ph_copy.ngay_tt = CommonFunc.FormatDateToE(vm.ph.ngay_tt, $sys.separatorDate);
                        vm.ph_copy.ngay_gh = CommonFunc.FormatDateToE(vm.ph.ngay_gh, $sys.separatorDate);
                        vm.ph_copy.ong_ba2 = vm.ph.ong_ba;
                        vm.ph_copy.ong_ba3 = vm.ph.ong_ba;

                        listdm.push(vm.ph_copy);
                        var arr_ct_copy = [];
                        var ct_copy = {};
                        for (var i = 0; i < vm.ct.length; i++) {
                            ct_copy = angular.copy(vm.ct[i]);
                            ct_copy.stt_rec = vm.ph_copy.stt_rec;
                            ct_copy.so_ct = vm.ph_copy.so_ct;
                            ct_copy.ma_ct = vm.ph_copy.ma_ct;
                            ct_copy.ngay_ct = CommonFunc.FormatDateToE(vm.ph.ngay_ct, $sys.separatorDate);
                            arr_ct_copy.push(ct_copy);
                        }
                        TinhTongTien(vm.ph_copy, arr_ct_copy);
                        //#region COPY
                        data_save = {
                            listdm: [vm.ph_copy],
                            listdmct: arr_ct_copy
                        }
                        var kq = ListBase.SaveEdit('/TempAPI/api/List/TestVoucherAPI/SaveAdd/', data_save, vm.ph);
                        kq.then(function (value) {
                            if (value.status != -1) {
                                growl.success("Sao chép chứng từ thành công", {});
                                $stateParams.params.ct = vm.ph_copy;
                                vm.passData.params = $stateParams.params;
                                //update vào localstore để nếu có F5 thì sẽ load chứng từ mới vừa đc tạo từ lệnh copy
                                stateStorage.checkData($state.current.url);
                                vm.EditMode = false;
                                GetById(vm.ph_copy.stt_rec, 1);
                            }
                            else {
                                vm.saving = false;
                                vm.ph.ngay_ct = CommonFunc.FormatDateToV(vm.ph.ngay_ct, $sys.separatorDate);
                                vm.ph.ngay_lct = CommonFunc.FormatDateToV(vm.ph.ngay_lct, $sys.separatorDate);
                                vm.ph.ngay_tt = CommonFunc.FormatDateToV(vm.ph.ngay_tt, $sys.separatorDate);
                                vm.ph.ngay_gh = CommonFunc.FormatDateToV(vm.ph.ngay_gh, $sys.separatorDate);
                                LoadData(1, null, null);
                            }
                        });

                    });
                }
                else {
                    switch (res.error.type) {
                        case 'FORM-INVALID':
                        case 'GRID-NO-DATA': {
                            vm.submitted = true;
                            break;
                        }
                        case 'GRID-INVALID-DATA': {
                            var err = growl.error(res.error.title + ": nhập liệu chưa đúng");
                            EventEditRow(res.error.id);
                            //focus vào ô dòng cần sửa thông tin
                            var $cellGrid = $("#" + res.error.id + "_" + res.error.name);

                            setTimeout(function () {
                                $cellGrid.focus();
                                $cellGrid.select();
                                $cellGrid.addClass('none');
                            }, 100);
                            break;
                        }
                    }
                }
            }

            function Close() {
                if (vm.EditMode) {
                    var original = vm.ph.$original;
                    var compare = angular.equals(vm.ph, original);
                    if (!compare) {
                        var dialog = $dialogs.confirm("Chú ý", "Chưa lưu thông tin! Bạn có muốn lưu trước khi đóng?");
                        dialog.result.then(function () {
                            vm.Save(true);
                        }, function () {
                            $state.go(stateParent, {
                                params: {
                                    paramsearch: $stateParams.params.search
                                }
                            });
                        })
                    } else {
                        $state.go(stateParent, {
                            params: {
                                paramsearch: $stateParams.params.search
                            }
                        });
                    }
                }
                else {
                    $state.go(stateParent, {
                        params: {
                            paramsearch: $stateParams.params.search
                        }
                    });
                }
            }

            function ChangeGD() {
                RESULT = CRUDServices.getdata({ ma_ct: vm.ph.ma_ct, ma_gd: vm.ph.ma_gd },
                    '/TempAPI/api/List/TestVoucherAPI/GetQTByMaCT/', 'GET');
                RESULT.then(function (value) {
                    vm.passData.importData = value.data;
                })
            }

            function ChangeTyGia(tygia) {
                //chọn ngoại tệ
                if (tygia.ma_nt != $sys.ma_nt_df) {
                    jqgridFactory.ShowCol(gridID, ds_column_hidden);
                } else {
                    //ẩn cột ngoại tệ
                    jqgridFactory.HideCol(gridID, ds_column_hidden);
                }
                jqgridFactory.SetGridWidth(gridID, outerID);

                //update tỷ giá tương ứng
                angular.forEach(vm.ct, function (item) {
                    item.gia2 = item.gia_nt2 * vm.ph.ty_gia;
                    item.tien2 = item.gia2 * item.so_luong;
                });
                $sys.lastSelected = 0;
                jqgridFactory.ClearGridData(gridID);
                jqgridFactory.AddRowData(gridID, vm.ct);

                $timeout(function () {
                    if (vm.EditMode) {
                        AddRow();
                        TinhTongTien(vm.ph, vm.ct);
                        $scope.$apply();
                    }
                }, 200);
            }

            function ChangeTyGiaNT(tygia) {
                vm.ph.ty_gia = parseFloat(tygia.replace(/,/g, ''));
            }

            function Tinh_Change(data) {
                if (data != null) {
                    if (data.tinh.ma_tinh) ma_tinh = data.tinh.ma_tinh;
                    vm.ph.huyen = null;
                    if (ma_tinh != '') {
                        vm.ph.ma_tinh = ma_tinh;
                        var param = {
                            ma_tinh: ma_tinh,
                            ma_huyen: '',
                            _type: 2
                        };

                        vm.ds_huyen = [];
                        RESULT = CRUDServices.getdata(param, '/ConfigAPI/api/LookUp/LookUpConfigAPI/GetTinhHuyenXa/', 'GET');
                        RESULT.then(function (value) {
                            vm.ds_huyen = JSON.parse(value.data);
                            if (vm.ds_huyen.length > 0) {
                                for (var i = 0; i < vm.ds_huyen.length; i++) {
                                    if (vm.ds_huyen[i].ma_huyen == vm.ph.ma_huyen) {
                                        vm.ph.huyen = vm.ds_huyen[i];
                                        break;
                                    }
                                }
                            }
                        });
                    } else {
                        vm.ds_huyen = [];
                    }
                }
            };
            //#endregion


            //#region ẨN HIỆN KHI CLICK VÀO TAB

            function CheckShowGridview(tab) {
                if (tab == 'main1') {
                    vm.show_yn = true;
                    $('.voucher-detail').css({ 'height': 'calc(100vh - 240px)' });
                }
                else {
                    vm.show_yn = false;

                    $('.voucher-detail').css({ 'height': 'calc(100vh - 90px)' });
                }
            }

            function HideGroupInfo() {
                if ($('#group_info').css('display') == 'block') {
                    $('#group_info').hide();
                    vm.show_css = true;
                }
                else {
                    $('#group_info').show();
                    vm.show_css = false;
                }
            }
            //#endregion

            //#region EXTENSION

            function OnClickMenu(menu) {

                switch (menu.menuid) {
                    case 'reload': {
                        //$window.location.reload();
                        LoadData(1);
                        break;
                    }
                    case 'edit': {
                        Edit();
                        break;
                    }
                    case 'save': {
                        Save();
                        break;
                    }
                    case 'close': {
                        Close();
                        break;
                    }
                    case 'copy': {
                        Copy();
                        break;
                    }
                    case 'importct': {
                        VertData(menu);
                        break;
                    }
                    case 'approve_vc':
                    case 'cancel_vc':
                    case 'close_vc':
                    case 'deny_vc': {
                        Approve(menu.menuid);
                        break;
                    }
                    default: break;
                }
            }

            function VertData(menu) {
                //console.log(menu);
                if (vm.EditMode) {
                    var res = VoucherBase.VertData({
                        state: stateParent,
                        ph: vm.ph,
                        import_info: menu
                    });
                    res.then(function (kq) {
                        if (kq.length > 0) {
                            var oldData = angular.copy(vm.ct);
                            angular.forEach(oldData, function (item) {
                                item.action_type = "D";
                            });
                            $sys.deleteList = $sys.deleteList.concat(oldData); //xóa vật tư cũ

                            angular.forEach(kq, function (item) {
                                item[menu.colname_sl_to] = item.so_luong;
                                item[menu.colname_stt_rec_from] = angular.copy(item.stt_rec);
                                item[menu.colname_so_ct_from] = angular.copy(item.so_ct);
                                item[menu.colname_ln_from] = angular.copy(item.ln);

                                item.ma_ct = vm.ph.ma_ct;

                                item.so_ct = vm.ph.so_ct;
                                item.ngay_ct = CommonFunc.FormatDateToE(angular.copy(vm.ph.ngay_ct), $sys.separatorDate);
                                item.ln = $sys.max_ln;
                                $sys.max_ln += 1;

                                item['action_type'] = 'A';    //xác định vật tư này là thêm mới
                            });

                            vm.ct = kq;
                            TinhTongTien(vm.ph, vm.ct);
                            $sys.lastSelected = 0;
                            jqgridFactory.ClearGridData(gridID);
                            jqgridFactory.AddRowData(gridID, vm.ct);
                            AddRow();
                        }
                    })
                }
            }

            function Approve(type) {
                if (!vm.add_yn && !vm.EditMode) {
                    var params = {
                        state_parent: stateParent,
                        state: $thisState,
                        ph: vm.ph,
                        ct: vm.ct,
                        type: type,
                        gridID_close: 'StateTemplateVC_close'
                    }
                    var approve = VoucherBase.ApproveDetail(params);
                    approve.then(function (value) {
                        if (value.list_data.length > 0)
                            vm.ct = value.list_data;
                        jqgridFactory.ClearGridData(gridID);
                        jqgridFactory.AddRowData(gridID, vm.ct);
                        //LoadData(2, vm.ph.stt_rec, vm.ph.so_ct);
                    }, function (data) {

                    });
                }
            }

            function TinhTongTien(obj, ds) {
                obj.t_so_luong = 0; obj.t_tien = 0; obj.t_tien_nt = 0;
                angular.forEach(ds, function (item) {
                    obj.t_so_luong += parseInt(item.so_luong);
                    obj.t_tien += JSON.toNumber(item.tien2) > 0 ? parseFloat(item.tien2) : 0;
                    obj.t_tien_nt += JSON.toNumber(item.tien_nt2) > 0 ? parseFloat(item.tien_nt2) : 0;
                    obj.t_tt = obj.t_tien;
                    obj.t_tt_nt = obj.t_tien_nt;
                });
            }

            //update toàn bộ những thuộc tính tương ứng của update cho object
            //sử dụng trong tính toán hoặc sau khi lookup
            //type : "A" or "E"
            function UpdateObject(object, update, type) {

                for (var pro in object) {
                    object[pro] = update[pro] ? update[pro] : object[pro];
                }

                //các trường mặc định phụ thuộc lấy từ ph
                object.stt_rec = vm.ph.stt_rec;
                object.so_ct = vm.ph.so_ct;
                object.ma_ct = vm.ph.ma_ct;
                object.ngay_ct = CommonFunc.FormatDateToE(vm.ph.ngay_ct, $sys.separatorDate);

                //chỉ khi nào object chưa có thuộc tính ln thì mới update
                if (!object.ln) {
                    object.ln = $sys.max_ln;
                    $sys.max_ln += 1;
                }

                //xử lý ngoại lệ
                object.gio_dong = object.gio_dong == "" || object.gio_dong == null ? "00:00:00" : object.gio_dong;
                object.status = update.status ? update.status : '1';
                //công thức tính toán giá trị các cột
                object.so_luong = object.so_luong != null ? parseFloat(object.so_luong) : 0;
                object.gia_nt2 = object.gia_nt2 != null ? parseFloat(object.gia2) : 0;
                object.gia2 = object.gia2 != null ? parseFloat(object.gia2) * vm.ph.ty_gia : 0;
                object.tien2 = object.tien2 != null ? object.so_luong * object.gia2 : 0;
                object.tien_nt2 = object.tien_nt2 != null ? object.so_luong * object.gia_nt2 : 0;
                object.action_type = JSON.returnAction(object.action_type);
                object.check_save = true;
                //console.log(object);
                return object;
            }

            //#endregion

            //#region QUY TRÌNH

            function GetStepInfo() {
                // 
                if (!get_step_yn && !vm.add_yn) {
                    var data_share = {
                        process_id: 'SO',
                        ph: vm.ph,
                        ct: vm.ct,
                        stt_rec_pre: 'stt_rec_sq1',
                        state: $thisState,
                        form_trans: $thisState
                    };
                    //share param sang controller hiển thị quy trình
                    processShare.sendData(data_share);
                    get_step_yn = true;
                }
            }
            //#endregion
        }
    ]);



;
app.controller('ConfigLangController', ['$scope', '$location', 'SessionService', 'ngFabForm', 'CRUDServices', '$cookies', '$translate',
      '$window', '$state', '$dialogs', 'growl', 'ListBase',
      function ($scope, $location, SessionService, ngFabForm, CRUDServices, $cookies, $translate, $window, $state, $dialogs, growl, ListBase) {
          $scope.res_value = "";
          //#region KHAI BÁO - ĐỊNH NGHĨA 
          $scope.list_datatable = [
              {
                  form_name: "sys_languages"
              },
              {
                  form_name: "sys_languages_data",
              }
          ];
          $scope.remove_yn = 0;
          $scope.list_type = [];
          $scope.list_typeform = [
             {
                 form_value: "N",
                 form_name: "FormState thông thường",
                 arr_type: [{
                     form_value: "CH",
                     form_name: "Column header"
                 }]
             },
             {
                 form_value: "LK",
                 form_name: "Lookup modal",
                 arr_type: [{
                     form_value: "CH",
                     form_name: "Column header"
                 },
                 {
                     form_value: "TH",
                     form_name: "Title header"
                 }]
             },
              {
                  form_value: "L",
                  form_name: "Danh mục (List)",
                  arr_type: [{
                      form_value: "CH",
                      form_name: "Column header"
                  },
                    {
                        form_value: "LB",
                        form_name: "Label"
                    }]
              },
                {
                    form_value: "V",
                    form_name: "Chứng từ (Voucher)",
                    arr_type: [
                         {
                             form_value: "CH",
                             form_name: "Column header"
                         },
                        {
                            form_value: "VD",
                            form_name: "Vert data"
                        },
                         {
                             form_value: "LB",
                             form_name: "Label"
                         }]
                },
             {
                 form_value: "R",
                 form_name: "Báo cáo (Report)",
                 arr_type: [{
                     form_value: "CH",
                     form_name: "Column header"
                 },
                        {
                            form_value: "LB",
                            form_name: "Label"
                        }]
             },
              {
                  form_value: "W",
                  form_name: "Widget (Dashboard/Overview) Label config & Gridview ",
                  arr_type: [{
                      form_value: "CH",
                      form_name: "Column header"
                  },
                        {
                            form_value: "LB",
                            form_name: "Label"
                        }]
              }
          ];

          $scope.trans_form = $scope.list_typeform[0];
          $scope.trans_type = $scope.list_type[0];
          $scope.show_form_type = 'N';

          $scope.name_id = 'Value name';
          $scope.form_id = 'Form';
          $scope.value_insert = '';
          $scope.list_form_by_table = [];
          //danh sách các ngôn ngữ 
          $scope.ds_languages = JSON.parse(localStorage.listlang);

          $scope.ds_languages_add = JSON.parse(localStorage.listlang);


          $scope.name_add = '';
          $scope.form_add = '';

          //#endregion

          //#region SỰ KIỆN NGƯỜI DÙNG

          $scope.tableUpChange = function (table_name) {
              if (table_name) {
                  var kq = CRUDServices.getdata({
                      table_name: table_name.form_name
                  }, '/ConfigAPI/api/Translate/TranslationsConfigAPI/GetListForm/', 'GET');
                  kq.then(function (value) {
                      $scope.list_form_by_table = value.data;
                  })
              }
          }

          $scope.FormUpChange = function (this_form) {
              if (this_form) {
                  var kq = CRUDServices.getdata({
                      table_name: $scope.table_up.form_name,
                      form: this_form.form
                  }, '/ConfigAPI/api/Translate/TranslationsConfigAPI/GetListNameByForm/', 'GET');
                  kq.then(function (value) {
                      $scope.list_name_by_table = value.data;
                      $scope.name_value = '';
                  })
              } else {
                  $scope.name = '';
                  $scope.list_name_by_table = [];
                  $scope.name_value = '';
                  for (var i = 0; i < $scope.ds_languages.length; i++) {
                      $scope.ds_languages[i].value = '';
                  }
              }
          }
          $scope.transFormChange = function (item) {
              //nếu là normal thì ẩn trên giao diện
              $scope.show_form_type = item.form_value;
              switch ($scope.show_form_type) {
                  case "V": {
                      $scope.form_id = "Mã chứng từ";
                      $scope.name_id = "GridID (sys_gridconfig)"
                      break;
                  }
                  case "R": {
                      $scope.form_id = "State";
                      break;
                  }
                  case "LK":
                  case "L": {
                      $scope.form_id = "State";
                      $scope.name_id = "GridID (sys_gridconfig)"
                      break;
                  }
                  case "W": {
                      $scope.form_id = "Widget ID";
                      $scope.name_id = "GridID (sys_gridconfig)"
                      break;
                  }
                  case "N": {
                      $scope.form_id = "Form translate";
                      $scope.name_id = "Value name"
                      break;
                  }
              }
              $scope.list_type = item.arr_type;
              $scope.trans_type = $scope.list_type[0];
              setTimeout(function () {
                  $('input#form').focus();
              }, 200);
          }

          $scope.ColumnUpChange = function (this_column) {
              if (this_column) {
                  var kq = CRUDServices.getdata({
                      table_name: $scope.table_up.form_name,
                      form: $scope.form.form,
                      name: this_column.name
                  }, '/ConfigAPI/api/Translate/TranslationsConfigAPI/GetListValueByForm/', 'GET');
                  kq.then(function (res) {
                      var value = res.data;
                      if (value.length > 0)
                          $scope.name_value = value[0].name;
                      else $scope.name_value = null;
                      for (var i = 0; i < value.length; i++) {
                          for (var j = 0; j < $scope.ds_languages.length; j++) {
                              if (value[i].culture === $scope.ds_languages[j].ma) {
                                  $scope.ds_languages[j].value = value[i].value;
                              }
                          }
                      }
                  });
              }
              else {
                  $scope.name_value = '';
                  for (var j = 0; j < $scope.ds_languages.length; j++) {
                      $scope.ds_languages[j].value = '';
                  }
              }
          }

          //#region THÊM MỚI
          $scope.tableAddChange = function (this_form) {
              if (!this_form) {
                  $scope.name = null;
                  document.getElementById("rowForm2").reset();
              }
          }

          //#endregion

          //#region THÊM - SỬA -  XÓA
          //lưu giá trị vào DB
          $scope.SaveUpdateConfig = function (lang) {
              if ($scope.table_up != null) {
                  var pass_data = [];
                  for (var i = 0; i < $scope.ds_languages.length; i++) {
                      pass_data.push({
                          form: $scope.form.form ? $scope.form.form : "",
                          name: $scope.name ? $scope.name.name : "",
                          culture: $scope.ds_languages[i].ma,
                          value: $scope.ds_languages[i].value,
                      });
                  };

                  var data = {
                      table_name: $scope.table_up.form_name,
                      searchDynamic: pass_data
                  }

                  var update = CRUDServices.postdata(data, '/ConfigAPI/api/Translate/TranslationsConfigAPI/UpdateTranslate/', 'POST');
                  update.then(function (value) {
                      if (value.data > 0) {
                          $scope.name = null;
                          document.getElementById("rowForm").reset();
                          $scope.name_value = '';
                          $scope.name_value_new = '';
                          growl.success('Cập nhật thành công');
                      }
                      else {
                          growl.error("Đã có lỗi xảy ra, hãy kiểm tra lại!");
                      }
                  });
              }
              else growl.error("Chưa chọn bảng đích lưu giá trị");
          }

          //dùng chung ngôn ngữ: xử lý để thêm nhanh khi test
          function UpdateValue(data, name_add) {
              for (var i = 0; i < $scope.ds_languages_add.length; i++) {
                  if ($scope.ds_languages_add[i].ma == 'en-US')
                      $scope.ds_languages_add[i].value = 'E.' + data;
                  else if ($scope.ds_languages_add[i].ma == 'jp-JP')
                      $scope.ds_languages_add[i].value = 'J.' + data;
                  else if ($scope.ds_languages_add[i].ma == 'vi-VN')
                      $scope.ds_languages_add[i].value = data;
              }
          }
          $scope.disabled_yn = false;
          $scope.SaveAddConfig = function (res_value, click_add_yn) {
              if ($scope.disabled_yn && !click_add_yn) return false;
              if ($scope.table_add != null) {
                  //nếu là nhập đơn lẻ từng bản ghi (form normal)
                  if ($scope.trans_form.form_value == 'N') {
                      if (!$scope.disabled_yn) UpdateValue(res_value, $scope.name_add);
                      var res = ngFabForm.submit({ form: 'rowForm2', gridID: '', scope: $scope });
                      if (res.result) {
                          var pass_data = [];
                          for (var i = 0; i < $scope.ds_languages_add.length; i++) {
                              pass_data.push({
                                  form: ($scope.form_add).trim(),
                                  name: ($scope.name_add).trim(),
                                  culture: $scope.ds_languages_add[i].ma,
                                  value: $scope.ds_languages_add[i].value,
                              });
                          }
                          var data = {
                              table_name: $scope.table_add.form_name,
                              searchDynamic: pass_data
                          }
                        
                          var update = CRUDServices.postdata(data, '/ConfigAPI/api/Translate/TranslationsConfigAPI/AddTranslateNormal/', 'POST');
                          update.then(function (value) {
                              if (value.data > 0) {
                                  for (var j = 0; j < $scope.ds_languages_add.length; j++) {
                                      $scope.ds_languages_add[j].value = '';
                                  }
                                  $scope.name_add = null;
                                  $scope.res_value = '';
                                  growl.success('Đã thêm mới thành công!');
                                  setTimeout(function () {
                                      $('input#form1').focus();
                                  }, 100);
                                  ngFabForm.resetSubmit({ form: 'rowForm2', scope: $scope });
                              }
                              else {
                                  growl.error("Đã tồn tại bản ghi này !! Không thể thêm mới!");
                              }
                          });
                      }
                  }
                  else {
                      var data = {
                          table_name: $scope.table_add.form_name,
                          gridconfig: $scope.name_add,
                          form_name: $scope.form_add,
                          type_form: $scope.show_form_type,
                          type_param: $scope.trans_type.form_value,
                          remove_yn: $scope.remove_yn
                      };

                      var update = CRUDServices.postdata(data, '/ConfigAPI/api/Translate/TranslationsConfigAPI/AddTranslateAvdance/', 'POST');
                      update.then(function (value) {
                          if (value.data == 0)
                              growl.error("Không thành công!! Kiểm tra lại các tham số");
                          else if (value.data < 0) {
                              growl.error("Bản ghi đã tồn tại!! Kiểm tra lại các tham số");
                          }
                          else growl.success("Đã thêm thành công");
                      })
                  }
              }
              else growl.error("Chưa chọn bảng đích lưu giá trị");
          }

          $scope.Delete = function (table, form, name) {
              var dialog = $dialogs.confirm("Xác nhận", "Có chắc chắn muốn xóa không?");
              dialog.result.then(function () {

                  var data = {
                      table_name: $scope.table_up.form_name,
                      form_name: $scope.form.form ? $scope.form.form : "",
                      gridconfig: $scope.name ? $scope.name.name : "",
                  }

                  var update = CRUDServices.postdata(data, '/ConfigAPI/api/Translate/TranslationsConfigAPI/Delete/', 'POST');
                  update.then(function (value) {
                      document.getElementById("rowForm").reset();
                      $scope.table_up = null;

                      $scope.list_form_by_table = [];
                      $scope.list_name_by_table = [];
                      for (var j = 0; j < $scope.ds_languages.length; j++) {
                          $scope.ds_languages[j].value = '';
                      }
                      growl.success('Đã xóa thành công');
                      $scope.name_value = '';
                      $scope.name_value_new = '';
                      setTimeout(function () {
                          $scope.$apply();
                      }, 100);
                  })
              })
          }
          //#endregion

          //#region TƯƠNG TÁC VS API
          //lấy danh sách from theo table
          function GetFormOfTable(table_name) {
              var kq = ListBase.GetData({
                  table_name: table_name
              }, '/ConfigAPI/api/Translate/TranslationsConfigAPI/GetListForm/', 'GET');
              kq.then(function (value) {
                  return value;
              })
          }
          //#endregion

      }]);
;
//DANH MỤC CHÍNH
app.controller('ListConfigController',
    ['$scope', 'CRUDServices', 'SessionService', '$state', '$stateParams', '$dialogs', '$compile', '$filter', '$cookies',
        'sysDataShare', '$timeout', 'SystemBase', '$injector', 'jqgridFactory', 'growl', 'ListBase',
        '$translatePartialLoader', '$translate', 'Page',
        function ($scope, CRUDServices, SessionService, $state, $stateParams, $dialogs, $compile, $filter, $cookies,
            sysDataShare, $timeout, SystemBase, $injector, jqgridFactory, growl, ListBase,
            $translatePartialLoader, $translate, Page) {
            //#region khai báo
            $translatePartialLoader.addPart('ListConfig');
            $translate.refresh();
            Page.setTitleAuto($state.current);
            $scope.lang = "vi";
            var index = 0;
            var limit = 50;
            var reachedLast = false;
            var totalPages;
            $scope.searchResult = " 1 = 1 ";
            var error_logic = "";

            var role = [];
            $scope.ds_status = [{
                ma_ct: 'ACC',
                status: 'all',
                statusname: 'Tất cả',
                statusname2: 'All'
            }, {
                status: 'owner',
                statusname: 'Khách hàng của tôi',
                statusname2: 'My accounts'
            }];

            $scope.ds_loaikh = [{ form_value: '', form_name: 'Tất cả' }];
            $scope.ds_nganhnghe = [{ form_value: '', form_name: 'Tất cả' }];
            $scope.ds_tinh = [{ ma_tinh: '', form_name: 'Tất cả' }];
            $scope.search = {
                key: '',
                sql: '',
                trang_thai: $scope.ds_status[1].status,
                loaikh: $scope.ds_loaikh[0],
                nganhnghe: $scope.ds_nganhnghe[0],
                tinh: $scope.ds_tinh[0],
                searchDynamic: {}
            };
            $scope.dynamic = {};
            var _where = " 1=1";
            var configColumn = "";
            //console.log($scope.search);
            var gridID = "crmaccount";
            $scope.gridData = [];
            $scope.header = []; var header = [];
            $scope.menu = [];
            $scope.totalItems = 0;

            $scope.contextMenuRow = [{ id: 'edit', class: 'ti-pencil-alt', name: 'edit_btn', func: EditPage },
                { id: 'del', class: 'ti-trash', name: 'delete_btn', func: DeleteRows }];
            $scope.contextMenuHeader = [
                { id: 'frozen', name: 'Frozen' },
                { id: 'destroyFrozen', name: 'Destroy Frozen' }];

            //jqgrid mới
            $scope.myGridOptions = {
                //các thuộc tính mặc định của jqgrid
                scroll: false,
                datatype: 'local',
                rownumbers: true,
                rownumWidth: 50,
                multiselect: true,
                multiboxonly: true, // chỉ chọn nhiều dòng khi click ô checkbox
                //height: 420,
                shrinkToFit: true, //tự động co dãn kích thước các cột
                //các thuộc tính bổ sung cho directive
                outerID: 'all_items',
                id: gridID,
                autoBinding: true,
                config_server: true,
                radio_btn: false,
                frozen: true,
                lazy_yn: true,
                pageSize: 50,
                remove_loadding: false,
                contextMenu: true,//rightclick trên grid
                contextMenuRowID: 'contextMenuRow',
                contextMenuRow: $scope.contextMenuRow,
                contextMenuHeaderID: 'contextMenuHeader',
                contextMenuHeader: $scope.contextMenuHeader,
                configServer: true, //lấy cấu hình từ server
                actionNav: false,
                actionWidth: 50,
                actionsNavOptions: {
                    deleteUsericon: "ui-icon-trash",
                    align: 'center',
                    deleteUsertitle: "Xóa",
                    custom: [
                        {
                            action: "deleteUser",
                            //onClick: DeleteRow
                        }
                    ]
                },
                loadComplete: function () {
                    //jqgridFactory.SetLabelRn(gridID);
                },
                report: false,
                pivot: false,
                treeGrid: false,
                ondblClickRow: EditPage,
                filterToolbar: true,
                groupHeader: false
            };

            //#endregion

            //#region DIRECTIVE PARAMS
            //truyền các tham số cần thiết về directive để xử lý thiết lập
            $scope.passData = {
                gridConfig: $scope.myGridOptions,
                txtHeader: 'ListConfig_title_list', //tiêu đề của danh mục
                totalItems: 0,
                editOnPage: true,
                params: $stateParams.params, //load lại dữ liệu vừa tìm kiếm nếu vừa từ detail của bản ghi trở ra
                status: {
                    ma_ct: '',   //mã chứng từ cấu hình trong bảng sysdmtt
                    owner_yn: false, //check danh mục này có trạng thái: Của tôi hay ko,
                    selected: 'all', //trạng thái mặc định hiển thị khi load lần đầu (dựa vào bảng sysdmtt để điền value)
                },
                command: {
                    gridid: 'ListConfig', //khai báo menuid: header và menu theo phân quyền
                    state: 'ListConfig',
                    role_yn: true,
                }
            };

            //nhận giá trị cấu hình từ directive trả về
            (function first() {
                $scope.resultData = function (item) {
                    $scope.search.trang_thai = item.status.status;
                    role = item.role;
                    $scope.header = item.header;
                    sysDataShare.shareData('data_shared', { header: item.header, array_yn: true });
                    //tránh tham chiếu cùng một biến
                    var header_show = angular.copy(item.header_show);
                    sysDataShare.sendData('hideshow_shared', { ds_column: header_show, gridid: gridID, array_yn: true });
                }
                if ($stateParams.params != "") {
                    $scope.search = $stateParams.params.paramsearch;
                };
            })();



            //gọi từ directive
            $scope.GetData = function (index) {
                GetData(index);

            };
            //sự kiện chọn item trên list trạng thái
            $scope.StatusClick = function (item) {
                if (item.error_logic == "") {
                    if (!angular.isUndefined(item)) {
                        $scope.search.trang_thai = item.status;
                    }
                    TimKiem();
                }
                else {
                    SystemBase.DisplaySearchError();
                }
            }


            //#endregion

            //#region dữ liệu
            function GetData(index) {
                //debugger;
                var where = $scope.search.sql != "" ? $scope.search.sql + " and " + $scope.searchResult : $scope.searchResult;
                $scope.search.searchDynamic["index"] = index;
                $scope.search.searchDynamic["limit"] = 50;
                $scope.search.searchDynamic["offset"] = 50 * index;
                $scope.search.searchDynamic["gridid"] = "ListConfig"; //keycode lookup
                $scope.search.searchDynamic["keyword"] = $scope.search.key;
                $scope.search.searchDynamic["status"] = $scope.search.trang_thai;
                $scope.search.searchDynamic["where"] = where;
                $scope.search.searchDynamic["user_id"] = SessionService.getItems().user_id;
                var data = {
                    searchDynamic: $scope.search.searchDynamic
                };
                //console.log(data);
                //phương thức đang test
                var kq = ListBase.GetData(data, '/ConfigAPI/api/Gridview/ListConfigAPI/GetData/', 'GET');
                kq.then(function (value) {
                    //console.log(value);
                    SystemBase.DisplaySearch($scope.search.trang_thai);
                    $scope.gridData = $scope.gridData.concat(value.Items);
                    $scope.totalPages = value.TotalPages;
                    $scope.totalItems = value.TotalItems;

                    $scope.passData.totalItems = $scope.totalItems;

                    if (limit + limit * index < $scope.totalItems) {
                        reachedLast = false;
                    }
                        //đã đạt đến trang cuối cùng
                    else {
                        reachedLast = true;
                    }

                    SystemBase.RemoveLoading();
                });
            };
            /////
            function TimKiem() {
                index = 0;
                reachedLast = false;
                $scope.gridData = [];
                jqgridFactory.ClearGridData(gridID);
                GetData(index);
            }

            $scope.TimKiem = function (data_search) {
                if (data_search) {
                    $scope.search.key = JSON.toString(data_search.advan.key);
                    $scope.search.sql = JSON.toString(data_search.advan.sql);
                    $scope.search.searchDynamic = data_search.searchDynamic;
                    TimKiem();
                }
                else {
                    SystemBase.DisplaySearchError();
                }
            }
            //////////
            $scope.SearchChange = function (key) {
                if (key == null || key == "") {
                    TimKiem();
                }
            }

            $scope.Paging = function () {
                if (reachedLast) {
                    return false;
                }
                else {
                    index++;
                    GetData(index);
                }
            }
            //#endregion

            //#region grid - menu
            function Add() {
                //debugger;
                var params = {
                    state: 'SettingLookup',
                    role: role,
                    from: 'listdm',
                    paramsearch: $scope.search,
                }
                //console.log(params);
                var add = ListBase.AddPage(params);
            }

            function EditPage() {
                var params = {
                    gridID: gridID,
                    state: 'ListConfigDetail',
                    paramsearch: $scope.search,
                    role: role,
                    from: 'listdm',
                }
                ListBase.EditRowPage(params);
            }

            function DeleteRows() {
                var params = {
                    gridID: gridID,
                    api: '/ConfigAPI/api/Gridview/ListConfigAPI/Delete/',
                    entities: 'listdm',
                    role: role,
                    check_owner: false,
                    field_display: 'title',
                    field_key: 'gridid',
                    check_arise: false,
                    state: 'ListConfig',
                }
                var del = ListBase.DeleteRows(params);
                del.then(function (value) {
                    if (value.data > 0) {
                        TimKiem();
                        var dialog = $dialogs.notify("Thông báo", "Xóa thành công " + value.data + " bản ghi");
                    }
                    if (angular.isDefined(value.message_check_owner) && value.message_check_owner != "") {
                        var dialog = $dialogs.notify("Thông báo", "Bản ghi: " + value.message_check_owner + " của user khác. Không thể xóa");
                    }

                    if (angular.isDefined(value.message_check_arise) && value.message_check_arise != "") {
                        var dialog = $dialogs.notify("Thông báo", "Bản ghi: " + value.message_check_arise + " đã phát sinh dữ liệu. Không thể xóa");
                    }
                });
            }

            function ReLoad() {
                TimKiem();
            }

            function Import() {
                var idlg = $dialogs.create("/Scripts/SYSTEM/Htmls/ImportData.html", "ImportController", {
                    params: {
                        id: 'crmaccount',
                        apiimport: '/CrmAPI/api/Category/AccountAPI/ImportData/',
                        entity: 'listdm'
                    }
                }, { key: true, back: 'static', size: 'md' })
                idlg.result.then(function (kq) {
                    if (kq > 0) {
                        TimKiem();
                    }
                });
            }

            function Export(type) {
                var params = {
                    gridID: gridID,
                    type: type,
                    filename: 'Danh sách khách hàng',
                    search: {
                        index: index,
                        limit: 50,
                        status: $scope.search.trang_thai,
                        key: $scope.search.key,
                        where_adv: $scope.search.sql != "" ? $scope.search.sql + " and " + $scope.searchResult : $scope.searchResult,
                        dm_yn: true,
                        searchDynamic: $scope.search.searchDynamic
                    },
                    configColumn: configColumn,
                    functionName: 'voucher_test',
                }
                ListBase.Export(params);
            }
            //#endregion

            //#region references
            //nhận data từ controller mẹ
            $scope.$on('hideshow_shared', function () {
                configColumn = SystemBase.ColumnShow(sysDataShare.getData('hideshow_shared'));
            });

            $scope.OnClickMenu = function (menu) {
                switch (menu.menuid) {
                    case 'addcampaign': {
                        AddToCampaign(); break;
                    }
                    case 'reload': {
                        ReLoad();
                        break;
                    }
                    case 'add': {
                        //console.log(1);
                        Add();
                        break;
                    }
                    case 'edit': {
                        EditPage();
                        break;
                    }
                    case 'delete': {
                        DeleteRows();
                        break;
                    }
                    case "expExcel": {
                        Export("excel");
                        break;
                    }
                    case "expPDF": {
                        Export("pdf");
                        break;
                    }
                    case "expCSV": {
                        Export("csv");
                        break;
                    }
                    case "import": {
                        Import();
                        break;
                    }
                    case "duplicate": {
                        Duplicate();
                        break;
                    }
                }
                $('#btnNav').trigger('click');
            }

            //key short cut
            $scope.OnKeyDown = function (value) {
                //console.log(value);
                switch (value.keyCode) {
                    case 46: //delete
                        {
                            DeleteRows();
                            break;
                        }
                    case 113: //f2
                        {
                            Add();
                            break;
                        }
                    case 118://f7
                        {
                            EditPage();
                            break;
                        }
                    default:
                        break;

                }
            }

            $scope.$watch(function () { return $cookies.__APPLICATION_LANGUAGE; }, function (newValue) {

                $scope.lang = newValue;
                if (newValue == "vi-VN") {
                    $scope.tieng_viet = true;
                }
                else {
                    $scope.tieng_viet = false;
                }
                //GetLanguage();
            });

            //theo dõi sự thay đổi biến searchResult từ jqgrid để apply kết quả vào query
            $scope.$watch('searchResult', function (newValue, oldValue) {
                //console.log(newValue == oldValue);
                if (angular.isDefined(newValue) && newValue != oldValue) {
                    $scope.searchResult = newValue;
                    TimKiem();
                }
            });
            //#endregion
        }]);

//DETAIL CONFIG LOOKUP
app.controller('ListConfigDetailController',
    ['$scope', '$window', 'CRUDServices', 'SessionService', '$state', '$stateParams', '$dialogs', '$cookies', 'stateStorage', '$timeout', 'growl',
        'SystemBase', 'ngFabForm', '$translatePartialLoader', '$translate', 'CommonFunc', 'jqgridFactory', 'ListBase', 'Page', 'LookUpServiceNew',
        function ($scope, $window, CRUDServices, SessionService, $state, $stateParams, $dialogs, $cookies, stateStorage, $timeout, growl,
            SystemBase, ngFabForm, $translatePartialLoader, $translate, CommonFunc, jqgridFactory, ListBase, Page, LookUpServiceNew) {
            $translatePartialLoader.addPart('ListConfigDetail');
            $translate.refresh();

            Page.setTitleAuto($state.current);
            stateStorage.checkData();
            $scope.EditMode = false;
            //#region KHAI BÁO
            $scope.trang_thai = $stateParams.params.trang_thai;
            console.log($scope.trang_thai);
            $scope.from = $stateParams.params.from;
            $scope.submitted = false;
            $scope.lang = "vi";
            $scope.list_datatable = [];
            var lastSelected = 0;
            var id = 1
            var reachedLast = false;
            var deleteList = [];
            var index = 0;
            $scope.list_alias_table = [];
            $scope.list_table_ref = [];
            $scope.list_joinoption = [
               {
                   form_name: "LEFT JOIN"
               }, {
                   form_name: "INNER JOIN",
               }, {
                   form_name: "RIGHT JOIN",
               }, {
                   form_name: "OUTER JOIN",
               }
            ];
            $scope.ct = [];
            var gridID = "tabgrid";

            $scope.header = []; var header = [];
            $scope.menu = [];
            $scope.totalItems = 0;

            //jqgrid mới
            $scope.myGridOptions = {
                scroll: false,
                datatype: 'local',
                rownumbers: true,
                rownumWidth: 50,
                multiselect: false,
                multiboxonly: false, // chỉ chọn nhiều dòng khi click ô checkbox
                height: 300,
                shrinkToFit: false, //tự động co dãn kích thước các cột
                forceFit: false,
                inlineNav: false,
                gridview: true,
                loadonce: false,
                //các thuộc tính bổ sung cho directive
                outerID: 'grid_ct',
                id: gridID,
                autoBinding: true,
                config_server: true,
                radio_btn: false,
                frozen: true,
                lazy_yn: true,
                pageSize: 50,
                remove_loadding: false,
                contextMenu: true,//rightclick trên grid
                configServer: true, //lấy cấu hình từ server

                actionWidth: 30,
                actionNav: true,
                onSelectRow: OnSelectRow,
                actionsNavOptions: {
                    deleteUsericon: "ui-icon-trash",
                    align: 'center',
                    deleteUsertitle: "Xóa",
                    custom: [
                        {
                            action: "deleteUser",
                            onClick: DeleteRow
                        }
                    ]
                },
                onCellSelect: function (rowid, iCol, cellcontent, event) {

                    if (!angular.isUndefined(event) && $(event.target)[0].type == "checkbox") {
                        console.log(rowid, iCol, cellcontent, event);
                    }
                },
                loadComplete: function () {
                    jqgridFactory.SetLabelRn(gridID);
                    for (var i = 0; i < $scope.header.length; i++) {
                        if ($scope.header[i].event_yn) {
                            jqgridFactory.SetColProp(gridID, $scope.header[i].fieldname, $scope.header[i].event_name, BlurTextbox);
                        }
                    }
                },
                searchLocal: true,
                pivot: false,
                treeGrid: false,
                filterToolbar: true
            };

            function AddRow() {

                if (!id) id = 1;
                $('#' + gridID).jqGrid('addRow', {
                    key: true,
                    rowID: "id".concat(id),
                    initdata: {},
                    position: "last",
                    useDefValues: false,
                    useFormatter: false,
                    addRowParams: {
                        keys: true,
                        oneditfunc: function () { },
                        beforeSaveRow: function (options, rowid, b) {

                            var rowData = jqgridFactory.GetLocalRow(gridID, rowid);
                            check_sl = true;
                            if (check_sl) {
                                return true;
                            } else {
                                growl.error("Bạn chưa nhập các trường dữ liệu bắt buộc");
                                return false;
                            }
                        },
                        //lưu: enter
                        aftersavefunc: function (rowid, response) {

                            var rowData = jqgridFactory.GetLocalRow(gridID, rowid);

                            if (rowData.fieldname != "") {
                                $scope.ct.push(rowData);
                            }

                            $scope.$apply();
                            jqgridFactory.ClearGridData(gridID);
                            lastSelected = 0;
                            jqgridFactory.AddRowData(gridID, $scope.ct);
                            AddRow();
                        },
                        afterrestorefunc: function (rowid) {
                            console.log($scope.ph);
                            AddRow();
                        }
                    }
                });
                $scope.last_row_id = id;
                id++;
            }


            function OnSelectRow(id, state, event) {
                if (!angular.isUndefined(event) && $(event.target).hasClass('cbox')) { }
                else if (!angular.isUndefined(event) && $(event.target).hasClass('ui-icon-trash')) { }
                else {
                    //debugger;
                    if (event) {
                        var old_data = jqgridFactory.GetRowData(gridID, id);
                        //console.log(old_data);
                        jqgridFactory.RestoreRow(gridID, lastSelected);
                        ////console.log(event.target.cellIndex);
                        $('#' + gridID).jqGrid('editRow', id, {   //bắt đầu trang thái  sửa, enable các ô nhập dữ liệu
                            keys: true,
                            focusField: event.target.cellIndex,
                            oneditfunc: function (rowid, options) {
                                $('#' + gridID).setCell(id, 'ma_vt', old_data.ma_vt);
                            },
                            beforeSaveRow: function (options, rowid, b) {

                            },
                            //lưu dữ liệu sau khi sửa
                            aftersavefunc: function (rowid, response) {
                                //debugger;
                                var newData = jqgridFactory.GetLocalRow(gridID, rowid);
                                //cap nhat giá trị trên grid
                                //đổi khóa chính
                                if (newData.ma_widget != old_data.ma_widget) {
                                    //xóa vt có mã cũ trong danh sách đi
                                    var _index = JSON.CheckExistInArray('ma_widget', old_data.ma_widget, $scope.ct);
                                    if (_index > -1) {
                                        //nếu trạng thái là sửa thì push vt này vào ds bị xóa
                                        if ($scope.trang_thai == "edit" && $scope.ct[_index].oid) {
                                            $scope.ct[_index].action_type = "D";
                                            deleteList.push($scope.ct[_index]);
                                        }
                                        //xóa vt khỏi ds trên grid
                                        $scope.ct.splice(_index, 1);
                                    }
                                    //ktra vt mới đã tồn tại trong ds vt chưa
                                    _index = JSON.CheckExistInArray('ma_widget', newData.ma_widget, $scope.ct);
                                    //nếu có -> cập nhật số lượng, tiền theo số lượng, tiền mới
                                    if (_index > -1) {
                                        if ($scope.trang_thai == "edit" && $scope.ct[_index].oid) {
                                            $scope.ct[_index].action_type = "E";
                                        }
                                    }
                                        //nếu chưa có -> push vào ds vt trên grid
                                    else {
                                        delete newData.ma_widget; //remove stt_rec để vt này thành thêm mới
                                        $scope.ct.push(newData);
                                    }
                                }
                                    //không đổi khóa chính
                                else {
                                    //cap nhat giá trị trên grid
                                    for (var i = 0; i < $scope.ct.length; i++) {
                                        if (newData.ma_widget == $scope.ct[i].ma_widget) {
                                            if ($scope.trang_thai == "edit" && $scope.ct[i].oid) {
                                                $scope.ct[i].action_type = "E";
                                            }
                                            break;
                                        }
                                    }
                                }

                                $scope.$apply();
                                jqgridFactory.ClearGridData(gridID);
                                lastSelected = 0;
                                jqgridFactory.AddRowData(gridID, $scope.ct);
                                AddRow();
                            }
                        });
                        lastSelected = id;
                    }
                }
            }

            function BlurTextbox(e) {
                // console.log(e);
                var id = e.target.id;   //id của ô textbox
                var rowID = e.target.id.split("_")[0];      //id của row trên grid
                var el_id = e.target.id.substring(rowID.length + 1, e.target.id.length);
                var rowData = jqgridFactory.GetLocalRow(gridID, rowID);
                //có giá trị mới xử lý

                if (e.target.value != "") {
                    switch (el_id) {
                        case 'ten_widget': {
                            //truyền dữ liệu về control lookup
                            var passData = {
                                keyword: e.target.value,
                                lazyload_yn: true,
                                multiselect_yn: true,
                                keyId: 'ma_widget',
                                pkey: 'ma_widget',
                                condition: {
                                    selected: $scope.ct
                                },
                                table_arr: [{
                                    gridid: 'LK_WIDGET_ITEM',
                                    name: 'Danh sách widget'
                                }],
                            };

                            var check = JSON.CheckExistInArray(passData.keyId, e.target.value, $scope.ct);

                            //mã chưa có trong mảng đã chọn thì mới bật lookup
                            if (check < 0) {
                                var RESULT = LookUpServiceNew.LookUp(passData);
                                if (RESULT != null)
                                    RESULT.then(function (vt) {

                                        //trường hợp chọn nhiều: 
                                        //duyệt ds trả về(bao gồm cả những bản ghi đã chọn từ trước + bản ghi mới)
                                        //kiểm tra bản ghi có nằm trong ds đã chọn không(ds trên grid): nếu không có -> add vào 1 ds khác để xử lý
                                        var result = [];
                                        angular.forEach(vt, function (item) {
                                            if (item != '') {
                                                var check = JSON.CheckExistInArray(passData.keyId, item[passData.keyId], $scope.ct);
                                                if (check < 0)
                                                    result = result.concat(item);
                                            }
                                        });

                                        if (!angular.isUndefined(result)) {
                                            if (result.length > 1) {

                                                for (var i = 0; i < result.length; i++) {
                                                    result[i].chieu_rong = "3";
                                                    result[i].chieu_cao = "1";
                                                }
                                                //them du lieu tren modal xuong $scope
                                                $scope.ct = $scope.ct.concat(result); //ds sản phẩm trên grid

                                                //HIỂN THỊ DỮ LIỆU LÊN GIAO DIỆN
                                                lastSelected = 0;
                                                jqgridFactory.ClearGridData(gridID);
                                                jqgridFactory.AddRowData(gridID, $scope.ct);
                                                AddRow();
                                                jqgridFactory.SetGridWidth(gridID, 'grid_ct');
                                            }
                                            else if (result.length == 1) {

                                                var input = $('#' + rowID).next('input').first().context.activeElement.attributes;//.context.activeElement.attributes.id.nodeValue
                                                ////console.log(input.id);
                                                if (!angular.isUndefined(input.id)) {
                                                    $('#' + input.id.nodeValue).focus();
                                                }
                                                //set giá trị lookup cho local data
                                                var rowData = jqgridFactory.GetLocalRow(gridID, rowID);
                                                rowData.ma_widget = result[0].ma_widget;
                                                rowData.ten_widget = result[0].ten_widget;
                                                rowData.status = true;
                                                rowData.params_default = result[0].params_default;
                                                rowData.params_type = result[0].params_type;
                                                rowData.module = Module;
                                                //#region set giá trị cho dạng select

                                                var arr_tmp = [];
                                                if (result[0].type_chart == '')
                                                    $('#' + rowID + "_type_chart").addClass('hidden');
                                                else {
                                                    for (var i = 0; i < $scope.header.length; i++) {
                                                        if ($scope.header[i].fieldname === 'type_chart') {
                                                            arr_tmp = JSON.parse($scope.header[i].sel_values);
                                                            break;
                                                        }
                                                    }

                                                    for (var i = 0; i < arr_tmp.length; i++) {
                                                        if (arr_tmp[i].key_value.length == (result[0].type_chart).length) {
                                                            $('#' + rowID + "_type_chart").val(arr_tmp[i].key_value);
                                                            rowData.type_chart = arr_tmp[i].key_value;
                                                            break;
                                                        }
                                                    }
                                                }

                                                ////////////////
                                                var arr_tmp = [];
                                                for (var i = 0; i < $scope.header.length; i++) {
                                                    if ($scope.header[i].fieldname === 'wid_sizex') {
                                                        arr_tmp = JSON.parse($scope.header[i].sel_values);
                                                        break;
                                                    }
                                                }

                                                $('#' + rowID + "_wid_sizex").val(arr_tmp[1].key_value);
                                                rowData.chieu_rong = arr_tmp[1].key_value;
                                                ////////////////
                                                for (var i = 0; i < $scope.header.length; i++) {
                                                    if ($scope.header[i].fieldname === 'wid_sizey') {
                                                        arr_tmp = JSON.parse($scope.header[i].sel_values);
                                                        break;
                                                    }
                                                }
                                                $('#' + rowID + "_wid_sizey").val(arr_tmp[1].key_value);
                                                rowData.chieu_cao = arr_tmp[1].key_value;
                                                ////
                                                setTimeout(function () {
                                                    $scope.$apply;
                                                }, 1000);

                                                //#endregion

                                                //#region gán giá trị lookup cho các ô textbox
                                                $('#' + rowID + "_ma_widget").val(result[0].ma_widget);
                                                $('#' + rowID + "_status").attr('checked', 'checked');
                                                //#endregion

                                                //region set giá trị cho các ô label
                                                $("#" + gridID).jqGrid('setCell', rowID, "ten_widget", result[0].ten_widget);

                                                //#endregion

                                                //jqgridFactory.AddRowData(gridID, [rowData]);
                                                $scope.ct = $scope.ct.concat(rowData); //ds sản phẩm trên grid
                                                AddRow();
                                                jqgridFactory.SetGridWidth(gridID, 'grid_ct');
                                            }
                                        }
                                    });
                            }
                            break;
                        }
                        case 'tablename': {
                            console.log(el_id);
                            console.log(rowData);
                            console.log($("#" + gridID).jqGrid('getGridParam', "colModel"));
                        }
                    }
                } else {
                    switch (el_id) {

                    }
                }
            }
            //#endregion

            //#region DIRECTIVE PARAMS
            //truyền các tham số cần thiết về directive để xử lý thiết lập
            $scope.passData = {
                txtHeader: 'CHI TIẾT',
                propertyShow: 'gridid',
                add_yn: $stateParams.params.trang_thai == 'add' || !$stateParams.params.trang_thai,
                params: $stateParams.params,
                editOnPage: true,
                validClick: { form: 'rowForm', gridID: '', scope: $scope },
                command: {
                    gridid: 'SYS_LISTGRIDCONFIG', //khai báo menuid: header và menu theo phân quyền
                    state: 'ListConfigDetail',
                    role_yn: false,
                }

            };
            //nhận giá trị cấu hình từ directive trả về
            (function first() {
                $scope.resultData = function (item) {
                    //loại bỏ các kí tự ko cần thiết trên thanh tiêu đề
                    for (var i = 0; i < item.header.length; i++) {
                        item.header[i].fieldcaption = item.header[i].fieldcaption.replace('SYS_LISTGRIDCONFIG_', '');
                        item.header[i].fieldcaption = item.header[i].fieldcaption.replace('ListConfigDetail_', '');
                        item.header[i].fieldcaption = item.header[i].fieldcaption.replace('_yn', '');//
                    }
                    $scope.header_temp = angular.copy(item.header);
                    GetDetail();
                }
                ////
                if ($stateParams.params != "") {
                    $scope.search = $stateParams.params.paramsearch;
                };
            })();

            //#endregion


            //#region CHẠY KHI LOAD FORM
            function GetDetail() {
                if ($scope.trang_thai == "edit") {
                    var kq = CRUDServices.getdata({ id: $stateParams.params.ct.gridid },
                          '/ConfigAPI/api/System/ListConfigAPI/GetById/', 'GET');
                    kq.then(function (value) {
                        $scope.ph = (value.data.ph).length > 0 ? (value.data.ph)[0] : {};
                        $scope.ph_tblfrom_arr = $scope.ph.tbl_from.split(' ');
                        $scope.ph.alias = $scope.ph_tblfrom_arr[$scope.ph_tblfrom_arr.length - 1];
                        $scope.ph.tbl_from = $scope.ph_tblfrom_arr[0];
                        $scope.ph.pkey = $scope.ph.pkey.split('.')[1];
                        $scope.ph.order_by = $scope.ph.order_by.split('.')[1];

                        console.log($scope.ph);

                        $scope.list_table_ref = value.data.sys_listjoin.length > 0 ? value.data.sys_listjoin : [];

                        $scope.list_alias_table = [
                           {
                               alias: $scope.ph.alias,
                               form_name: $scope.ph.tbl_from
                           }
                        ];
                        for (var i = 0; i < $scope.list_table_ref.length; i++) {
                            $scope.list_alias_table.push({
                                alias: $scope.list_table_ref[i].alias_left,
                                form_name: $scope.list_table_ref[i].table_name,
                            });
                        }

                        var sel_values = '[';
                        for (var j = 0; j < $scope.list_alias_table.length; j++) {
                            sel_values = sel_values + '{"key_value":"' + $scope.list_alias_table[j].alias + '",' +
                                '"display_value":"' + $scope.list_alias_table[j].form_name + '",' +
                                '"search_value":"' + $scope.list_alias_table[j].form_name + '"},';
                        }
                        sel_values = sel_values.slice(0, -1);
                        sel_values += ']';

                        for (var i = 0; i < $scope.header_temp.length; i++) {
                            if ($scope.header_temp[i].style == 'SELECT' && $scope.header_temp[i].fieldname == "tablename") {
                                $scope.header_temp[i].sel_values = sel_values;
                                break;
                            }
                        }

                        $scope.header = angular.copy($scope.header_temp);

                        setTimeout(function () {
                            $scope.$apply();
                            $scope.ct = value.data.sys_gridconfig.length > 0 ? value.data.sys_gridconfig : [];
                        }, 1000);

                        var data = {
                            table: $scope.ph.tbl_from
                        };
                        var kq = ListBase.GetData(data, '/ConfigAPI/api/Gridview/ListConfigAPI/GetListColumnByTable/', 'GET');
                        kq.then(function (value) {
                            $scope.list_colmain_table = value;
                            $scope.list_colmain_table_first = value;
                        })

                        var kq = ListBase.GetData({ table: '' }, '/ConfigAPI/api/Gridview/ListConfigAPI/GetListTable/', 'GET');
                        kq.then(function (value) {
                            $scope.list_datatable = value;
                        })
                    });
                } else {
                    $scope.EditMode = true;
                    $scope.trang_thai == "add"
                    var kq = CRUDServices.getdata('', '/ConfigAPI/api/System/ListConfigAPI/GetNew/', 'GET');
                    kq.then(function (value) {
                        $scope.ph = JSON.parse(value.data.ctdm);
                        $scope.ph.alias = "a";
                        $scope.list_alias_table = [
                          {
                              alias: $scope.ph.alias,
                              form_name: ""
                          }
                        ];
                        $scope.header = angular.copy($scope.header_temp);
                        var kq = ListBase.GetData({ table: '' }, '/ConfigAPI/api/Gridview/ListConfigAPI/GetListTable/', 'GET');
                        kq.then(function (value) {
                            $scope.list_datatable = value;
                        })
                        $scope.trang_thai = "add";
                        $scope.EditMode = true;

                        jqgridFactory.SetGridWidth(gridID, 'grid_ct');
                    });
                }
            }

            function DeleteRow(options) {
                //chỉ xóa các dòng có id là kiểu số
                if ((options.rowid)) {
                    var rowData = jqgridFactory.GetLocalRow(gridID, options.rowid);
                    //xóa dữ liệu trong dsnv
                    for (var i = $scope.ct.length - 1; i > -1; i--) {
                        if ($scope.ct[i].fieldname === rowData.fieldname) {
                            //nếu trạng thái = sửa và dòng này là dòng dữ liệu cũ (có stt_rec) thì push dòng đc xóa vào danh sách xóa
                            if ($scope.trang_thai == "edit" && $scope.ct[i].oid) {
                                $scope.ct[i].action_type = "D";
                                deleteList.push($scope.ct[i]);
                            }
                            $scope.ct.splice(i, 1);
                            break;
                        }
                    }

                    $scope.$apply();
                    //xóa dòng trên grid cha
                    jqgridFactory.DelRowData(gridID, options.rowid);
                }

            }

            //#endregion

            //#region FUNCTION CHỨC NĂNG TRÊN MENU

            function Reload() {
                growl.success("reload");
            }

            function Edit() {
                $scope.trang_thai = "edit";
                $scope.EditMode = true;

                if ($("#" + gridID + " tr[editable = 1]").length <= 1) {
                    setTimeout(function () {
                        $window.dispatchEvent(new Event("resize"));
                        AddRow();
                    }, 500);
                }
            }

            function Save(closed) {
                growl.success("save");
            }

            function Cancel() {
                $state.go('ListConfig', {
                    params: {
                        paramsearch: $stateParams.params.search
                    }
                });

            }
            //#endregion

            //#region REFERENCE
            $scope.OnClickMenu = function (menu) {

                switch (menu.menuid) {
                    case 'reload': {
                        Reload();
                        break;
                    }
                    case 'edit': {
                        Edit();
                        break;
                    }
                    case 'save': {
                        $scope.SaveConfig();
                        break;
                    }
                    case 'cancel': {
                        Cancel();
                        break;
                    }
                    default: break;
                }
            }

            $scope.click_tab = 0;
            $scope.showTab = function () {

                setTimeout(function () {
                    $window.dispatchEvent(new Event("resize"));
                    if ($scope.click_tab == 0) {
                        if ($scope.EditMode || $scope.trang_thai == 'add')
                            AddRow();
                    }
                    $scope.click_tab += 1;

                }, 1500);
            }

            //sự kiện thêm một bảng ref mới đề left join...
            $scope.SaveAddTable = function () {

                if ($scope.list_alias_table.length > 0) {

                    var last = $scope.list_alias_table[$scope.list_alias_table.length - 1];
                    var new_alias = String.fromCharCode(last.alias.charCodeAt(last.alias) + 1);
                    $scope.list_alias_table.push({
                        alias: new_alias,
                        form_name: ''
                    });
                } else {
                    $scope.list_alias_table.push({
                        alias: "a",
                        form_name: ''
                    });
                }
                //console.log($scope.list_alias_table);
                $scope.list_table_ref.push(
                 {
                     gridid: $scope.ph.gridid,
                     table_name: '',
                     alias_left: new_alias,
                     col_left: '',
                     type_join: $scope.list_joinoption[0].form_name,
                     alias_right: $scope.list_alias_table[0].alias,
                     col_right: '',
                     where_def: '',
                     action_type: 'A'
                 }
               );
            }

            $scope.RemoveTable = function (table) {
                $scope.list_table_ref.splice($scope.list_table_ref.indexOf(table), 1);
                var index = 0;
                for (var i = 0; i < $scope.list_alias_table.length; i++) {
                    if ($scope.list_alias_table[i].alias == table.alias_left) {
                        index = i;
                        break;
                    }
                };
                if (index > 0) $scope.list_alias_table.splice(index, 1);

                if ($scope.list_table_ref.length == 0) {
                    $scope.list_alias_table = [
                       {
                           alias: $scope.ph.alias,
                           form_name: $scope.ph.tbl_from
                       }
                    ];
                }
            }

            //lưu cấu hình sau khi chỉnh sửa
            $scope.SaveConfig = function () {
                var res = ngFabForm.submit({ form: 'rowForm', gridID: gridID, scope: $scope });

                if (res.result) {

                    $scope.gridconfig = [];
                    $scope.listjoin = [];
                    var style = '';
                    var index_pos = 0;
                    for (var i = 0; i < $scope.ct.length; i++) {
                        if (!$scope.ct[i].oid) {
                            $scope.ct[i].gridid = $scope.ph.gridid;
                            $scope.ct[i].action_type = "A";
                        } else {
                            $scope.ct[i].action_type = "E";
                        }
                    }

                    for (var i = 0; i < $scope.list_table_ref.length; i++) {
                        if ($scope.list_table_ref[i].table_name != '') {
                            $scope.listjoin.push($scope.list_table_ref[i]);
                        }
                    }

                    ///update lại giá trị chính xác cho các cột: pkey, order_by
                    $scope.ph.tbl_from = $scope.ph.tbl_from + ' AS ' + $scope.ph.alias;
                    $scope.ph.pkey = $scope.ph.alias + '.' + $scope.ph.pkey;
                    $scope.ph.order_by = $scope.ph.alias + '.' + $scope.ph.order_by;

                    var data = {
                        listconfig: $scope.ph,
                        gridconfig: $scope.ct.concat(deleteList),
                        listjoin: $scope.listjoin,
                    };
                    console.log(data);
                    if ($scope.trang_thai == "edit") {
                        var kq = ListBase.SaveEdit('/ConfigAPI/api/Gridview/ListConfigAPI/SaveEdit/', data, $scope.ph);
                        kq.then(function (value) {
                            growl.success("Cập nhật thành công");
                        });
                    }
                    else {
                        console.log($scope.last_row_id);
                        jqgridFactory.DelRowData('id' + $scope.last_row_id);

                        var kq = ListBase.SaveAdd('/ConfigAPI/api/Gridview/ListConfigAPI/SaveAdd/', data);
                        kq.then(function (value) {
                            $scope.trang_thai = "edit";
                            $stateParams.params.ct = $scope.ph;
                            $scope.EditMode = false;

                            GetDetail();

                            growl.success("Thêm mới thành công");
                        });
                    }
                }
                else {
                    growl.error("Chưa điền đầy đủ thông tin cần thiết!!!")
                }
            }

            $scope.getListColumn = function (table) {

                for (var i = 0; i < $scope.list_alias_table.length; i++) {
                    if ($scope.list_alias_table[i].alias == 'a') {
                        $scope.list_alias_table[i].form_name = table;
                    }
                }

                var kq = ListBase.GetData({
                    table: table
                }, '/ConfigAPI/api/Gridview/ListConfigAPI/GetPrimaryKeyOfTable/', 'GET');
                kq.then(function (value) {
                    if (value.length > 0) {
                        $scope.ph.pkey = value[0].column_name;
                        $scope.ph.order_by = value[0].column_name;
                    }
                    else {
                        $scope.ph.pkey = $scope.list_colmain_table[0].column_name;
                        $scope.ph.order_by = $scope.list_colmain_table[0].column_name;
                    }
                })
            }

            //ds các cột trong bảng thành phần
            $scope.getListColumnRef = function (table) {
                console.log($scope.list_alias_table);
                var last = $scope.list_alias_table[$scope.list_alias_table.length - 1];
                var new_alias = String.fromCharCode(last.alias.charCodeAt(last.alias) + 1);

                $scope.list_alias_table[$scope.list_alias_table.length - 1].form_name = table.table_name;
                $scope.list_alias_table[$scope.list_alias_table.length - 1].alias = new_alias;

                var data = {
                    table: table.table_name
                };
                var text = '';
                var kq = ListBase.GetData(data, '/ConfigAPI/api/Gridview/ListConfigAPI/GetListColumnByTable/', 'GET');
                kq.then(function (value) {
                    for (var i = 0; i < value.length; i++) {
                        text += value[i].field_root + ', ';
                    }

                    setTimeout(function () {
                        table.col_list_text = text;
                        $scope.$apply();
                    }, 1000);
                });

            }


            //theo dõi sự thay đổi biến searchResult từ jqgrid để apply tổng số bản ghi sau khi search
            $scope.$watch('searchResult', function (newValue, oldValue) {
                //console.log(newValue == oldValue);
                if (angular.isDefined(newValue) && newValue != oldValue) {
                    $scope.searchResult = newValue;
                    $scope.totalItems = $scope.searchResult;
                }
            });
            //#endregion

        }]);
;

//ADD NEW CONFIG LOOKUP
app.controller('ListConfigAddController',
   ['$scope', '$location', '$stateParams', 'SessionService', 'CRUDServices', '$cookies', '$translate',
       '$window', '$state', '$dialogs', 'growl', 'sysDataShare', 'ListBase',
       function ($scope, $location, $stateParams, SessionService, CRUDServices, $cookies, $translate,
           $window, $state, $dialogs, growl, sysDataShare, ListBase) {

           //#region KHAI BÁO
           $scope.trang_thai = $stateParams.params.trang_thai;
           //console.log($scope.trang_thai);
           $scope.from = $stateParams.params.from;
           $scope.submitted = false;

           //#endregion

           //#region DIRECTIVE PARAMS
           //truyền các tham số cần thiết về directive để xử lý thiết lập
           $scope.passData = {
               titleText: 'TẠO MỚI', //tiêu d?  
               propertyShow: 'so_ct',
               add_yn: $stateParams.params.trang_thai == 'add' || !$stateParams.params.trang_thai,
               params: $stateParams.params, //load l?i d? li?u v?a tìm ki?m n?u v?a t? overview b?n ghi tr? ra
               validClick: { form: 'rowForm', gridID: '', scope: $scope },
               command: {
                   gridid: 'ListConfigDetail', //khai báo menuid: header và menu theo phân quyền
                   state: 'ListConfigDetail',
                   role_yn: false,
               }

           };
           //nhận giá trị cấu hình từ directive trả về
           (function first() {
               $scope.resultData = function (item) {
                   //console.log(item);
                   $scope.header = angular.copy(item.header);
                   //console.log($scope.header);
                   if ($scope.header.length > 0) {
                       //LoadData(1);
                   }
               }
               ////
               if ($stateParams.params != "") {
                   $scope.search = $stateParams.params.paramsearch;
               };
           })();

           //#endregion

           //#region CHẠY KHI LOAD FORM

           //#endregion

           $scope.lookup = {
               gridid: '',
               tbl_from: '',
               title: '',
               order_by: '',
               ma_ct: '',
               pkey: '',
               alias: 'a',
           }
           $scope.list_alias_table = [
               {
                   alias: $scope.lookup.alias,
                   form_name: $scope.lookup.tbl_from
               }
           ];

           $scope.list_joinoption = [
             {
                 form_name: "LEFT JOIN"
             },
           {
               form_name: "INNER JOIN",
           },
            {
                form_name: "RIGHT JOIN",
            },
              {
                  form_name: "OUTER JOIN",
              }
           ];
           $scope.list_table_ref = [];

           $scope.list_datatable = [];
           $scope.list_options_setup = [
              {
                  id: 1,
                  form_name: "Danh mục"
              },
              {
                  id: 2,
                  form_name: "LookUp",
              }
           ];
           $scope.table_ins = $scope.list_options_setup[0];
           $scope.prefix = 'LT_';
           //$scope.ds_languages = JSON.parse(localStorage.listlang);
           InitLoad();
           //các function load lần đầu
           function InitLoad() {
               var data = {
                   table: ''
               };

               var kq = ListBase.GetData(data, '/ConfigAPI/api/Gridview/ListConfigAPI/GetListTable/', 'GET');
               kq.then(function (value) {
                   $scope.list_datatable = value;

               })
           }
           $scope.list_table_selected = '';

           $scope.changeOptions = function (option) {
               console.log(option);
               if (option.id == 1) {
                   $scope.prefix = 'LT_';
               }
               else {
                   $scope.prefix = 'LK_';
               }

           }

           $scope.getListColumn = function (table) {

               for (var i = 0; i < $scope.list_alias_table.length; i++) {
                   if ($scope.list_alias_table[i].alias == 'a') {
                       $scope.list_alias_table[i].form_name = table.table_name;
                   }
               }
               var data = {
                   table: table.table_name
               };
               var kq = ListBase.GetData(data, '/ConfigAPI/api/Gridview/ListConfigAPI/GetListColumnByTable/', 'GET');
               kq.then(function (value) {
                   $scope.list_colmain_table = value;
               })

               var kq = ListBase.GetData(data, '/ConfigAPI/api/Gridview/ListConfigAPI/GetPrimaryKeyOfTable/', 'GET');
               kq.then(function (value) {
                   if (value.length > 0) {
                       $scope.lookup.pkey = value[0].column_name;
                       $scope.lookup.order_by = value[0].column_name;
                   }
                   else {
                       $scope.lookup.pkey = $scope.list_colmain_table[0].column_name;
                       $scope.lookup.order_by = $scope.list_colmain_table[0].column_name;
                   }
               })
           }

           //ds các cột trong bảng thành phần
           $scope.getListColumnRef = function (table) {

               var last = $scope.list_alias_table[$scope.list_alias_table.length - 2];
               var new_alias = String.fromCharCode(last.alias.charCodeAt(last.alias) + 1);

               $scope.list_alias_table[$scope.list_alias_table.length - 1].form_name = table.table_name;
               $scope.list_alias_table[$scope.list_alias_table.length - 1].alias = new_alias;

               var data = {
                   table: table.table_name
               };
               var text = '';
               var kq = ListBase.GetData(data, '/ConfigAPI/api/Gridview/ListConfigAPI/GetListColumnByTable/', 'GET');
               kq.then(function (value) {
                   for (var i = 0; i < value.length; i++) {
                       text += value[i].field_root + ', ';
                   }

                   setTimeout(function () {
                       table.col_list_text = text;
                       console.log(table.col_list_text);
                       $scope.$apply();
                   }, 1000);
               });

           }


           //sau khi add thành công 1 bảng ref vào mảng, thì tăng index của alias trong ds $scope.list_alias_table
           $scope.SaveAddTable = function () {
               var last = $scope.list_alias_table[$scope.list_alias_table.length - 1];
               var new_alias = String.fromCharCode(last.alias.charCodeAt(last.alias) + 1);
               $scope.list_alias_table.push({
                   alias: new_alias,
                   form_name: ''
               });
               //console.log($scope.list_alias_table);
               $scope.list_table_ref.push(
                {
                    gridid: $scope.lookup.gridid,
                    table_name: '',
                    alias_left: new_alias,
                    col_left: '',
                    type_join: $scope.list_joinoption[0],
                    alias_right: $scope.list_alias_table[0],
                    col_right: '',
                    where_def: '',
                }
              );
           }


           $scope.RemoveTable = function (table) {
               $scope.list_table_ref.splice($scope.list_table_ref.indexOf(table), 1);
               var index = 0;
               for (var i = 0; i < $scope.list_alias_table.length; i++) {
                   if ($scope.list_alias_table[i].alias == table.alias_left) {
                       index = i;
                       break;
                   }
               };
               if (index > 0) $scope.list_alias_table.splice(index, 1);

               if ($scope.list_table_ref.length == 0) {
                   $scope.list_alias_table = [
                      {
                          alias: $scope.lookup.alias,
                          form_name: $scope.lookup.tbl_from
                      }
                   ];
               }
           }

           //lưu cấu hình lookup
           $scope.SaveConfig = function () {

               if ($scope.table_ins != null) {
                   $scope.gridconfig = [];
                   $scope.listjoin = [];
                   var style = '';
                   var index_pos = 0;
                   $scope.lookup.gridid = $scope.prefix + $scope.lookup.gridid;
                   for (var i = 0; i < $scope.list_colmain_table.length; i++) {
                       style = '';
                       if ($scope.list_colmain_table[i].check_yn) {
                           if ($scope.list_colmain_table[i].data_type == 'date') {
                               style = 'FORMAT_DATE_GRID';
                           }
                           else if ($scope.list_colmain_table[i].data_type == 'bigint' ||
                                   $scope.list_colmain_table[i].data_type == 'numeric' ||
                                   $scope.list_colmain_table[i].data_type == 'smallint') {
                               style = 'FORMAT_SL';
                           }
                           else style = '';

                           //"bigint"
                           $scope.gridconfig.push({
                               gridid: $scope.lookup.gridid,
                               fieldname: $scope.list_colmain_table[i].fieldname,
                               field_root: $scope.list_colmain_table[i].field_root,
                               tablename: $scope.lookup.tbl_from.table_name,
                               table_as: $scope.lookup.alias,
                               fieldposition: i,
                               fieldcaption: $scope.list_colmain_table[i].column_name,
                               visible: 1,
                               style: style,
                               width_web: 150,
                               inwhere_yn: true,
                               advance_search_yn: true,
                               action_type: 'A',
                           });
                           index_pos = i;
                       }
                   }
                   ///
                   console.log($scope.list_table_ref);
                   for (var i = 0; i < $scope.list_table_ref.length; i++) {
                       if ($scope.list_table_ref[i].table_name != '') {
                           $scope.listjoin.push({
                               gridid: $scope.lookup.gridid,
                               table_name: $scope.list_table_ref[i].table_name.table_name,
                               alias_left: $scope.list_table_ref[i].alias_left,
                               col_left: $scope.list_table_ref[i].col_left,
                               type_join: $scope.list_table_ref[i].type_join.form_name,
                               alias_right: $scope.list_table_ref[i].alias_right.form_name,
                               col_right: $scope.list_table_ref[i].col_right,
                               where_def: $scope.list_table_ref[i].where_def,
                               action_type: 'A',
                           });

                           //nếu col_select <> '' thì add thêm vào danh sách insert vào bảng sys_gridconfig

                           if (JSON.toString($scope.list_table_ref[i].col_select) != '') {
                               var arr_col = $scope.list_table_ref[i].col_select.split(',');
                               for (var j = 0; j < arr_col.length; j++) {
                                   //xử lý trường hợp sử dụng alias
                                   arr_col[j] = arr_col[j].toUpperCase();
                                   var col_alias = (arr_col[j].split(' AS '));
                                   if (arr_col[j].includes('AS')) {
                                       $scope.gridconfig.push({
                                           gridid: $scope.lookup.gridid,
                                           fieldname: col_alias[1].toLowerCase().trim(),
                                           field_root: col_alias[0].toLowerCase().trim(),
                                           tablename: $scope.list_table_ref[i].table_name.table_name,
                                           table_as: $scope.list_table_ref[i].alias_left,
                                           fieldposition: index_pos + j,
                                           fieldcaption: arr_col[j],
                                           visible: 1,
                                           style: '',
                                           width_web: 150,
                                           inwhere_yn: true,
                                           action_type: 'A',
                                       });
                                   }
                                   else {
                                       $scope.gridconfig.push({
                                           gridid: $scope.lookup.gridid,
                                           fieldname: arr_col[j].toLowerCase().trim(),
                                           field_root: arr_col[j].toLowerCase().trim(),
                                           tablename: $scope.list_table_ref[i].table_name.table_name,
                                           table_as: $scope.list_table_ref[i].alias_left,
                                           fieldposition: index_pos + j,
                                           fieldcaption: arr_col[j],
                                           visible: 1,
                                           style: '',
                                           width_web: 150,
                                           inwhere_yn: true,
                                           advance_search_yn: true,
                                           action_type: 'A',
                                       });
                                   }

                               }
                           }
                       }
                   }

                   ///update lại giá trị chính xác cho các cột: pkey, order_by
                   $scope.lookup.tbl_from = $scope.lookup.tbl_from.table_name + ' AS ' + $scope.lookup.alias;
                   $scope.lookup.pkey = $scope.lookup.alias + '.' + $scope.lookup.pkey;
                   $scope.lookup.order_by = $scope.lookup.alias + '.' + $scope.lookup.order_by;
                   if ($scope.gridconfig.length == 0) {
                       growl.error("Chưa chọn danh sách cột hiển thị");
                   } else {
                       var data = {
                           listconfig: $scope.lookup,
                           gridconfig: $scope.gridconfig,
                           listjoin: $scope.listjoin,
                       };
                       console.log(data);
                       var kq = ListBase.SaveAdd('/ConfigAPI/api/Gridview/ListConfigAPI/SaveAdd/', data);
                       kq.then(function (value) {
                           growl.success("Thêm cấu hình thành công");
                           $scope.list_colmain_table = [];
                           document.getElementById("rowForm").reset();

                       });
                   }
               }
               else growl.error("Chưa chọn loại cấu hình");
           }

           //#region FUNCTION CHỨC NĂNG TRÊN MENU
           function Reload() {
               growl.success("reload");
           }

           function Cancel() {
               console.log($stateParams.params);
               if ($stateParams.params.search)
                   $state.go('ListConfig', {
                       params: {
                           paramsearch: $stateParams.params.search
                       }
                   });
               else
                   $state.go('ListConfig', {
                       params: {
                           paramsearch: {}
                       }
                   });

           }



           //#endregion

           //#region references
           //nhận data từ controller mẹ
           $scope.$on('hideshow_shared', function () {
               configColumn = SystemBase.ColumnShow(sysDataShare.getData('hideshow_shared'));
           });

           $scope.OnClickMenu = function (menu) {
               switch (menu.menuid) {
                   case 'addcampaign': {
                       AddToCampaign(); break;
                   }
                   case 'reload': {
                       ReLoad();
                       break;
                   }
                   case 'save': {

                       $scope.SaveConfig();
                       break;
                   }
                   case 'cancel': {
                       Cancel();
                       break;
                   }
                   case 'delete': {
                       DeleteRows();
                       break;
                   }
                   case "expExcel": {
                       Export("excel");
                       break;
                   }
                   case "expPDF": {
                       Export("pdf");
                       break;
                   }
                   case "expCSV": {
                       Export("csv");
                       break;
                   }
                   case "import": {
                       Import();
                       break;
                   }
                   case "duplicate": {
                       Duplicate();
                       break;
                   }
               }
               $('#btnNav').trigger('click');
           }

           //key short cut
           $scope.OnKeyDown = function (value) {
               //console.log(value);
               switch (value.keyCode) {
                   case 46: //delete
                       {
                           DeleteRows();
                           break;
                       }
                   case 113: //f2
                       {
                           Add();
                           break;
                       }
                   case 118://f7
                       {
                           EditPage();
                           break;
                       }
                   default:
                       break;

               }
           }


           //theo dõi sự thay đổi biến searchResult từ jqgrid để apply kết quả vào query
           $scope.$watch('searchResult', function (newValue, oldValue) {
               //console.log(newValue == oldValue);
               if (angular.isDefined(newValue) && newValue != oldValue) {
                   $scope.searchResult = newValue;
                   TimKiem();
               }
           });
           //#endregion
       }]);
;
